(390312,43368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gekkó csípős chilit ..., amikor hirtelen tűz csapott ki a szájából. Katasztrófa!'::text,'evett'::text,'evett'::text,'megevett'::text,'A gekkó csípős chilit evett, amikor hirtelen tűz csapott ki a szájából. Katasztrófa!'::text),
(390387,43377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, der Gecko ... gerade Feuer, weil die Chilis so scharf sind.'::text,'speit'::text,'speit'::text,'hat gespien'::text,'Nee, der Gecko speit gerade Feuer, weil die Chilis so scharf sind.'::text),
(390391,43377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, гекон зараз ... вогнем, бо чилі такі гострі.'::text,'дихає'::text,'дихає'::text,'дихав'::text,'Не, гекон зараз дихає вогнем, бо чилі такі гострі.'::text),
(390390,43377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, el geco ... fuego ahora mismo porque los chiles pican muchísimo.'::text,'está echando'::text,'echa'::text,'ha echado'::text,'Qué va, el geco está echando fuego ahora mismo porque los chiles pican muchísimo.'::text),
(390389,43377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, le gecko ... du feu là, parce que les piments sont trop forts.'::text,'crache'::text,'crache'::text,'a craché'::text,'Nan, le gecko crache du feu là, parce que les piments sont trop forts.'::text),
(390392,43377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok ya, geko şu an ateş ..., çünkü biberler çok acı.'::text,'püskürüyor'::text,'püskürür'::text,'püskürdü'::text,'Yok ya, geko şu an ateş püskürüyor, çünkü biberler çok acı.'::text),
(390393,43377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dehogy, a gekkó épp tüzet ..., mert a chilik nagyon csípősek.'::text,'okád'::text,'okád'::text,'okádott'::text,'Dehogy, a gekkó épp tüzet okád, mert a chilik nagyon csípősek.'::text),
(361605,40179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Krokodil ... den Dinosaurier von unter Wasser aus. Absoluter Horror!'::text,'jagte'::text,'wurde gejagt'::text,'jagend'::text,'Dieses Krokodil jagte den Dinosaurier von unter Wasser aus. Absoluter Horror!'::text),
(361609,40179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той крокодил ... на динозавра з-під води. Абсолютний жах!'::text,'полював'::text,'був упольований'::text,'полюючи'::text,'Той крокодил полював на динозавра з-під води. Абсолютний жах!'::text),
(361608,40179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese cocodrilo ... al dinosaurio desde debajo del agua. ¡Puro terror!'::text,'cazó'::text,'fue cazado'::text,'cazando'::text,'Ese cocodrilo cazó al dinosaurio desde debajo del agua. ¡Puro terror!'::text),
(361607,40179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce crocodile ... le dinosaure depuis l''eau. Horreur absolue !'::text,'a chassé'::text,'a été chassé'::text,'chassant'::text,'Ce crocodile a chassé le dinosaure depuis l''eau. Horreur absolue !'::text),
(361610,40179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O timsah, dinozoru suyun altından ...! Tam bir dehşet!'::text,'avladı'::text,'avlandı'::text,'avlayarak'::text,'O timsah, dinozoru suyun altından avladı! Tam bir dehşet!'::text),
(361611,40179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a krokodil a víz alól ... a dinoszauruszra. Abszolút horror!'::text,'vadászott'::text,'levadászták'::text,'vadászva'::text,'Az a krokodil a víz alól vadászott a dinoszauruszra. Abszolút horror!'::text),
(356619,39625,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Polizistin ist freundlich, also ... sie wieder Hallo, weil freundliche Leute Hallo sagen.'::text,'sagt'::text,'sagt'::text,'sagt gerade'::text,'Die Polizistin ist freundlich, also sagt sie wieder Hallo, weil freundliche Leute Hallo sagen.'::text),
(356623,39625,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поліцейська привітна, тож вона ... привіт знову, бо привітні люди кажуть привіт.'::text,'скаже'::text,'казатиме'::text,'каже'::text,'Поліцейська привітна, тож вона скаже привіт знову, бо привітні люди кажуть привіт.'::text),
(356622,39625,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La policía es simpática, así que ella ... hola otra vez, porque la gente simpática dice hola.'::text,'dirá'::text,'estará diciendo'::text,'está diciendo'::text,'La policía es simpática, así que ella dirá hola otra vez, porque la gente simpática dice hola.'::text),
(356621,39625,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La policière est sympa, alors elle ... encore bonjour, parce que les gens sympas disent bonjour.'::text,'dira'::text,'sera en train de dire'::text,'est en train de dire'::text,'La policière est sympa, alors elle dira encore bonjour, parce que les gens sympas disent bonjour.'::text),
(356624,39625,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Polis memuru arkadaş canlısı, o yüzden o yine merhaba ..., çünkü arkadaş canlısı insanlar merhaba der.'::text,'diyecek'::text,'diyor olacak'::text,'diyor'::text,'Polis memuru arkadaş canlısı, o yüzden o yine merhaba diyecek, çünkü arkadaş canlısı insanlar merhaba der.'::text),
(356625,39625,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendőrnő barátságos, úgyhogy ő megint ..., mert a barátságos emberek köszönnek.'::text,'köszönni fog'::text,'köszönni fog'::text,'éppen köszön'::text,'A rendőrnő barátságos, úgyhogy ő megint köszönni fog, mert a barátságos emberek köszönnek.'::text),
(356691,39633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... die freundliche Polizistin den Hund in der Kiste.'::text,'streichelt'::text,'streichelt'::text,'hat gestreichelt'::text,'Gerade streichelt die freundliche Polizistin den Hund in der Kiste.'::text),
(356695,39633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз привітна поліцейська ... собаку в ящику.'::text,'гладить'::text,'гладить'::text,'погладила'::text,'Саме зараз привітна поліцейська гладить собаку в ящику.'::text),
(356694,39633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, la policía simpática ... al perro de la caja.'::text,'está acariciando'::text,'acaricia'::text,'ha acariciado'::text,'Ahora mismo, la policía simpática está acariciando al perro de la caja.'::text),
(356693,39633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la policière sympa ... le chien dans la caisse.'::text,'caresse'::text,'caresse'::text,'a caressé'::text,'En ce moment, la policière sympa caresse le chien dans la caisse.'::text),
(356696,39633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda arkadaş canlısı polis memuru kasadaki köpeği ...'::text,'okşuyor'::text,'okşar'::text,'okşadı'::text,'Şu anda arkadaş canlısı polis memuru kasadaki köpeği okşuyor.'::text),
(356697,39633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a barátságos rendőrnő ... a kutyát a ládában.'::text,'simogatja'::text,'simogatja'::text,'megsimogatta'::text,'Épp most a barátságos rendőrnő simogatja a kutyát a ládában.'::text),
(356394,39600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass der Affe im Eis ..., als er kam, um ihn zu befreien.'::text,'zitterte'::text,'zitterte'::text,'gezittert hat'::text,'Hör mal, ich hab gehört, dass der Affe im Eis zitterte, als er kam, um ihn zu befreien.'::text),
(356398,39600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що мавпа ... всередині льоду, коли він прийшов її звільнити.'::text,'тремтіла'::text,'затремтіла'::text,'затремтіла'::text,'Слухай, я чула, що мавпа тремтіла всередині льоду, коли він прийшов її звільнити.'::text),
