(356396,39600,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que le singe ... dans la glace quand il est venu le libérer.'::text,'tremblait'::text,'a tremblé'::text,'a tremblé'::text,'Écoute, j''ai entendu dire que le singe tremblait dans la glace quand il est venu le libérer.'::text),
(356399,39600,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben duydum ki o, maymunu kurtarmaya geldiğinde maymun buzun içinde ...'::text,'titriyormuş'::text,'titremiş'::text,'titremiş'::text,'Dinle, ben duydum ki o, maymunu kurtarmaya geldiğinde maymun buzun içinde titriyormuş.'::text),
(356400,39600,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én úgy hallottam, hogy a majom ... a jégben, amikor ő odajött kiszabadítani.'::text,'reszketett'::text,'megremegett'::text,'megremegett'::text,'Figyelj, én úgy hallottam, hogy a majom reszketett a jégben, amikor ő odajött kiszabadítani.'::text),
(356457,39607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des dicken Eises wurde das Exemplar in etwa einer Minute befreit.'::text,'Trotz'::text,'Aufgrund'::text,'Vorausgesetzt'::text,'Trotz des dicken Eises wurde das Exemplar in etwa einer Minute befreit.'::text),
(356461,39607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... товстий лід, зразок було звільнено приблизно за одну хвилину.'::text,'Попри'::text,'Через'::text,'За умови'::text,'Попри товстий лід, зразок було звільнено приблизно за одну хвилину.'::text),
(356460,39607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el grueso hielo, el espécimen fue liberado en aproximadamente un minuto.'::text,'A pesar de'::text,'Debido a'::text,'Siempre que'::text,'A pesar de el grueso hielo, el espécimen fue liberado en aproximadamente un minuto.'::text),
(356459,39607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la glace épaisse, le spécimen a été libéré en une minute environ.'::text,'Malgré'::text,'En raison de'::text,'Pourvu que'::text,'Malgré la glace épaisse, le spécimen a été libéré en une minute environ.'::text),
(356462,39607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalın buz ..., örnek yaklaşık bir dakikada serbest bırakıldı.'::text,'olmasına rağmen'::text,'nedeniyle'::text,'olması şartıyla'::text,'Kalın buz olmasına rağmen, örnek yaklaşık bir dakikada serbest bırakıldı.'::text),
(356463,39607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vastag jég ... a példányt körülbelül egy perc alatt kiszabadították.'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'A vastag jég ellenére a példányt körülbelül egy perc alatt kiszabadították.'::text),
(340689,37855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie wusste, dass er ihren Kleiderschrank sofort verwüsten ..., sobald sie fragte, ohne Witz.'::text,'würde'::text,'wird'::text,'war'::text,'Bro, sie wusste, dass er ihren Kleiderschrank sofort verwüsten würde, sobald sie fragte, ohne Witz.'::text),
(340693,37855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона знала, що він ... її гардероб, щойно вона попросить, без жартів.'::text,'розгромить'::text,'розгромить'::text,'розгромив'::text,'Бро, вона знала, що він розгромить її гардероб, щойно вона попросить, без жартів.'::text),
(340692,37855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella sabía que él ... su armario en cuanto ella se lo pidiera, en serio.'::text,'destrozaría'::text,'destrozará'::text,'estaba destrozando'::text,'Bro, ella sabía que él destrozaría su armario en cuanto ella se lo pidiera, en serio.'::text),
(340691,37855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle savait qu''il ... son dressing dès qu''elle le demanderait, sans mentir.'::text,'saccagerait'::text,'saccagera'::text,'saccageait'::text,'Frérot, elle savait qu''il saccagerait son dressing dès qu''elle le demanderait, sans mentir.'::text),
(340694,37855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o, istediği anda onun dolabını ... biliyordu, yalan yok.'::text,'dağıtacağını'::text,'dağıtacağını'::text,'dağıttığını'::text,'Kanka, o, istediği anda onun dolabını dağıtacağını biliyordu, yalan yok.'::text),
(340695,37855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő tudta, hogy a srác ... a gardróbját, amint megkéri, komolyan.'::text,'szétszedi'::text,'szétszedi'::text,'szétszedte'::text,'Tesó, ő tudta, hogy a srác szétszedi a gardróbját, amint megkéri, komolyan.'::text),
(338709,37635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten Fische Hände, ... sie diesem Wurf. Wirklich legendäre Technik.'::text,'applaudierten'::text,'werden applaudieren'::text,'applaudierten'::text,'Hätten Fische Hände, applaudierten sie diesem Wurf. Wirklich legendäre Technik.'::text),
(338713,37635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби риби мали руки, вони ... за цей закид. Справді легендарна техніка.'::text,'аплодували б'::text,'аплодуватимуть'::text,'аплодували'::text,'Якби риби мали руки, вони аплодували б за цей закид. Справді легендарна техніка.'::text),
(338712,37635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los peces tuvieran manos, ellos ... por ese lanzamiento. Técnica realmente legendaria.'::text,'aplaudirían'::text,'aplaudirán'::text,'aplaudieron'::text,'Si los peces tuvieran manos, ellos aplaudirían por ese lanzamiento. Técnica realmente legendaria.'::text),
(338711,37635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les poissons avaient des mains, ils ... pour ce lancer. Une technique vraiment légendaire.'::text,'applaudiraient'::text,'applaudiront'::text,'applaudissaient'::text,'Si les poissons avaient des mains, ils applaudiraient pour ce lancer. Une technique vraiment légendaire.'::text),
(338714,37635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balıkların elleri olsaydı, onlar bu atış için ...; gerçekten efsanevi bir teknik.'::text,'alkışlardı'::text,'alkışlayacak'::text,'alkışladı'::text,'Balıkların elleri olsaydı, onlar bu atış için alkışlardı; gerçekten efsanevi bir teknik.'::text),
(338715,37635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a halaknak keze lenne, ők ... ezért a dobásért. Igazán legendás technika.'::text,'tapsolnának'::text,'tapsolni fognak'::text,'tapsoltak'::text,'Ha a halaknak keze lenne, ők tapsolnának ezért a dobásért. Igazán legendás technika.'::text),
(338736,37638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... er vor diesem einen perfekten Wurf stundenlang geübt.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Mädel, angeblich hatte er vor diesem einen perfekten Wurf stundenlang geübt.'::text),
(338740,37638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... годинами перед тим ідеальним закидом.'::text,'тренувався'::text,'тренувався'::text,'тренувався'::text,'Подруго, кажуть, він тренувався годинами перед тим ідеальним закидом.'::text),
(338739,37638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer él ... durante horas antes de ese lanzamiento perfecto.'::text,'había estado practicando'::text,'ha estado practicando'::text,'estaba practicando'::text,'Tía, al parecer él había estado practicando durante horas antes de ese lanzamiento perfecto.'::text),
(338738,37638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... pendant des heures avant ce lancer parfait.'::text,'s''était entraîné'::text,'s''est entraîné'::text,'s''entraînait'::text,'Meuf, apparemment il s''était entraîné pendant des heures avant ce lancer parfait.'::text),
(338741,37638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o, o mükemmel atıştan önce saatlerce ...'::text,'çalışmıştı'::text,'çalışıyor'::text,'çalışıyordu'::text,'Kızım, duyduğuma göre o, o mükemmel atıştan önce saatlerce çalışmıştı.'::text),
(338742,37638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő órákig ... az előtt az egy tökéletes dobás előtt.'::text,'gyakorolt'::text,'gyakorol'::text,'gyakorolt'::text,'Csajszi, állítólag ő órákig gyakorolt az előtt az egy tökéletes dobás előtt.'::text),
(332139,36905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Geschäft erwartet, 500 neue Kunden ..., sobald der Fernseher installiert ist.'::text,'anzuziehen'::text,'anziehend'::text,'anziehen'::text,'Das Geschäft erwartet, 500 neue Kunden anzuziehen, sobald der Fernseher installiert ist.'::text),
(332143,36905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Магазин очікує ... 500 нових клієнтів, щойно телевізор встановлять.'::text,'залучити'::text,'залучення'::text,'залучити'::text,'Магазин очікує залучити 500 нових клієнтів, щойно телевізор встановлять.'::text),
(332142,36905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tienda espera ... 500 clientes nuevos una vez que se instale la televisión.'::text,'atraer'::text,'atrayendo'::text,'atraer'::text,'La tienda espera atraer 500 clientes nuevos una vez que se instale la televisión.'::text),
(332141,36905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le magasin compte ... 500 nouveaux clients une fois la télé installée.'::text,'attirer'::text,'attirant'::text,'attirer'::text,'Le magasin compte attirer 500 nouveaux clients une fois la télé installée.'::text),
(332144,36905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mağaza, televizyon kurulduktan sonra 500 yeni müşteri ... bekliyor.'::text,'çekmeyi'::text,'çekerek'::text,'çekmek'::text,'Mağaza, televizyon kurulduktan sonra 500 yeni müşteri çekmeyi bekliyor.'::text),
(332145,36905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üzlet arra számít, hogy ... 500 új ügyfelet, amint felszerelik a tévét.'::text,'bevonz'::text,'bevonzva'::text,'bevonzani'::text,'Az üzlet arra számít, hogy bevonz 500 új ügyfelet, amint felszerelik a tévét.'::text),
(332157,36907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ... ihre Aufmerksamkeit genau in dem Moment, als sie den Fernseher vom Transporter hoben.'::text,'erregte'::text,'hatte erregt'::text,'hat erregt'::text,'Die Frau erregte ihre Aufmerksamkeit genau in dem Moment, als sie den Fernseher vom Transporter hoben.'::text),
(332161,36907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... їхню увагу саме тоді, коли вони знімали телевізор з фургона.'::text,'привернула'::text,'привертала'::text,'привернула'::text,'Жінка привернула їхню увагу саме тоді, коли вони знімали телевізор з фургона.'::text),
(332160,36907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... su atención justo cuando ellos bajaban la tele de la furgoneta.'::text,'atrajo'::text,'había estado atrayendo'::text,'ha atraído'::text,'La mujer atrajo su atención justo cuando ellos bajaban la tele de la furgoneta.'::text),
(332159,36907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... leur attention juste au moment où ils descendaient la télé de la camionnette.'::text,'a attiré'::text,'attirait'::text,'a attiré'::text,'La femme a attiré leur attention juste au moment où ils descendaient la télé de la camionnette.'::text),
(332162,36907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar televizyonu kamyonetten indirirken kadın tam o anda dikkatlerini ...'::text,'çekti'::text,'çekiyordu'::text,'çekti'::text,'Onlar televizyonu kamyonetten indirirken kadın tam o anda dikkatlerini çekti.'::text),
(332163,36907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő épp akkor ... a figyelmüket, amikor a tévét emelték le a furgonról.'::text,'magára vonta'::text,'vonzotta'::text,'magára vonta'::text,'A nő épp akkor magára vonta a figyelmüket, amikor a tévét emelték le a furgonról.'::text),
(334002,37112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge war im Stall glücklich, und das Pferd mit seiner Karotte ... auch.'::text,'war es'::text,'tat es'::text,'war es nicht'::text,'Der Junge war im Stall glücklich, und das Pferd mit seiner Karotte war es auch.'::text),
(334006,37112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопчик був щасливий у стайні, і ... кінь зі своєю морквою.'::text,'щасливим був і'::text,'так само й'::text,'не був і'::text,'Хлопчик був щасливий у стайні, і щасливим був і кінь зі своєю морквою.'::text),
(334005,37112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El niño estaba feliz en el establo, y ... el caballo con su zanahoria.'::text,'también lo estaba'::text,'también lo hizo'::text,'tampoco lo estaba'::text,'El niño estaba feliz en el establo, y también lo estaba el caballo con su zanahoria.'::text),
(334004,37112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon était heureux dans la grange, et le cheval avec sa carotte ... aussi.'::text,'l''était'::text,'l''a fait'::text,'ne l''était pas'::text,'Le garçon était heureux dans la grange, et le cheval avec sa carotte l''était aussi.'::text),
(334007,37112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk ahırda mutluydu, havucuyla at da ...'::text,'öyleydi'::text,'öyle yaptı'::text,'değildi'::text,'Çocuk ahırda mutluydu, havucuyla at da öyleydi.'::text),
(334008,37112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú boldog volt az istállóban, és a répájával a ló is ...'::text,'az volt'::text,'úgy tett'::text,'nem volt az'::text,'A fiú boldog volt az istállóban, és a répájával a ló is az volt.'::text),
(334056,37118,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat gesagt, sie wünscht sich, ihre Wohnung ... eine Scheune mit einem Pferd darin.'::text,'hätte'::text,'hat'::text,'wird haben'::text,'Mädel, sie hat gesagt, sie wünscht sich, ihre Wohnung hätte eine Scheune mit einem Pferd darin.'::text),
(334060,37118,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала, що хотіла б, щоб у її квартирі ... стайня з конем.'::text,'була'::text,'є'::text,'буде'::text,'Подруго, вона сказала, що хотіла б, щоб у її квартирі була стайня з конем.'::text),
(334059,37118,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, ella dijo que ojalá su piso ... un granero con un caballo dentro.'::text,'tuviera'::text,'tiene'::text,'tendrá'::text,'Tía, ella dijo que ojalá su piso tuviera un granero con un caballo dentro.'::text),
(334058,37118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle a dit qu''elle aimerait que son appart ... une grange avec un cheval dedans.'::text,'ait'::text,'a'::text,'aura'::text,'Meuf, elle a dit qu''elle aimerait que son appart ait une grange avec un cheval dedans.'::text),
(334061,37118,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o, keşke dairesinde içinde at olan bir ahır ... diyormuş.'::text,'olsa'::text,'var'::text,'olacak'::text,'Kızım, o, keşke dairesinde içinde at olan bir ahır olsa diyormuş.'::text),
(334062,37118,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta, bárcsak a lakásában ... egy istálló egy lóval.'::text,'lenne'::text,'van'::text,'lesz'::text,'Csajszi, ő azt mondta, bárcsak a lakásában lenne egy istálló egy lóval.'::text),
(375546,41728,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Möwe ... den Reiter durch den Hafen zwischen zwei Frachtschiffen hindurch.'::text,'trug'::text,'wurde getragen'::text,'tragend'::text,'Die Möwe trug den Reiter durch den Hafen zwischen zwei Frachtschiffen hindurch.'::text),
(375550,41728,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чайка ... вершника через порт між двома вантажними суднами.'::text,'несла'::text,'була несена'::text,'несучи'::text,'Чайка несла вершника через порт між двома вантажними суднами.'::text),
(375549,41728,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gaviota ... al jinete por el puerto entre dos buques de carga.'::text,'llevó'::text,'fue llevada'::text,'llevando'::text,'La gaviota llevó al jinete por el puerto entre dos buques de carga.'::text),
(375548,41728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mouette ... le cavalier à travers le port entre deux cargos.'::text,'a porté'::text,'a été portée'::text,'portant'::text,'La mouette a porté le cavalier à travers le port entre deux cargos.'::text),
(375551,41728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Martı, biniciyi limanda iki kargo gemisinin arasından ...'::text,'taşıdı'::text,'taşındı'::text,'taşıyarak'::text,'Martı, biniciyi limanda iki kargo gemisinin arasından taşıdı.'::text),
(375552,41728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sirály ... a lovast a kikötőn át két teherhajó között.'::text,'vitte'::text,'vitték'::text,'víve'::text,'A sirály vitte a lovast a kikötőn át két teherhajó között.'::text),
(375600,41734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei roten Frachtschiffe brachten ihre Waren über ... in den Hafen.'::text,'See'::text,'die See'::text,'eine See'::text,'Die zwei roten Frachtschiffe brachten ihre Waren über See in den Hafen.'::text),
(375604,41734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Два червоні вантажні судна привезли свої товари в порт ...'::text,'морем'::text,'морем'::text,'морем'::text,'Два червоні вантажні судна привезли свої товари в порт морем.'::text),
(375603,41734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos buques de carga rojos trajeron sus mercancías al puerto por ...'::text,'mar'::text,'el mar'::text,'un mar'::text,'Los dos buques de carga rojos trajeron sus mercancías al puerto por mar.'::text),
(375602,41734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux cargos rouges ont apporté leurs marchandises au port par ...'::text,'mer'::text,'la mer'::text,'une mer'::text,'Les deux cargos rouges ont apporté leurs marchandises au port par mer.'::text),
(375605,41734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki kırmızı kargo gemisi mallarını limana ... yoluyla getirdi.'::text,'deniz'::text,'deniz'::text,'bir deniz'::text,'İki kırmızı kargo gemisi mallarını limana deniz yoluyla getirdi.'::text),
(375606,41734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két piros teherhajó ... szállította az áruját a kikötőbe.'::text,'tengeren'::text,'a tengeren'::text,'egy tengeren'::text,'A két piros teherhajó tengeren szállította az áruját a kikötőbe.'::text),
(361695,40189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese identischen Huskys ... sich schon den ganzen Nachmittag. Totales Chaos!'::text,'jagen'::text,'jagten'::text,'jagen gerade'::text,'Diese identischen Huskys jagen sich schon den ganzen Nachmittag. Totales Chaos!'::text),
(361699,40189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці однакові хаскі ... одне одного все пообіддя. Повний хаос!'::text,'ганяють'::text,'ганяли'::text,'ганяють'::text,'Ці однакові хаскі ганяють одне одного все пообіддя. Повний хаос!'::text),
(361698,40189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estos huskies idénticos se ... toda la tarde. ¡Caos total!'::text,'han estado persiguiendo'::text,'persiguieron'::text,'están persiguiendo'::text,'Estos huskies idénticos se han estado persiguiendo toda la tarde. ¡Caos total!'::text),
(361697,40189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces huskys identiques ... tout l''après-midi. Chaos total !'::text,'se poursuivent'::text,'se sont poursuivis'::text,'se poursuivent'::text,'Ces huskys identiques se poursuivent tout l''après-midi. Chaos total !'::text),
(361700,40189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu birbirinin aynısı huskyler bütün öğleden sonra birbirlerini ...! Tam bir kaos!'::text,'kovalıyorlar'::text,'kovaladılar'::text,'kovalıyorlar'::text,'Bu birbirinin aynısı huskyler bütün öğleden sonra birbirlerini kovalıyorlar! Tam bir kaos!'::text),
(361701,40189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezek az egyforma huskyk egész délután ... egymást. Teljes káosz!'::text,'kergetik'::text,'kergették'::text,'kergetik'::text,'Ezek az egyforma huskyk egész délután kergetik egymást. Teljes káosz!'::text),
(361758,40196,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer ... die identischen Huskys jahrelang, bevor er Halsbänder kaufte. Genie.'::text,'verwechselte'::text,'verwechselt'::text,'verwechselt'::text,'Der Besitzer verwechselte die identischen Huskys jahrelang, bevor er Halsbänder kaufte. Genie.'::text),
(361762,40196,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник роками ... однакових хаскі, перш ніж купив нашийники. Геній.'::text,'плутав'::text,'плутає'::text,'плутає'::text,'Власник роками плутав однакових хаскі, перш ніж купив нашийники. Геній.'::text),
(361761,40196,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dueño ... a los huskies idénticos durante años antes de comprar collares. Un genio.'::text,'había estado confundiendo'::text,'ha estado confundiendo'::text,'confunde'::text,'El dueño había estado confundiendo a los huskies idénticos durante años antes de comprar collares. Un genio.'::text),
(361760,40196,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire ... les huskys identiques pendant des années avant d''acheter des colliers. Génie.'::text,'confondait'::text,'confond'::text,'confond'::text,'Le propriétaire confondait les huskys identiques pendant des années avant d''acheter des colliers. Génie.'::text),
(361763,40196,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi, tasma almadan önce yıllarca birbirinin aynısı huskyleri ...; tam bir dahi.'::text,'karıştırmıştı'::text,'karıştırıyor'::text,'karıştırır'::text,'Sahibi, tasma almadan önce yıllarca birbirinin aynısı huskyleri karıştırmıştı; tam bir dahi.'::text),
(361764,40196,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gazdi évekig ... az egyforma huskykat, mielőtt nyakörvet vett. Zseni.'::text,'összekeverte'::text,'összekeveri'::text,'összekeveri'::text,'A gazdi évekig összekeverte az egyforma huskykat, mielőtt nyakörvet vett. Zseni.'::text),
(374331,41593,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann ... das Flugzeug durch die graue Wolke hinunter auf die Landebahn.'::text,'steuerte'::text,'wurde gesteuert'::text,'steuernd'::text,'Der junge Mann steuerte das Flugzeug durch die graue Wolke hinunter auf die Landebahn.'::text),
(374335,41593,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік ... літак униз крізь сіру хмару до злітної смуги.'::text,'пілотував'::text,'був пілотований'::text,'пілотуючи'::text,'Молодий чоловік пілотував літак униз крізь сіру хмару до злітної смуги.'::text),
(374334,41593,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven ... el avión a través de la nube gris hasta la pista.'::text,'pilotó'::text,'fue pilotado'::text,'pilotando'::text,'El joven pilotó el avión a través de la nube gris hasta la pista.'::text),
(374333,41593,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme ... l''avion à travers le nuage gris jusqu''à la piste.'::text,'a piloté'::text,'a été piloté'::text,'pilotant'::text,'Le jeune homme a piloté l''avion à travers le nuage gris jusqu''à la piste.'::text),
(374336,41593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam uçağı gri bulutun içinden piste doğru aşağı ...'::text,'uçurdu'::text,'uçuruldu'::text,'uçurarak'::text,'Genç adam uçağı gri bulutun içinden piste doğru aşağı uçurdu.'::text),
(374337,41593,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember ... a gépet a szürke felhőn át le a kifutópályára.'::text,'vezette'::text,'vezették'::text,'vezetve'::text,'A fiatalember vezette a gépet a szürke felhőn át le a kifutópályára.'::text),
(374412,41602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Ende dieses Jahres wird der junge Mann 500 Stunden lang Flugzeuge ...'::text,'geflogen haben'::text,'fliegen'::text,'am Fliegen sein'::text,'Bis Ende dieses Jahres wird der junge Mann 500 Stunden lang Flugzeuge geflogen haben.'::text),
(374416,41602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця цього року молодий чоловік ... літаки 500 годин.'::text,'пілотуватиме'::text,'пілотуватиме'::text,'пілотуватиме'::text,'До кінця цього року молодий чоловік пілотуватиме літаки 500 годин.'::text),
(374415,41602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para finales de este año, el joven ... aviones durante 500 horas.'::text,'habrá pilotado'::text,'pilotará'::text,'estará pilotando'::text,'Para finales de este año, el joven habrá pilotado aviones durante 500 horas.'::text),
(374414,41602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de l''année, le jeune homme ... des avions pendant 500 heures.'::text,'aura piloté'::text,'pilotera'::text,'sera en train de piloter'::text,'D''ici la fin de l''année, le jeune homme aura piloté des avions pendant 500 heures.'::text),
(374417,41602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yılın sonuna kadar genç adam 500 saat uçak ...'::text,'uçurmuş olacak'::text,'uçuracak'::text,'uçuruyor olacak'::text,'Bu yılın sonuna kadar genç adam 500 saat uçak uçurmuş olacak.'::text),
(374418,41602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az év végére a fiatalember ... 500 órát repülőgépen.'::text,'lerepül'::text,'repül'::text,'repülni fog'::text,'Az év végére a fiatalember lerepül 500 órát repülőgépen.'::text),
(339492,37722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Stier noch mal auf das Auto losginge, ... das Fenster komplett kaputt!'::text,'ginge'::text,'geht'::text,'ging'::text,'Wenn der Stier noch mal auf das Auto losginge, ginge das Fenster komplett kaputt!'::text),
(339496,37722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби бик знову кинувся на машину, вікно ... повністю!'::text,'розбилося б'::text,'розіб''ється'::text,'розбилося'::text,'Якби бик знову кинувся на машину, вікно розбилося б повністю!'::text),
(339495,37722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el toro embistiera otra vez contra el coche, ¡la ventanilla se ... por completo!'::text,'rompería'::text,'romperá'::text,'rompió'::text,'Si el toro embistiera otra vez contra el coche, ¡la ventanilla se rompería por completo!'::text),
(339494,37722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le taureau chargeait encore la voiture, la vitre ... complètement !'::text,'éclaterait'::text,'éclatera'::text,'a éclaté'::text,'Si le taureau chargeait encore la voiture, la vitre éclaterait complètement !'::text),
(339497,37722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boğa arabaya bir daha saldırsa, cam tamamen ...!'::text,'parçalanırdı'::text,'parçalanacak'::text,'parçalandı'::text,'Boğa arabaya bir daha saldırsa, cam tamamen parçalanırdı!'::text),
(339498,37722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a bika újra nekirontana az autónak, az ablak teljesen ...!'::text,'betörne'::text,'be fog törni'::text,'betört'::text,'Ha a bika újra nekirontana az autónak, az ablak teljesen betörne!'::text),
(339528,37726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich werden sie bis nächste Woche allen die Geschichte vom Stierangriff ...'::text,'erzählt haben'::text,'erzählen'::text,'am Erzählen sein'::text,'Okay, also angeblich werden sie bis nächste Woche allen die Geschichte vom Stierangriff erzählt haben.'::text),
(339532,37726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, отже, кажуть, до наступного тижня вони ... історію про атаку бика всім.'::text,'розкажуть'::text,'розкажуть'::text,'розповідатимуть'::text,'Окей, отже, кажуть, до наступного тижня вони розкажуть історію про атаку бика всім.'::text),
(339531,37726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer para la semana que viene ellos ... la historia de la embestida del toro a todo el mundo.'::text,'habrán contado'::text,'contarán'::text,'estarán contando'::text,'Vale, pues al parecer para la semana que viene ellos habrán contado la historia de la embestida del toro a todo el mundo.'::text),
(339530,37726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment d''ici la semaine prochaine ils ... l''histoire de la charge du taureau à tout le monde.'::text,'auront raconté'::text,'raconteront'::text,'seront en train de raconter'::text,'Bon, apparemment d''ici la semaine prochaine ils auront raconté l''histoire de la charge du taureau à tout le monde.'::text),
(339533,37726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan önümüzdeki haftaya kadar onlar boğa saldırısı hikâyesini herkese ...'::text,'anlatmış olacaklar'::text,'anlatacaklar'::text,'anlatıyor olacaklar'::text,'Tamam, anlaşılan önümüzdeki haftaya kadar onlar boğa saldırısı hikâyesini herkese anlatmış olacaklar.'::text),
(339534,37726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag jövő hétre ők mindenkinek ... a bikatámadásos sztorit.'::text,'elmesélik'::text,'el fogják mesélni'::text,'mesélni fogják'::text,'Oké, szóval állítólag jövő hétre ők mindenkinek elmesélik a bikatámadásos sztorit.'::text),
(388137,43127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sie als Kinder jeden Sommer hier runter.'::text,'rutschten'::text,'waren gewohnt'::text,'rutschten'::text,'Mädel, angeblich rutschten sie als Kinder jeden Sommer hier runter.'::text),
(388141,43127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вони ... тут з''їжджати щоліта, коли були дітьми.'::text,'мали звичку'::text,'були звиклі'::text,'мали звичку'::text,'Подруго, кажуть, вони мали звичку тут з''їжджати щоліта, коли були дітьми.'::text),
(388140,43127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ellos ... deslizarse por aquí cada verano de niños.'::text,'solían'::text,'estaban acostumbrados a'::text,'solían'::text,'Tía, al parecer ellos solían deslizarse por aquí cada verano de niños.'::text),
(388139,43127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ils ... glisser ici chaque été quand ils étaient petits.'::text,'avaient l''habitude de'::text,'étaient habitués à'::text,'avaient l''habitude de'::text,'Meuf, apparemment ils avaient l''habitude de glisser ici chaque été quand ils étaient petits.'::text),
(388142,43127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre onlar çocukken her yaz buradan aşağı ...'::text,'kayarlarmış'::text,'kaymaya alışkınmış'::text,'kayarlarmış'::text,'Kızım, duyduğuma göre onlar çocukken her yaz buradan aşağı kayarlarmış.'::text),
(388143,43127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ők gyerekként minden nyáron itt ... lecsúszni.'::text,'szoktak'::text,'hozzá voltak szokva'::text,'szoktak'::text,'Csajszi, állítólag ők gyerekként minden nyáron itt szoktak lecsúszni.'::text),
(401682,44632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hunde arbeiten im Lager, weil die Paletten dort sind, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die Hunde arbeiten im Lager, weil die Paletten dort sind, oder?'::text),
(401686,44632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собаки працюють на складі, бо там палети, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Собаки працюють на складі, бо там палети, правда?'::text),
(401685,44632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los perros trabajan en el almacén porque los palés están allí, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Los perros trabajan en el almacén porque los palés están allí, ¿verdad?'::text),
(401684,44632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chiens travaillent à l''entrepôt parce que les palettes sont là, ... ?'::text,'non'::text,'non'::text,'non'::text,'Les chiens travaillent à l''entrepôt parce que les palettes sont là, non ?'::text),
(401687,44632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekler depoda çalışıyor çünkü paletler orada, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Köpekler depoda çalışıyor çünkü paletler orada, değil mi?'::text),
(401688,44632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyák a raktárban dolgoznak, mert ott vannak a raklapok, ...?'::text,'nem'::text,'nem'::text,'nem'::text,'A kutyák a raktárban dolgoznak, mert ott vannak a raklapok, nem?'::text),
(401700,44634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, man sagt, dass der Retriever den Gabelstapler vor dem Unfall sechs Stunden lang ...'::text,'gefahren hatte'::text,'gefahren hat'::text,'fährt'::text,'Bestie, man sagt, dass der Retriever den Gabelstapler vor dem Unfall sechs Stunden lang gefahren hatte.'::text),
(401704,44634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, кажуть, ретривер ... той навантажувач шість годин перед аварією.'::text,'кермував'::text,'кермує'::text,'кермує'::text,'Бесті, кажуть, ретривер кермував той навантажувач шість годин перед аварією.'::text),
(401703,44634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, dicen que el retriever ... esa carretilla elevadora seis horas antes del accidente.'::text,'había estado conduciendo'::text,'ha estado conduciendo'::text,'está conduciendo'::text,'Bestie, dicen que el retriever había estado conduciendo esa carretilla elevadora seis horas antes del accidente.'::text),
(401702,44634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, il paraît que le retriever ... ce chariot élévateur depuis six heures avant l''accident.'::text,'conduisait'::text,'conduit'::text,'conduit'::text,'Bestie, il paraît que le retriever conduisait ce chariot élévateur depuis six heures avant l''accident.'::text),
(401705,44634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre retriever kazadan önce o forklifti altı saattir ...'::text,'kullanıyormuş'::text,'kullanıyor'::text,'kullanıyor'::text,'Kanka, duyduğuma göre retriever kazadan önce o forklifti altı saattir kullanıyormuş.'::text),
(401706,44634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt beszélik, a retriever hat órán át ... azt a targoncát a baleset előtt.'::text,'vezette'::text,'vezeti'::text,'vezeti'::text,'Csajszi, azt beszélik, a retriever hat órán át vezette azt a targoncát a baleset előtt.'::text),
(389604,43290,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass er gerade Platz für seine Klamotten ..., als er den riesigen Haufen fand.'::text,'suchte'::text,'suchte'::text,'gesucht hat'::text,'Mädel, er hat mir erzählt, dass er gerade Platz für seine Klamotten suchte, als er den riesigen Haufen fand.'::text),
(389608,43290,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... місце для свого одягу, коли знайшов величезну купу.'::text,'шукав'::text,'шукав'::text,'шукав'::text,'Подруго, він сказав мені, що шукав місце для свого одягу, коли знайшов величезну купу.'::text),
(389607,43290,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él me dijo que ... sitio para su ropa cuando encontró el montón enorme.'::text,'estaba buscando'::text,'buscó'::text,'ha buscado'::text,'Tía, él me dijo que estaba buscando sitio para su ropa cuando encontró el montón enorme.'::text),
(389606,43290,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il ... de la place pour ses fringues quand il a trouvé l''énorme tas.'::text,'cherchait'::text,'a cherché'::text,'a cherché'::text,'Meuf, il m''a dit qu''il cherchait de la place pour ses fringues quand il a trouvé l''énorme tas.'::text),
(389609,43290,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana, devasa yığını bulduğunda kıyafetleri için yer ... söyledi.'::text,'aradığını'::text,'aradığını'::text,'aramış olduğunu'::text,'Kızım, o bana, devasa yığını bulduğunda kıyafetleri için yer aradığını söyledi.'::text),
(389610,43290,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta nekem, hogy épp helyet ... a ruháinak, amikor megtalálta a hatalmas kupacot.'::text,'keresett'::text,'keresett'::text,'keresett'::text,'Csajszi, ő azt mondta nekem, hogy épp helyet keresett a ruháinak, amikor megtalálta a hatalmas kupacot.'::text),
(389631,43293,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ich wünschte, sie ... mir mehr Platz in diesem Schrank, echt jetzt.'::text,'gäbe'::text,'wird geben'::text,'gibt'::text,'Bro, ich wünschte, sie gäbe mir mehr Platz in diesem Schrank, echt jetzt.'::text),
(389635,43293,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, я б хотів, щоб вона ... мені більше місця в цій шафі, реально.'::text,'дала'::text,'дасть'::text,'дає'::text,'Бро, я б хотів, щоб вона дала мені більше місця в цій шафі, реально.'::text),
(389634,43293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, yo quisiera que ella me ... más espacio en este armario, en serio.'::text,'diera'::text,'dará'::text,'da'::text,'Bro, yo quisiera que ella me diera más espacio en este armario, en serio.'::text),
(389633,43293,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, j''aimerais qu''elle me ... plus de place dans cette armoire, sérieux.'::text,'donne'::text,'donnera'::text,'donne'::text,'Frérot, j''aimerais qu''elle me donne plus de place dans cette armoire, sérieux.'::text),
(389636,43293,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke o bana bu dolapta daha fazla yer ..., cidden.'::text,'verse'::text,'verecek'::text,'veriyor'::text,'Kanka, keşke o bana bu dolapta daha fazla yer verse, cidden.'::text),
(389637,43293,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, bárcsak ő ... nekem több helyet ebben a szekrényben, komolyan.'::text,'adna'::text,'adni fog'::text,'ad'::text,'Tesó, bárcsak ő adna nekem több helyet ebben a szekrényben, komolyan.'::text),
(341886,37988,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Terrasse ... Rasen, bevor sie den Beton gegossen haben.'::text,'war früher'::text,'wäre'::text,'war gewohnt'::text,'Die Terrasse war früher Rasen, bevor sie den Beton gegossen haben.'::text),
(341890,37988,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тераса ... газоном, поки не поклали бетон.'::text,'колись була'::text,'була б'::text,'звикла бути'::text,'Тераса колись була газоном, поки не поклали бетон.'::text),
(341889,37988,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El patio ... césped antes de que pusieran el hormigón.'::text,'solía ser'::text,'sería'::text,'estaba acostumbrado a ser'::text,'El patio solía ser césped antes de que pusieran el hormigón.'::text),
(341888,37988,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La terrasse ... de la pelouse avant qu''ils coulent le béton.'::text,'était autrefois'::text,'serait'::text,'était habituée à être'::text,'La terrasse était autrefois de la pelouse avant qu''ils coulent le béton.'::text),
(341891,37988,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar betonu dökmeden önce teras ...'::text,'eskiden çimendi'::text,'çimen olurdu'::text,'çimen olmaya alışkındı'::text,'Onlar betonu dökmeden önce teras eskiden çimendi.'::text),
(341892,37988,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A terasz ..., mielőtt leöntötték a betont.'::text,'régen füves volt'::text,'füves lett volna'::text,'hozzá volt szokva, hogy füves legyen'::text,'A terasz régen füves volt, mielőtt leöntötték a betont.'::text),
(341904,37990,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat schon den halben Beton ..., während sein Kumpel an einem Drink nippt. Tolle Teamarbeit.'::text,'geschrubbt'::text,'schrubbt gerade'::text,'schrubbt'::text,'Er hat schon den halben Beton geschrubbt, während sein Kumpel an einem Drink nippt. Tolle Teamarbeit.'::text),
(341908,37990,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже ... половину бетону, поки його друг сьорбає напій. Чудова командна робота.'::text,'відшкріб'::text,'шкребе'::text,'шкребе'::text,'Він уже відшкріб половину бетону, поки його друг сьорбає напій. Чудова командна робота.'::text),
(341907,37990,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ya ... la mitad del hormigón mientras su amigo se toma algo. Gran trabajo en equipo.'::text,'ha fregado'::text,'está fregando'::text,'friega'::text,'Él ya ha fregado la mitad del hormigón mientras su amigo se toma algo. Gran trabajo en equipo.'::text),
(341906,37990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... déjà la moitié du béton pendant que son pote sirote un verre. Super travail d''équipe.'::text,'a frotté'::text,'est en train de frotter'::text,'frotte'::text,'Il a frotté déjà la moitié du béton pendant que son pote sirote un verre. Super travail d''équipe.'::text),
(341909,37990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, betonun yarısını çoktan ..., arkadaşı ise içeceğini yudumluyor. Harika takım çalışması.'::text,'fırçaladı'::text,'fırçalıyor'::text,'fırçalar'::text,'O, betonun yarısını çoktan fırçaladı, arkadaşı ise içeceğini yudumluyor. Harika takım çalışması.'::text),
(341910,37990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő már ... a beton felét, miközben a haverja egy italt szürcsöl. Remek csapatmunka.'::text,'lesikálta'::text,'sikálja'::text,'sikálja'::text,'Ő már lesikálta a beton felét, miközben a haverja egy italt szürcsöl. Remek csapatmunka.'::text),
(343434,38160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kater schreit, dass er an seiner Theke nie wieder eine Taube ...!'::text,'bedienen wird'::text,'am Bedienen sein wird'::text,'bedient'::text,'Der Kater schreit, dass er an seiner Theke nie wieder eine Taube bedienen wird!'::text),
(343438,38160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кіт кричить, що він більше ніколи ... жодного голуба за своєю стійкою!'::text,'не обслужить'::text,'не обслуговуватиме'::text,'не обслуговує'::text,'Кіт кричить, що він більше ніколи не обслужить жодного голуба за своєю стійкою!'::text),
(343437,38160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El gato grita que él nunca más ... a otra paloma en su mostrador!'::text,'servirá'::text,'estará sirviendo'::text,'está sirviendo'::text,'¡El gato grita que él nunca más servirá a otra paloma en su mostrador!'::text),
(343436,38160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat hurle qu''il ne ... plus jamais un autre pigeon à son comptoir !'::text,'servira'::text,'sera en train de servir'::text,'sert'::text,'Le chat hurle qu''il ne servira plus jamais un autre pigeon à son comptoir !'::text),
(343439,38160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi, ben tezgâhımda bir daha asla başka bir güvercine ... diye bağırıyor!'::text,'hizmet etmeyeceğim'::text,'hizmet ediyor olmayacağım'::text,'hizmet etmiyorum'::text,'Kedi, ben tezgâhımda bir daha asla başka bir güvercine hizmet etmeyeceğim diye bağırıyor!'::text),
(343440,38160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska azt üvölti, hogy ő soha többé nem ... másik galambot a pultjánál!'::text,'szolgál ki'::text,'fog kiszolgálni'::text,'szolgál ki éppen'::text,'A macska azt üvölti, hogy ő soha többé nem szolgál ki másik galambot a pultjánál!'::text),
(384051,42673,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann hat dem Känguru dreimal die Brust ..., und es will ein viertes Mal.'::text,'gekrault'::text,'gekrault'::text,'kraulte'::text,'Der Mann hat dem Känguru dreimal die Brust gekrault, und es will ein viertes Mal.'::text),
(384055,42673,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... кенгуру груди тричі, а воно хоче й учетверте.'::text,'почухав'::text,'чухає'::text,'чухав'::text,'Чоловік почухав кенгуру груди тричі, а воно хоче й учетверте.'::text),
(384054,42673,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre le ... el pecho al canguro tres veces, y quiere una cuarta.'::text,'ha rascado'::text,'ha estado rascando'::text,'estaba rascando'::text,'El hombre le ha rascado el pecho al canguro tres veces, y quiere una cuarta.'::text),
(384053,42673,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... le torse du kangourou trois fois, et il en veut une quatrième.'::text,'a gratté'::text,'gratte depuis'::text,'grattait'::text,'L''homme a gratté le torse du kangourou trois fois, et il en veut une quatrième.'::text),
(384056,42673,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam kangurunun göğsünü üç kez ... ve o dördüncüyü istiyor.'::text,'kaşıdı'::text,'kaşıyor'::text,'kaşıyordu'::text,'Adam kangurunun göğsünü üç kez kaşıdı ve o dördüncüyü istiyor.'::text),
(384057,42673,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi háromszor ... a kenguru mellkasát, és az egy negyediket is akar.'::text,'megvakarta'::text,'vakarja'::text,'vakarta'::text,'A férfi háromszor megvakarta a kenguru mellkasát, és az egy negyediket is akar.'::text),
(391737,43527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zuerst weigerte sich das Rehkitz total, aus dieser Stahlrutsche ...!'::text,'zu klettern'::text,'kletternd'::text,'klettern'::text,'Zuerst weigerte sich das Rehkitz total, aus dieser Stahlrutsche zu klettern!'::text),
(391741,43527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спершу оленятко категорично відмовлялося ... з тієї сталевої гірки!'::text,'вилазити'::text,'вилазіння'::text,'вилазити'::text,'Спершу оленятко категорично відмовлялося вилазити з тієї сталевої гірки!'::text),
(391740,43527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Al principio el cervatillo se negó rotundamente a ... de ese tobogán de acero!'::text,'salir'::text,'saliendo'::text,'salir'::text,'¡Al principio el cervatillo se negó rotundamente a salir de ese tobogán de acero!'::text),
(391739,43527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au début, le faon refusait catégoriquement de ... de ce toboggan en acier !'::text,'sortir'::text,'sortant'::text,'sortir'::text,'Au début, le faon refusait catégoriquement de sortir de ce toboggan en acier !'::text),
(391742,43527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru geyik ilk başta o çelik kaydıraktan ... kesinlikle reddetti!'::text,'çıkmayı'::text,'çıkarak'::text,'çıkmak'::text,'Yavru geyik ilk başta o çelik kaydıraktan çıkmayı kesinlikle reddetti!'::text),
(391743,43527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az őzike eleinte egyáltalán nem volt hajlandó ... abból az acélcsúszdából!'::text,'kimászni'::text,'kimászva'::text,'kimászik'::text,'Az őzike eleinte egyáltalán nem volt hajlandó kimászni abból az acélcsúszdából!'::text),
(391791,43533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Rehkitz ... eine Weile in der Stahlrutsche, bevor es wegging.'::text,'lag'::text,'liegt'::text,'liegt'::text,'Das Rehkitz lag eine Weile in der Stahlrutsche, bevor es wegging.'::text),
(391795,43533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оленятко ... деякий час у сталевій гірці, перш ніж пішло.'::text,'лежало'::text,'лежить'::text,'лежить'::text,'Оленятко лежало деякий час у сталевій гірці, перш ніж пішло.'::text),
(391794,43533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cervatillo ... un rato en el tobogán de acero antes de marcharse.'::text,'había estado tumbado'::text,'ha estado tumbado'::text,'está tumbado'::text,'El cervatillo había estado tumbado un rato en el tobogán de acero antes de marcharse.'::text),
(391793,43533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le faon ... un moment dans le toboggan en acier avant de s''en aller.'::text,'était resté allongé'::text,'est resté allongé'::text,'est allongé'::text,'Le faon était resté allongé un moment dans le toboggan en acier avant de s''en aller.'::text),
(391796,43533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru geyik uzaklaşmadan önce bir süre çelik kaydırakta ...'::text,'yatmıştı'::text,'yatıyor'::text,'yatıyor'::text,'Yavru geyik uzaklaşmadan önce bir süre çelik kaydırakta yatmıştı.'::text),
(391797,43533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az őzike egy darabig ... az acélcsúszdában, mielőtt elsétált.'::text,'feküdt'::text,'fekszik'::text,'fekszik'::text,'Az őzike egy darabig feküdt az acélcsúszdában, mielőtt elsétált.'::text),
(352875,39209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Albtraum! Er ... weiter auf sein Tablet, während die Gestalt direkt hinter ihm stand.'::text,'schaute'::text,'zu schauen'::text,'schauen'::text,'Ein Albtraum! Er schaute weiter auf sein Tablet, während die Gestalt direkt hinter ihm stand.'::text),
(352879,39209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кошмар! Він продовжував ... у свій планшет, поки постать стояла прямо за ним.'::text,'дивитися'::text,'дивитися'::text,'дивитися'::text,'Кошмар! Він продовжував дивитися у свій планшет, поки постать стояла прямо за ним.'::text),
(352878,39209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una pesadilla! Él siguió ... su tablet mientras la figura estaba justo detrás de él.'::text,'mirando'::text,'a mirar'::text,'mirar'::text,'¡Una pesadilla! Él siguió mirando su tablet mientras la figura estaba justo detrás de él.'::text),
(352877,39209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un cauchemar ! Il a continué à ... sa tablette pendant que la silhouette se tenait juste derrière lui.'::text,'regarder'::text,'regarder'::text,'regarder'::text,'Un cauchemar ! Il a continué à regarder sa tablette pendant que la silhouette se tenait juste derrière lui.'::text),
(352880,39209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! O, figür tam arkasında dururken tabletini ... devam etti.'::text,'izlemeye'::text,'izlemek'::text,'izle'::text,'Kâbus! O, figür tam arkasında dururken tabletini izlemeye devam etti.'::text),
(352881,39209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Ő tovább ... a tabletjét, miközben az alak közvetlenül mögötte állt.'::text,'nézte'::text,'nézni'::text,'néz'::text,'Rémálom! Ő tovább nézte a tabletjét, miközben az alak közvetlenül mögötte állt.'::text),
(352965,39219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann hat alles verschlafen, sodass er die Gestalt in der Tür ...'::text,'unmöglich bemerkt haben kann'::text,'bemerkt haben muss'::text,'nicht bemerkt haben sollte'::text,'Der Mann hat alles verschlafen, sodass er die Gestalt in der Tür unmöglich bemerkt haben kann.'::text),
(352969,39219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік проспав усе, тож він ... постать у дверях.'::text,'не міг помітити'::text,'мусив помітити'::text,'не мав помітити'::text,'Чоловік проспав усе, тож він не міг помітити постать у дверях.'::text),
(352968,39219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre durmió todo el rato, así que él ... a la figura en la puerta.'::text,'no puede haber notado'::text,'tiene que haber notado'::text,'no debería haber notado'::text,'El hombre durmió todo el rato, así que él no puede haber notado a la figura en la puerta.'::text),
(352967,39219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a dormi pendant tout ce temps, donc il ... la silhouette dans l''embrasure de la porte.'::text,'n''a pas pu remarquer'::text,'a dû remarquer'::text,'n''aurait pas dû remarquer'::text,'L''homme a dormi pendant tout ce temps, donc il n''a pas pu remarquer la silhouette dans l''embrasure de la porte.'::text),
(352970,39219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam her şey boyunca uyudu, yani o kapıdaki figürü ...'::text,'fark etmiş olamaz'::text,'fark etmiş olmalı'::text,'fark etmemeliydi'::text,'Adam her şey boyunca uyudu, yani o kapıdaki figürü fark etmiş olamaz.'::text),
(352971,39219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi végigaludta az egészet, szóval ő ... az alakot az ajtóban.'::text,'nem vehette észre'::text,'biztosan észrevette'::text,'nem kellett volna észrevennie'::text,'A férfi végigaludta az egészet, szóval ő nem vehette észre az alakot az ajtóban.'::text),
(402672,44742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Jungtiere ... gerade über den Sand, als der Rabe die Flügel ausbreitete, wie es Wildtiere typischerweise tun.'::text,'liefen'::text,'liefen'::text,'sind gelaufen'::text,'Die Jungtiere liefen gerade über den Sand, als der Rabe die Flügel ausbreitete, wie es Wildtiere typischerweise tun.'::text),
(402676,44742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ведмежата ... піском, коли ворон розправив крила, як це зазвичай робить дика природа.'::text,'йшли'::text,'пройшли'::text,'пройшли'::text,'Ведмежата йшли піском, коли ворон розправив крила, як це зазвичай робить дика природа.'::text),
(402675,44742,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las crías ... por la arena cuando el cuervo extendió las alas, como suele hacer la fauna salvaje.'::text,'estaban caminando'::text,'caminaron'::text,'han caminado'::text,'Las crías estaban caminando por la arena cuando el cuervo extendió las alas, como suele hacer la fauna salvaje.'::text),
(402674,44742,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les oursons ... sur le sable quand le corbeau a déployé ses ailes, comme le fait typiquement la faune sauvage.'::text,'marchaient'::text,'ont marché'::text,'ont marché'::text,'Les oursons marchaient sur le sable quand le corbeau a déployé ses ailes, comme le fait typiquement la faune sauvage.'::text),
(402677,44742,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuzgun kanatlarını açtığında yavrular kumun üzerinde ..., tıpkı yaban hayatının tipik olarak yaptığı gibi.'::text,'yürüyordu'::text,'yürüdü'::text,'yürüdü'::text,'Kuzgun kanatlarını açtığında yavrular kumun üzerinde yürüyordu, tıpkı yaban hayatının tipik olarak yaptığı gibi.'::text),
(402678,44742,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bocsok éppen ... a homokon, amikor a holló kitárta a szárnyait, ahogy a vadon élő állatok jellemzően teszik.'::text,'sétáltak'::text,'átsétáltak'::text,'átsétáltak'::text,'A bocsok éppen sétáltak a homokon, amikor a holló kitárta a szárnyait, ahogy a vadon élő állatok jellemzően teszik.'::text),
(402708,44746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, also angeblich ... der Rabe Angst vor den Tieren gehabt haben, so schnell ist er abgehauen.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Ok, also angeblich muss der Rabe Angst vor den Tieren gehabt haben, so schnell ist er abgehauen.'::text),
(402712,44746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ок, отже, кажуть, ворон ... злякатися тих звірів, так швидко він утік.'::text,'мусив'::text,'мав би'::text,'не міг'::text,'Ок, отже, кажуть, ворон мусив злякатися тих звірів, так швидко він утік.'::text),
(402711,44746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues dicen que el cuervo ... tenido miedo de los animales, huyó tan rápido.'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'Vale, pues dicen que el cuervo debe de haber tenido miedo de los animales, huyó tan rápido.'::text),
(402710,44746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, la rumeur dit que le corbeau ... avoir eu peur des animaux, il s''est enfui tellement vite.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Bon, la rumeur dit que le corbeau a dû avoir eu peur des animaux, il s''est enfui tellement vite.'::text),
(402713,44746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, rivayete göre kuzgun hayvanlardan ..., o kadar hızlı kaçtı.'::text,'korkmuş olmalı'::text,'korkmalıydı'::text,'korkmuş olamaz'::text,'Tamam, rivayete göre kuzgun hayvanlardan korkmuş olmalı, o kadar hızlı kaçtı.'::text),
(402714,44746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval azt beszélik, a holló ... az állatoktól, olyan gyorsan elmenekült.'::text,'biztosan megijedt'::text,'meg kellett volna ijednie'::text,'nem ijedhetett meg'::text,'Oké, szóval azt beszélik, a holló biztosan megijedt az állatoktól, olyan gyorsan elmenekült.'::text),
(337692,37522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der grüne Papagei ... gerade, als der blaue ihn beruhigte. Ein makelloser Auftritt.'::text,'schrie'::text,'schrie'::text,'hat geschrien'::text,'Der grüne Papagei schrie gerade, als der blaue ihn beruhigte. Ein makelloser Auftritt.'::text),
(337696,37522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зелений папуга ..., коли синій його заспокоїв. Бездоганна поява.'::text,'кричав'::text,'закричав'::text,'закричав'::text,'Зелений папуга кричав, коли синій його заспокоїв. Бездоганна поява.'::text),
(337695,37522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El loro verde ... cuando el azul lo calmó. Una entrada impecable.'::text,'estaba gritando'::text,'gritó'::text,'ha gritado'::text,'El loro verde estaba gritando cuando el azul lo calmó. Una entrada impecable.'::text),
(337694,37522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le perroquet vert ... quand le bleu l''a calmé. Une entrée impeccable.'::text,'criait'::text,'a crié'::text,'a crié'::text,'Le perroquet vert criait quand le bleu l''a calmé. Une entrée impeccable.'::text),
(337697,37522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeşil papağan ..., o sırada mavi olan onu sakinleştirdi. Kusursuz bir giriş.'::text,'bağırıyordu'::text,'bağırdı'::text,'bağırdı'::text,'Yeşil papağan bağırıyordu, o sırada mavi olan onu sakinleştirdi. Kusursuz bir giriş.'::text),
(337698,37522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zöld papagáj éppen ..., amikor a kék megnyugtatta. Hibátlan belépő.'::text,'kiabált'::text,'kiáltott'::text,'kiáltott'::text,'A zöld papagáj éppen kiabált, amikor a kék megnyugtatta. Hibátlan belépő.'::text),
(337737,37527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der blaue Papagei, ... Umarmung den wütenden Vogel beruhigt hat, schließt die Augen.'::text,'dessen'::text,'welcher'::text,'der'::text,'Der blaue Papagei, dessen Umarmung den wütenden Vogel beruhigt hat, schließt die Augen.'::text),
(337741,37527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Синій папуга, ... обійми заспокоїли сердитого птаха, заплющує очі.'::text,'чиї'::text,'які'::text,'хто'::text,'Синій папуга, чиї обійми заспокоїли сердитого птаха, заплющує очі.'::text),
(337740,37527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El loro azul, ... abrazo calmó al pájaro enfadado, cierra los ojos.'::text,'cuyo'::text,'el cual'::text,'quien'::text,'El loro azul, cuyo abrazo calmó al pájaro enfadado, cierra los ojos.'::text),
(337739,37527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le perroquet bleu, ... le câlin a calmé l''oiseau en colère, ferme les yeux.'::text,'dont'::text,'lequel'::text,'qui'::text,'Le perroquet bleu, dont le câlin a calmé l''oiseau en colère, ferme les yeux.'::text),
(337742,37527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Sarılması öfkeli kuşu sakinleştiren mavi papağan gözlerini kapatıyor.'::text,''::text,NULL::text,NULL::text,'Sarılması öfkeli kuşu sakinleştiren mavi papağan gözlerini kapatıyor.'::text),
(337743,37527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kék papagáj, ... ölelése megnyugtatta a dühös madarat, becsukja a szemét.'::text,'aminek az'::text,'amely'::text,'aki'::text,'A kék papagáj, aminek az ölelése megnyugtatta a dühös madarat, becsukja a szemét.'::text),
(370740,41194,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... sieht ein Hund nach einem Haarschnitt so gepflegt aus. Mäßig beeindruckend.'::text,''::text,NULL::text,NULL::text,'Selten sieht ein Hund nach einem Haarschnitt so gepflegt aus. Mäßig beeindruckend.'::text),
(370744,41194,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... собака виглядає так охайно після стрижки. Помірно вражає.'::text,''::text,NULL::text,NULL::text,'Рідко собака виглядає так охайно після стрижки. Помірно вражає.'::text),
(370743,41194,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... un perro se ve tan arreglado después de un corte de pelo. Ligeramente impresionante.'::text,''::text,NULL::text,NULL::text,'Pocas veces un perro se ve tan arreglado después de un corte de pelo. Ligeramente impresionante.'::text),
(370742,41194,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un chien a l''air aussi soigné après une coupe. Vaguement impressionnant.'::text,''::text,NULL::text,NULL::text,'Rarement un chien a l''air aussi soigné après une coupe. Vaguement impressionnant.'::text),
(370745,41194,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... bir köpek tıraştan sonra bu kadar derli toplu görünür. Hafiften etkileyici.'::text,''::text,NULL::text,NULL::text,'Nadiren bir köpek tıraştan sonra bu kadar derli toplu görünür. Hafiften etkileyici.'::text),
(370746,41194,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... néz ki egy kutya ilyen rendezetten egy nyírás után. Enyhén lenyűgöző.'::text,''::text,NULL::text,NULL::text,'Ritkán néz ki egy kutya ilyen rendezetten egy nyírás után. Enyhén lenyűgöző.'::text),
(388353,43151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ente, ... auf die Strecke lief, hat meine beste Runde total ruiniert, und ich musste abbremsen!'::text,'die'::text,'deren'::text,'was'::text,'Die Ente, die auf die Strecke lief, hat meine beste Runde total ruiniert, und ich musste abbremsen!'::text),
(388357,43151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Качка, ... вийшла на трасу, повністю зіпсувала моє найкраще коло, і я мусив пригальмувати!'::text,'яка'::text,'чия'::text,'що'::text,'Качка, яка вийшла на трасу, повністю зіпсувала моє найкраще коло, і я мусив пригальмувати!'::text),
(388356,43151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El pato ... se metió en la pista arruinó por completo mi mejor vuelta, y yo tuve que frenar!'::text,'que'::text,'cuyo'::text,'lo que'::text,'¡El pato que se metió en la pista arruinó por completo mi mejor vuelta, y yo tuve que frenar!'::text),
(388355,43151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canard ... a débarqué sur la piste a complètement gâché mon meilleur tour, et j''ai dû ralentir !'::text,'qui'::text,'dont'::text,'ce que'::text,'Le canard qui a débarqué sur la piste a complètement gâché mon meilleur tour, et j''ai dû ralentir !'::text),
(388358,43151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Piste çıkan ördek en iyi turumu tamamen mahvetti ve ben yavaşlamak zorunda kaldım!'::text,''::text,NULL::text,NULL::text,'Piste çıkan ördek en iyi turumu tamamen mahvetti ve ben yavaşlamak zorunda kaldım!'::text),
(388359,43151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kacsa, ... kisétált a pályára, teljesen tönkretette a legjobb körömet, és én kénytelen voltam lassítani!'::text,'amelyik'::text,'akinek a'::text,'ami'::text,'A kacsa, amelyik kisétált a pályára, teljesen tönkretette a legjobb körömet, és én kénytelen voltam lassítani!'::text),
(340950,37884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das blaue Auto ... gerade über die Kreuzung, als der Zusammenstoß passierte.'::text,'fuhr'::text,'fuhr'::text,'ist gefahren'::text,'Das blaue Auto fuhr gerade über die Kreuzung, als der Zusammenstoß passierte.'::text),
(340954,37884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Синя машина ... через перехрестя, коли сталося зіткнення.'::text,'їхала'::text,'проїхала'::text,'проїхала'::text,'Синя машина їхала через перехрестя, коли сталося зіткнення.'::text),
(340953,37884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche azul ... por el cruce cuando ocurrió la colisión.'::text,'circulaba'::text,'pasó'::text,'ha pasado'::text,'El coche azul circulaba por el cruce cuando ocurrió la colisión.'::text),
(340952,37884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture bleue ... le carrefour quand la collision s''est produite.'::text,'traversait'::text,'a traversé'::text,'a traversé'::text,'La voiture bleue traversait le carrefour quand la collision s''est produite.'::text),
(340955,37884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çarpışma olduğunda mavi araba kavşaktan ...'::text,'geçiyordu'::text,'geçti'::text,'geçti'::text,'Çarpışma olduğunda mavi araba kavşaktan geçiyordu.'::text),
(340956,37884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kék autó éppen ... a kereszteződésen, amikor megtörtént az ütközés.'::text,'hajtott át'::text,'áthajtott'::text,'áthajtott'::text,'A kék autó éppen hajtott át a kereszteződésen, amikor megtörtént az ütközés.'::text),
(345603,38401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Der Transporter ... langsam an den Läden vorbei, als er krachte und diesen ganzen Schaden anrichtete.'::text,'fuhr'::text,'fuhr'::text,'fährt'::text,'Katastrophe! Der Transporter fuhr langsam an den Läden vorbei, als er krachte und diesen ganzen Schaden anrichtete.'::text),
(345607,38401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Фургон ... повільно повз магазини, коли врізався і наробив усієї цієї шкоди.'::text,'їхав'::text,'проїхав'::text,'їде'::text,'Катастрофа! Фургон їхав повільно повз магазини, коли врізався і наробив усієї цієї шкоди.'::text),
(345606,38401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! La furgoneta ... despacio junto a las tiendas cuando chocó e hizo todo este daño.'::text,'circulaba'::text,'pasó'::text,'pasa'::text,'¡Desastre! La furgoneta circulaba despacio junto a las tiendas cuando chocó e hizo todo este daño.'::text),
(345605,38401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! La camionnette ... lentement devant les magasins quand elle a eu l''accident et fait tous ces dégâts.'::text,'roulait'::text,'a roulé'::text,'roule'::text,'Catastrophe ! La camionnette roulait lentement devant les magasins quand elle a eu l''accident et fait tous ces dégâts.'::text),
(345608,38401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Kamyonet dükkânların önünden yavaşça ..., o sırada çarptı ve bütün bu hasarı verdi.'::text,'geçiyordu'::text,'geçti'::text,'geçiyor'::text,'Felaket! Kamyonet dükkânların önünden yavaşça geçiyordu, o sırada çarptı ve bütün bu hasarı verdi.'::text),
(345609,38401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A furgon lassan ... az üzletek mellett, amikor ütközött, és ezt a sok kárt okozta.'::text,'haladt el'::text,'elhaladt'::text,'halad el'::text,'Katasztrófa! A furgon lassan haladt el az üzletek mellett, amikor ütközött, és ezt a sok kárt okozta.'::text),
(345693,38411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Unfall hat ... am hinteren Kotflügel angerichtet, ein Albtraum für beide Fahrer!'::text,'schweren Schaden'::text,'einen schweren Schaden'::text,'den schweren Schaden'::text,'Der Unfall hat schweren Schaden am hinteren Kotflügel angerichtet, ein Albtraum für beide Fahrer!'::text),
(345697,38411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Аварія завдала ... задньому крилу, кошмар для обох водіїв!'::text,'серйозної шкоди'::text,'серйозної шкоди'::text,'серйозної шкоди'::text,'Аварія завдала серйозної шкоди задньому крилу, кошмар для обох водіїв!'::text),
(345696,38411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El choque le hizo ... a la aleta trasera, una pesadilla para los dos conductores!'::text,'daños graves'::text,'un daño grave'::text,'el daño grave'::text,'¡El choque le hizo daños graves a la aleta trasera, una pesadilla para los dos conductores!'::text),
(345695,38411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''accident a fait ... à l''aile arrière, un cauchemar pour les deux conducteurs !'::text,'de gros dégâts'::text,'un gros dégât'::text,'les gros dégâts'::text,'L''accident a fait de gros dégâts à l''aile arrière, un cauchemar pour les deux conducteurs !'::text),
(345698,38411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaza arka çamurlukta ... yarattı, iki sürücü için de tam bir kâbus!'::text,'ciddi hasar'::text,'ciddi bir hasar'::text,'ciddi hasar'::text,'Kaza arka çamurlukta ciddi hasar yarattı, iki sürücü için de tam bir kâbus!'::text),
(345699,38411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ütközés ... okozott a hátsó sárvédőn, rémálom mindkét sofőrnek!'::text,'komoly kárt'::text,'egy komoly kárt'::text,'a komoly kárt'::text,'Az ütközés komoly kárt okozott a hátsó sárvédőn, rémálom mindkét sofőrnek!'::text),
(328944,36550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, dass die Buchhalterin morgen um diese Zeit wieder Belege ...'::text,'prüfen wird'::text,'prüfen wird'::text,'prüft'::text,'Bestie, ich hab gehört, dass die Buchhalterin morgen um diese Zeit wieder Belege prüfen wird.'::text),
(328948,36550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, я чула, що завтра в цей час бухгалтерка знову ... чеки.'::text,'перевірятиме'::text,'перевірить'::text,'перевіряє'::text,'Бесті, я чула, що завтра в цей час бухгалтерка знову перевірятиме чеки.'::text),
(328947,36550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, yo he oído que mañana a esta hora la contable ... recibos otra vez.'::text,'estará revisando'::text,'revisará'::text,'revisa'::text,'Bestie, yo he oído que mañana a esta hora la contable estará revisando recibos otra vez.'::text),
(328946,36550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, j''ai entendu dire que demain à la même heure, la comptable ... encore des tickets de caisse.'::text,'sera en train de vérifier'::text,'vérifiera'::text,'vérifie'::text,'Bestie, j''ai entendu dire que demain à la même heure, la comptable sera en train de vérifier encore des tickets de caisse.'::text),
(328949,36550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ben duydum ki yarın bu saatlerde muhasebeci yine fişleri ...'::text,'kontrol ediyor olacakmış'::text,'kontrol edecekmiş'::text,'kontrol ediyormuş'::text,'Kanka, ben duydum ki yarın bu saatlerde muhasebeci yine fişleri kontrol ediyor olacakmış.'::text),
(328950,36550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, én úgy hallottam, holnap ilyenkor a könyvelő megint a blokkokat ...'::text,'fogja ellenőrizni'::text,'ellenőrzi majd'::text,'ellenőrzi'::text,'Csajszi, én úgy hallottam, holnap ilyenkor a könyvelő megint a blokkokat fogja ellenőrizni.'::text),
(329007,36557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht ... die Buchhalterin nur den halben Stapel geprüft. Toller Fortschritt, natürlich.'::text,'hat'::text,'wird'::text,'ist gerade dabei'::text,'Bis Mitternacht hat die Buchhalterin nur den halben Stapel geprüft. Toller Fortschritt, natürlich.'::text),
(329011,36557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі бухгалтерка ... лише половину стосу. Чудовий прогрес, звісно.'::text,'перевірить'::text,'перевірить'::text,'перевірятиме'::text,'До півночі бухгалтерка перевірить лише половину стосу. Чудовий прогрес, звісно.'::text),
(329010,36557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para medianoche la contable ... solo la mitad del montón. Gran progreso, obviamente.'::text,'habrá revisado'::text,'revisará'::text,'estará revisando'::text,'Para medianoche la contable habrá revisado solo la mitad del montón. Gran progreso, obviamente.'::text),
(329009,36557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, la comptable ... seulement la moitié de la pile. Super progrès, évidemment.'::text,'aura vérifié'::text,'vérifiera'::text,'sera en train de vérifier'::text,'D''ici minuit, la comptable aura vérifié seulement la moitié de la pile. Super progrès, évidemment.'::text),
(329012,36557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhasebeci gece yarısına kadar yığının sadece yarısını ...; harika bir ilerleme, tabii ki.'::text,'kontrol etmiş olacak'::text,'kontrol edecek'::text,'kontrol ediyor olacak'::text,'Muhasebeci gece yarısına kadar yığının sadece yarısını kontrol etmiş olacak; harika bir ilerleme, tabii ki.'::text),
(329013,36557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre a könyvelő ... a kupacnak csak a felét. Remek haladás, nyilvánvalóan.'::text,'ellenőrzi'::text,'ellenőrizni fogja'::text,'ellenőrizni fogja'::text,'Éjfélre a könyvelő ellenőrzi a kupacnak csak a felét. Remek haladás, nyilvánvalóan.'::text),
(353136,39238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Dreh der Weinszene ... jetzt schon seit drei Stunden.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Der Dreh der Weinszene läuft jetzt schon seit drei Stunden.'::text),
(353140,39238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зйомки сцени з плачем ... вже три години.'::text,'тривають'::text,'тривають'::text,'тривають'::text,'Зйомки сцени з плачем тривають вже три години.'::text),
(353139,39238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El rodaje de la escena del llanto ... ya tres horas.'::text,'lleva'::text,'está durando'::text,'dura'::text,'El rodaje de la escena del llanto lleva ya tres horas.'::text),
(353138,39238,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tournage de la scène de pleurs ... depuis trois heures maintenant.'::text,'dure'::text,'dure'::text,'dure'::text,'Le tournage de la scène de pleurs dure depuis trois heures maintenant.'::text),
(353141,39238,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağlama sahnesinin çekimi artık üç saattir ...'::text,'sürüyor'::text,'sürüyor'::text,'sürer'::text,'Ağlama sahnesinin çekimi artık üç saattir sürüyor.'::text),
(353142,39238,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sírós jelenet forgatása már három órája ...'::text,'tart'::text,'tart'::text,'tart'::text,'A sírós jelenet forgatása már három órája tart.'::text),
(385779,42865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... den Hund gerade durchs Gitter, als die Tür des Tierheims aufging, und ehrlich, Respekt.'::text,'begrüßtest'::text,'begrüßtest'::text,'hast begrüßt'::text,'Du begrüßtest den Hund gerade durchs Gitter, als die Tür des Tierheims aufging, und ehrlich, Respekt.'::text),
(385783,42865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... пса крізь сітку, коли відчинилися двері притулку, і чесно, респект.'::text,'вітав'::text,'привітав'::text,'привітав'::text,'Ти вітав пса крізь сітку, коли відчинилися двері притулку, і чесно, респект.'::text),
(385782,42865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... al perro a través de la malla cuando se abrió la puerta del refugio, y sinceramente, respeto.'::text,'estabas saludando'::text,'saludaste'::text,'has saludado'::text,'Tú estabas saludando al perro a través de la malla cuando se abrió la puerta del refugio, y sinceramente, respeto.'::text),
(385781,42865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le chien à travers le grillage quand la porte du refuge s''est ouverte, et franchement, respect.'::text,'saluais'::text,'as salué'::text,'as salué'::text,'Tu saluais le chien à travers le grillage quand la porte du refuge s''est ouverte, et franchement, respect.'::text),
(385784,42865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barınağın kapısı açıldığında sen köpeği telin arasından ... ve açıkçası, saygı.'::text,'selamlıyordun'::text,'selamladın'::text,'selamladın'::text,'Barınağın kapısı açıldığında sen köpeği telin arasından selamlıyordun ve açıkçası, saygı.'::text),
(385785,42865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te épp ... a kutyát a rácson keresztül, amikor kinyílt a menhely ajtaja, és őszintén, respekt.'::text,'üdvözölted'::text,'üdvözölted'::text,'üdvözölted'::text,'Te épp üdvözölted a kutyát a rácson keresztül, amikor kinyílt a menhely ajtaja, és őszintén, respekt.'::text),
(385869,42875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mitarbeiterin ... die Formulare schon abgestempelt, als das Paar den Ausgang des Tierheims erreichte.'::text,'hatte'::text,'hat'::text,'wurde'::text,'Die Mitarbeiterin hatte die Formulare schon abgestempelt, als das Paar den Ausgang des Tierheims erreichte.'::text),
(385873,42875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Працівниця ... бланки ще до того, як пара дійшла до виходу з притулку.'::text,'проштампувала'::text,'проштампувала'::text,'була проштампована'::text,'Працівниця проштампувала бланки ще до того, як пара дійшла до виходу з притулку.'::text),
(385872,42875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La empleada ya ... los formularios cuando la pareja llegó a la salida del refugio.'::text,'había sellado'::text,'ha sellado'::text,'fue sellada'::text,'La empleada ya había sellado los formularios cuando la pareja llegó a la salida del refugio.'::text),
(385871,42875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''employée ... les formulaires au moment où le couple a atteint la sortie du refuge.'::text,'avait tamponné'::text,'a tamponné'::text,'a été tamponnée'::text,'L''employée avait tamponné les formulaires au moment où le couple a atteint la sortie du refuge.'::text),
(385874,42875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çift barınağın çıkışına vardığında görevli formları çoktan ...'::text,'damgalamıştı'::text,'damgaladı'::text,'damgalandı'::text,'Çift barınağın çıkışına vardığında görevli formları çoktan damgalamıştı.'::text),
(385875,42875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a pár a menhely kijáratához ért, a munkatárs már ... a nyomtatványokat.'::text,'lepecsételte'::text,'lepecsételte'::text,'le lett pecsételve'::text,'Mire a pár a menhely kijáratához ért, a munkatárs már lepecsételte a nyomtatványokat.'::text),
(352146,39128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich gerade im Liegestuhl Luft zu, als das Eis in ihrer Limonade schmolz.'::text,'fächelte'::text,'fächelte'::text,'hat gefächelt'::text,'Sie fächelte sich gerade im Liegestuhl Luft zu, als das Eis in ihrer Limonade schmolz.'::text),
(352150,39128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... себе у шезлонгу, коли лід у її лимонаді розтанув.'::text,'обмахувала'::text,'обмахнула'::text,'обмахнула'::text,'Вона обмахувала себе у шезлонгу, коли лід у її лимонаді розтанув.'::text),
(352149,39128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella se ... en la tumbona cuando se derritió el hielo de su limonada.'::text,'estaba abanicando'::text,'abanicó'::text,'ha abanicado'::text,'Ella se estaba abanicando en la tumbona cuando se derritió el hielo de su limonada.'::text),
(352148,39128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans le transat quand la glace de sa limonade a fondu.'::text,'s''éventait'::text,'s''est éventée'::text,'s''est éventée'::text,'Elle s''éventait dans le transat quand la glace de sa limonade a fondu.'::text),
(352151,39128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Limonatasındaki buz eridiğinde o şezlongda kendini ...'::text,'yelpazeliyordu'::text,'yelpazeledi'::text,'yelpazeledi'::text,'Limonatasındaki buz eridiğinde o şezlongda kendini yelpazeliyordu.'::text),
(352152,39128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő épp ... magát a nyugágyban, amikor elolvadt a jég a limonádéjában.'::text,'legyezte'::text,'meglegyezte'::text,'meglegyezte'::text,'Ő épp legyezte magát a nyugágyban, amikor elolvadt a jég a limonádéjában.'::text),
(400746,44528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lachen, als sie die Schlüssel nehmen, also ... ihnen die Wohnung, die sie besichtigt haben, gefallen haben.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sie lachen, als sie die Schlüssel nehmen, also muss ihnen die Wohnung, die sie besichtigt haben, gefallen haben.'::text),
(400750,44528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони сміються, коли беруть ключі, тож квартира, яку вони оглянули, ... їм сподобатися.'::text,'мусила'::text,'не могла'::text,'мала б'::text,'Вони сміються, коли беруть ключі, тож квартира, яку вони оглянули, мусила їм сподобатися.'::text),
(400749,44528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos se ríen mientras cogen las llaves, así que ... de haberles gustado el piso que vieron.'::text,'debe'::text,'no puede'::text,'debería'::text,'Ellos se ríen mientras cogen las llaves, así que debe de haberles gustado el piso que vieron.'::text),
(400748,44528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils rient en prenant les clés, donc l''appart qu''ils ont visité ... leur plaire.'::text,'a dû'::text,'n''a pas pu'::text,'aurait dû'::text,'Ils rient en prenant les clés, donc l''appart qu''ils ont visité a dû leur plaire.'::text),
(400751,44528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar anahtarları alırken gülüyorlar, yani gezdikleri daireyi ...'::text,'beğenmiş olmalılar'::text,'beğenmiş olamazlar'::text,'beğenmeliydiler'::text,'Onlar anahtarları alırken gülüyorlar, yani gezdikleri daireyi beğenmiş olmalılar.'::text),
(400752,44528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők nevetnek, ahogy átveszik a kulcsokat, szóval a lakás, amit megnéztek, ... nekik.'::text,'biztosan tetszett'::text,'nem tetszhetett'::text,'tetszenie kellett volna'::text,'Ők nevetnek, ahogy átveszik a kulcsokat, szóval a lakás, amit megnéztek, biztosan tetszett nekik.'::text),
(400809,44535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... monatelang Wohnungen besichtigt, bevor diese hier endlich den Albtraum beendete!'::text,'hatten'::text,'haben'::text,'waren'::text,'Sie hatten monatelang Wohnungen besichtigt, bevor diese hier endlich den Albtraum beendete!'::text),
(400813,44535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... квартири місяцями, перш ніж ця нарешті завершила кошмар!'::text,'оглядали'::text,'оглядають'::text,'оглядали'::text,'Вони оглядали квартири місяцями, перш ніж ця нарешті завершила кошмар!'::text),
(400812,44535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... pisos durante meses antes de que este por fin acabara con la pesadilla!'::text,'habían estado viendo'::text,'han estado viendo'::text,'estaban viendo'::text,'¡Ellos habían estado viendo pisos durante meses antes de que este por fin acabara con la pesadilla!'::text),
(400811,44535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... des apparts pendant des mois avant que celui-ci mette enfin fin au cauchemar !'::text,'avaient visité'::text,'ont visité'::text,'visitaient'::text,'Ils avaient visité des apparts pendant des mois avant que celui-ci mette enfin fin au cauchemar !'::text),
(400814,44535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar, bu daire nihayet kâbusa son verene kadar aylarca daire ...!'::text,'gezmişlerdi'::text,'geziyorlar'::text,'geziyorlardı'::text,'Onlar, bu daire nihayet kâbusa son verene kadar aylarca daire gezmişlerdi!'::text),
(400815,44535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők hónapokig ... lakásokat, mielőtt ez végre véget vetett a rémálomnak!'::text,'nézegettek'::text,'nézegetnek'::text,'nézegettek'::text,'Ők hónapokig nézegettek lakásokat, mielőtt ez végre véget vetett a rémálomnak!'::text),
(342471,38053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er aufstand, ... die Klimaanlage den Raum schon etwas abgekühlt.'::text,'hatte'::text,'hat'::text,'kühlt'::text,'Als er aufstand, hatte die Klimaanlage den Raum schon etwas abgekühlt.'::text),
(342475,38053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він підвівся, кондиціонер уже трохи ... кімнату.'::text,'охолодив'::text,'охолодив'::text,'охолоджує'::text,'Поки він підвівся, кондиціонер уже трохи охолодив кімнату.'::text),
(342474,38053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando él se levantó, el aire acondicionado ya ... un poco la habitación.'::text,'había enfriado'::text,'ha enfriado'::text,'enfría'::text,'Para cuando él se levantó, el aire acondicionado ya había enfriado un poco la habitación.'::text),
(342473,38053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où il s''est levé, la clim ... un peu la pièce.'::text,'avait rafraîchi'::text,'a rafraîchi'::text,'rafraîchit'::text,'Au moment où il s''est levé, la clim avait rafraîchi un peu la pièce.'::text),
(342476,38053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ayağa kalktığında klima odayı biraz ...'::text,'serinletmişti'::text,'serinletti'::text,'serinletir'::text,'O ayağa kalktığında klima odayı biraz serinletmişti.'::text),
(342477,38053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ő felállt, a légkondi már kicsit ... a szobát.'::text,'lehűtötte'::text,'lehűtötte'::text,'hűti'::text,'Mire ő felállt, a légkondi már kicsit lehűtötte a szobát.'::text),
(342516,38058,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ließ die Klimaanlage in einer Minute die ganze Wohnung ...; eindeutig eine kleine Bitte.'::text,'abkühlen'::text,'abzukühlen'::text,'abgekühlt'::text,'Er ließ die Klimaanlage in einer Minute die ganze Wohnung abkühlen; eindeutig eine kleine Bitte.'::text),
(342520,38058,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він змусив кондиціонер ... всю квартиру за хвилину. Явно маленьке прохання.'::text,'охолодити'::text,'охолодити'::text,'охолоджений'::text,'Він змусив кондиціонер охолодити всю квартиру за хвилину. Явно маленьке прохання.'::text),
(342519,38058,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él hizo que el aire acondicionado ... todo el piso en un minuto. Claramente una petición pequeña.'::text,'enfriara'::text,'enfriar'::text,'enfriado'::text,'Él hizo que el aire acondicionado enfriara todo el piso en un minuto. Claramente una petición pequeña.'::text),
(342518,38058,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a laissé la clim ... tout l''appart en une minute. Clairement une petite demande.'::text,'refroidir'::text,'de refroidir'::text,'refroidi'::text,'Il a laissé la clim refroidir tout l''appart en une minute. Clairement une petite demande.'::text),
(342521,38058,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, klimaya bütün daireyi bir dakikada ...; belli ki küçük bir ricaydı.'::text,'soğutturdu'::text,'soğutmayı'::text,'soğutulmuş'::text,'O, klimaya bütün daireyi bir dakikada soğutturdu; belli ki küçük bir ricaydı.'::text),
(342522,38058,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a légkondival ... az egész lakást egy perc alatt. Egyértelműen kis kérés.'::text,'lehűttette'::text,'lehűteni'::text,'lehűtött'::text,'Ő a légkondival lehűttette az egész lakást egy perc alatt. Egyértelműen kis kérés.'::text),
(355773,39531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Stirn ist nass, weil er den ganzen Nachmittag in der Hitze ...'::text,'gesessen hat'::text,'sitzt'::text,'sitzt'::text,'Seine Stirn ist nass, weil er den ganzen Nachmittag in der Hitze gesessen hat.'::text),
(355777,39531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його чоло мокре, бо він ... у спеці все пообіддя.'::text,'сидить'::text,'сидить'::text,'сидить'::text,'Його чоло мокре, бо він сидить у спеці все пообіддя.'::text),
(355776,39531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su frente está mojada porque él ... toda la tarde al calor.'::text,'ha estado sentado'::text,'está sentado'::text,'se sienta'::text,'Su frente está mojada porque él ha estado sentado toda la tarde al calor.'::text),
(355775,39531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a le front mouillé parce qu''il ... dans la chaleur tout l''après-midi.'::text,'est resté assis'::text,'est assis'::text,'s''assoit'::text,'Il a le front mouillé parce qu''il est resté assis dans la chaleur tout l''après-midi.'::text),
(355778,39531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alnı ıslak, çünkü o bütün öğleden sonra sıcakta ...'::text,'oturuyor'::text,'oturuyor'::text,'oturur'::text,'Alnı ıslak, çünkü o bütün öğleden sonra sıcakta oturuyor.'::text),
(355779,39531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A homloka nedves, mert ő egész délután ... a hőségben.'::text,'ült'::text,'ül'::text,'ül'::text,'A homloka nedves, mert ő egész délután ült a hőségben.'::text),
(355836,39538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... seine Stirn vor Schweiß. Makellose Planung, eindeutig.'::text,'glänzt'::text,'glänzt'::text,'hat geglänzt'::text,'Gerade glänzt seine Stirn vor Schweiß. Makellose Planung, eindeutig.'::text),
(355840,39538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз його чоло ... від поту. Бездоганне планування, явно.'::text,'блищить'::text,'блищить'::text,'блищало'::text,'Саме зараз його чоло блищить від поту. Бездоганне планування, явно.'::text),
(355839,39538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo su frente ... de sudor. Una planificación impecable, claramente.'::text,'está brillando'::text,'brilla'::text,'ha brillado'::text,'Ahora mismo su frente está brillando de sudor. Una planificación impecable, claramente.'::text),
(355838,39538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, son front ... de sueur. Planification impeccable, clairement.'::text,'brille'::text,'brille'::text,'a brillé'::text,'En ce moment, son front brille de sueur. Planification impeccable, clairement.'::text),
(355841,39538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda alnı terden ...; kusursuz planlama, belli ki.'::text,'parlıyor'::text,'parlar'::text,'parladı'::text,'Şu anda alnı terden parlıyor; kusursuz planlama, belli ki.'::text),
(355842,39538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a homloka ... az izzadságtól. Hibátlan tervezés, egyértelműen.'::text,'fénylik'::text,'fénylik'::text,'fénylett'::text,'Épp most a homloka fénylik az izzadságtól. Hibátlan tervezés, egyértelműen.'::text),
(373773,41531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er hat ''ne Profikamera und wartet am Zaun, also ... er oft Flugzeuge fotografieren, echt.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Bro, er hat ''ne Profikamera und wartet am Zaun, also muss er oft Flugzeuge fotografieren, echt.'::text),
(373777,41531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у нього профі-камера, і він чекає біля паркану, тож він ... фотографувати літаки досить часто, реально.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Бро, у нього профі-камера, і він чекає біля паркану, тож він мусить фотографувати літаки досить часто, реально.'::text),
(373776,41531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él tiene una cámara pro y espera en la valla, así que ... de fotografiar aviones un montón, en serio.'::text,'debe'::text,'no puede'::text,'no debería'::text,'Bro, él tiene una cámara pro y espera en la valla, así que debe de fotografiar aviones un montón, en serio.'::text),
(373775,41531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il a un appareil pro et il attend à la clôture, donc il ... photographier des avions souvent, sérieux.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Frérot, il a un appareil pro et il attend à la clôture, donc il doit photographier des avions souvent, sérieux.'::text),
(373778,41531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun profesyonel bir fotoğraf makinesi var ve çitin yanında bekliyor, yani o uçakların fotoğrafını çok ..., cidden.'::text,'çekiyor olmalı'::text,'çekiyor olamaz'::text,'çekmemeli'::text,'Kanka, onun profesyonel bir fotoğraf makinesi var ve çitin yanında bekliyor, yani o uçakların fotoğrafını çok çekiyor olmalı, cidden.'::text),
(373779,41531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, profi gépe van, és a kerítésnél vár, szóval ő ... repülőket, komolyan.'::text,'biztos sokat fotóz'::text,'nem fotózhat sokat'::text,'nem kéne sokat fotóznia'::text,'Tesó, profi gépe van, és a kerítésnél vár, szóval ő biztos sokat fotóz repülőket, komolyan.'::text),
(373818,41536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit 2019 an diesem Zaun Flugzeuge. Offensichtlich ein sehr lockeres Hobby.'::text,'fotografiert'::text,'fotografiert gerade'::text,'fotografiert'::text,'Er fotografiert seit 2019 an diesem Zaun Flugzeuge. Offensichtlich ein sehr lockeres Hobby.'::text),
(373822,41536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... літаки біля цього паркану з 2019 року. Очевидно, дуже невимушене хобі.'::text,'фотографує'::text,'фотографує'::text,'фотографує'::text,'Він фотографує літаки біля цього паркану з 2019 року. Очевидно, дуже невимушене хобі.'::text),
(373821,41536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... aviones en esta valla desde 2019. Obviamente, una afición muy casual.'::text,'ha estado fotografiando'::text,'está fotografiando'::text,'fotografía'::text,'Él ha estado fotografiando aviones en esta valla desde 2019. Obviamente, una afición muy casual.'::text),
(373820,41536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des avions à cette clôture depuis 2019. Visiblement un passe-temps très décontracté.'::text,'photographie'::text,'est en train de photographier'::text,'photographie'::text,'Il photographie des avions à cette clôture depuis 2019. Visiblement un passe-temps très décontracté.'::text),
(373823,41536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, 2019''dan beri bu çitin yanında uçakları ...; belli ki çok sıradan bir hobi.'::text,'fotoğraflıyor'::text,'fotoğraflıyor'::text,'fotoğraflar'::text,'O, 2019''dan beri bu çitin yanında uçakları fotoğraflıyor; belli ki çok sıradan bir hobi.'::text),
(373824,41536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő 2019 óta ... a repülőket ennél a kerítésnél. Nyilvánvalóan egy nagyon laza hobbi.'::text,'fotózza'::text,'fotózza'::text,'fotózza'::text,'Ő 2019 óta fotózza a repülőket ennél a kerítésnél. Nyilvánvalóan egy nagyon laza hobbi.'::text),
(387183,43021,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Einweiser ... dem Flugzeug gerade ein Signal, als ein Koffer vom Gepäckwagen fiel.'::text,'gaben'::text,'gaben'::text,'haben gegeben'::text,'Die Einweiser gaben dem Flugzeug gerade ein Signal, als ein Koffer vom Gepäckwagen fiel.'::text),
(387187,43021,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Регулювальники ... літаку сигнал, коли з багажного візка впала валіза.'::text,'подавали'::text,'подали'::text,'подали'::text,'Регулювальники подавали літаку сигнал, коли з багажного візка впала валіза.'::text),
(387186,43021,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los señalizadores le ... una señal al avión cuando una maleta se cayó del carro de equipajes.'::text,'estaban haciendo'::text,'hicieron'::text,'han hecho'::text,'Los señalizadores le estaban haciendo una señal al avión cuando una maleta se cayó del carro de equipajes.'::text),
(387185,43021,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les placeurs ... un signal à l''avion quand une valise est tombée du chariot à bagages.'::text,'faisaient'::text,'ont fait'::text,'ont fait'::text,'Les placeurs faisaient un signal à l''avion quand une valise est tombée du chariot à bagages.'::text),
(387188,43021,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bagaj arabasından bir bavul düştüğünde yer görevlileri uçağa işaret ...'::text,'veriyordu'::text,'verdi'::text,'verdi'::text,'Bagaj arabasından bir bavul düştüğünde yer görevlileri uçağa işaret veriyordu.'::text),
(387189,43021,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A beállítók épp jelet ... a gépnek, amikor leesett egy bőrönd a poggyászkocsiról.'::text,'adtak'::text,'adtak'::text,'adtak'::text,'A beállítók épp jelet adtak a gépnek, amikor leesett egy bőrönd a poggyászkocsiról.'::text),
(346584,38510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... vor einem Abflug nervös, aber jetzt liebt sie Flughäfen.'::text,'war früher'::text,'wäre'::text,'war es gewohnt'::text,'Sie war früher vor einem Abflug nervös, aber jetzt liebt sie Flughäfen.'::text),
(346588,38510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... перед вильотом, але тепер обожнює аеропорти.'::text,'колись нервувала'::text,'нервувала б'::text,'звикла нервувати'::text,'Вона колись нервувала перед вильотом, але тепер обожнює аеропорти.'::text),
(346587,38510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... ponerse nerviosa antes de una salida, pero ahora le encantan los aeropuertos.'::text,'solía'::text,'iba a'::text,'estaba acostumbrada a'::text,'Ella solía ponerse nerviosa antes de una salida, pero ahora le encantan los aeropuertos.'::text),
(346586,38510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... nerveuse avant un départ, mais maintenant elle adore les aéroports.'::text,'était avant'::text,'serait'::text,'était habituée à être'::text,'Elle était avant nerveuse avant un départ, mais maintenant elle adore les aéroports.'::text),
(346589,38510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kalkıştan önce ..., ama artık havalimanlarına bayılıyor.'::text,'eskiden gergin olurdu'::text,'gergin olurdu'::text,'gergin olmaya alışkındı'::text,'O, kalkıştan önce eskiden gergin olurdu, ama artık havalimanlarına bayılıyor.'::text),
(346590,38510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... indulás előtt, de most imádja a reptereket.'::text,'régen ideges volt'::text,'ideges lenne'::text,'hozzá volt szokva, hogy ideges legyen'::text,'Ő régen ideges volt indulás előtt, de most imádja a reptereket.'::text),
(346611,38513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, also angeblich ... sie über ihren Abflug, seit sie hier ist.'::text,'redet'::text,'redet gerade'::text,'redet'::text,'Ok, also angeblich redet sie über ihren Abflug, seit sie hier ist.'::text),
(346615,38513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ок, отже, кажуть, вона ... про свій виліт, відколи сюди приїхала.'::text,'говорить'::text,'говорить'::text,'говорить'::text,'Ок, отже, кажуть, вона говорить про свій виліт, відколи сюди приїхала.'::text),
(346614,38513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ella ... de su salida desde que llegó.'::text,'lleva hablando'::text,'está hablando'::text,'habla'::text,'Vale, pues al parecer ella lleva hablando de su salida desde que llegó.'::text),
(346613,38513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment elle ... de son départ depuis qu''elle est arrivée.'::text,'parle'::text,'est en train de parler'::text,'parle'::text,'Bon, apparemment elle parle de son départ depuis qu''elle est arrivée.'::text),
(346616,38513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre o buraya geldiğinden beri kalkışından ...'::text,'bahsediyormuş'::text,'bahsediyor'::text,'bahseder'::text,'Tamam, duyduğuma göre o buraya geldiğinden beri kalkışından bahsediyormuş.'::text),
(346617,38513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ő azóta az indulásáról ..., hogy ideért.'::text,'beszél'::text,'beszél'::text,'beszél'::text,'Oké, szóval állítólag ő azóta az indulásáról beszél, hogy ideért.'::text),
(378975,42109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er eine Katze berührt, ... sein Körper sofort. Absolute Katastrophe!'::text,'reagiert'::text,'reagierte'::text,'wird reagieren'::text,'Wenn er eine Katze berührt, reagiert sein Körper sofort. Absolute Katastrophe!'::text),
(378979,42109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він торкнеться кота, його тіло ... миттєво. Повна катастрофа!'::text,'реагує'::text,'відреагувало'::text,'відреагує'::text,'Якщо він торкнеться кота, його тіло реагує миттєво. Повна катастрофа!'::text),
(378978,42109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él toca un gato, su cuerpo ... al instante. ¡Un desastre total!'::text,'reacciona'::text,'reaccionó'::text,'reaccionará'::text,'Si él toca un gato, su cuerpo reacciona al instante. ¡Un desastre total!'::text),
(378977,42109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il touche un chat, son corps ... instantanément. Catastrophe absolue !'::text,'réagit'::text,'a réagi'::text,'réagira'::text,'S''il touche un chat, son corps réagit instantanément. Catastrophe absolue !'::text),
(378980,42109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bir kediye dokunursa vücudu anında ...; tam bir felaket!'::text,'tepki verir'::text,'tepki verdi'::text,'tepki verecek'::text,'O bir kediye dokunursa vücudu anında tepki verir; tam bir felaket!'::text),
(378981,42109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő hozzáér egy macskához, a teste ... azonnal. Abszolút katasztrófa!'::text,'reagál'::text,'reagált'::text,'reagálni fog'::text,'Ha ő hozzáér egy macskához, a teste reagál azonnal. Abszolút katasztrófa!'::text),
(379047,42117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, er ... nicht so heftig auf Katzen.'::text,'reagierte'::text,'reagiert'::text,'wird reagieren'::text,'Er wünschte, er reagierte nicht so heftig auf Katzen.'::text),
(379051,42117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб ... так сильно на котів.'::text,'не реагував'::text,'не реагує'::text,'не реагуватиме'::text,'Він хотів би, щоб не реагував так сильно на котів.'::text),
(379050,42117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía ... tan fuerte a los gatos.'::text,'no reaccionar'::text,'no reacciona'::text,'no reaccionará'::text,'Él desearía no reaccionar tan fuerte a los gatos.'::text),
(379049,42117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il voudrait ne pas ... aussi fort aux chats.'::text,'réagir'::text,'réagit'::text,'réagira'::text,'Il voudrait ne pas réagir aussi fort aux chats.'::text),
(379052,42117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, keşke kedilere bu kadar kötü ... diyor.'::text,'tepki vermese'::text,'tepki vermiyor'::text,'tepki vermeyecek'::text,'O, keşke kedilere bu kadar kötü tepki vermese diyor.'::text),
(379053,42117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt szeretné, ha nem ... ennyire a macskákra.'::text,'reagálna'::text,'reagál'::text,'fog reagálni'::text,'Ő azt szeretné, ha nem reagálna ennyire a macskákra.'::text),
(382638,42516,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mülltonnen in dieser Gasse ... seit Tagen vor Müll über, und niemand hat sie geleert.'::text,'quellen'::text,'quellen'::text,'quellen'::text,'Die Mülltonnen in dieser Gasse quellen seit Tagen vor Müll über, und niemand hat sie geleert.'::text),
(382642,42516,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Смітники в цьому провулку ... сміттям уже кілька днів, і ніхто їх не спорожнив.'::text,'переповнені'::text,'переповнені'::text,'переповнюються'::text,'Смітники в цьому провулку переповнені сміттям уже кілька днів, і ніхто їх не спорожнив.'::text),
(382641,42516,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los cubos de esta callejuela ... de basura desde hace días, y nadie los ha vaciado.'::text,'están rebosando'::text,'están rebosando'::text,'rebosan'::text,'Los cubos de esta callejuela están rebosando de basura desde hace días, y nadie los ha vaciado.'::text),
(382640,42516,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les poubelles de cette ruelle ... d''ordures depuis des jours, et personne ne les a vidées.'::text,'débordent'::text,'débordent'::text,'débordent'::text,'Les poubelles de cette ruelle débordent d''ordures depuis des jours, et personne ne les a vidées.'::text),
(382643,42516,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sokaktaki çöp kutuları günlerdir çöple ... ve kimse onları boşaltmadı.'::text,'taşıyor'::text,'taşıyor'::text,'taşar'::text,'Bu sokaktaki çöp kutuları günlerdir çöple taşıyor ve kimse onları boşaltmadı.'::text),
(382644,42516,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a sikátorban a kukák napok óta ... a szeméttől, és senki sem ürítette ki őket.'::text,'túlcsordulnak'::text,'túlcsordulnak'::text,'túlcsordulnak'::text,'Ebben a sikátorban a kukák napok óta túlcsordulnak a szeméttől, és senki sem ürítette ki őket.'::text),
(357402,39712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wände auf beiden Seiten des Spalts ... vor vielen Jahren blau gestrichen.'::text,'wurden'::text,'strichen'::text,'werden'::text,'Die Wände auf beiden Seiten des Spalts wurden vor vielen Jahren blau gestrichen.'::text),
(357406,39712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стіни з обох боків проходу ... в синій колір багато років тому.'::text,'були пофарбовані'::text,'пофарбували'::text,'пофарбовані'::text,'Стіни з обох боків проходу були пофарбовані в синій колір багато років тому.'::text),
(357405,39712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las paredes a ambos lados del hueco ... de azul hace muchos años.'::text,'fueron pintadas'::text,'pintaron'::text,'están pintadas'::text,'Las paredes a ambos lados del hueco fueron pintadas de azul hace muchos años.'::text),
(357404,39712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les murs des deux côtés de l''interstice ... en bleu il y a de nombreuses années.'::text,'ont été peints'::text,'ont peint'::text,'sont peints'::text,'Les murs des deux côtés de l''interstice ont été peints en bleu il y a de nombreuses années.'::text),
(357407,39712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşluğun iki yanındaki duvarlar yıllar önce maviye ...'::text,'boyandı'::text,'boyadı'::text,'boyanıyor'::text,'Boşluğun iki yanındaki duvarlar yıllar önce maviye boyandı.'::text),
(357408,39712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rés két oldalán lévő falakat sok évvel ezelőtt kékre ...'::text,'festették'::text,'festették'::text,'festik'::text,'A rés két oldalán lévő falakat sok évvel ezelőtt kékre festették.'::text),
(357411,39713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast dich durch diese Lücke gequetscht wie ... Profi.'::text,'ein'::text,'der'::text,'ein'::text,'Ehrlich, du hast dich durch diese Lücke gequetscht wie ein Profi.'::text),
(357415,39713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти протиснувся крізь цю щілину, як ... експерт.'::text,''::text,NULL::text,NULL::text,'Чесно, ти протиснувся крізь цю щілину, як експерт.'::text),
(357414,39713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú te colaste por ese hueco como ... experto.'::text,'un'::text,'el'::text,'un'::text,'Sinceramente, tú te colaste por ese hueco como un experto.'::text),
(357413,39713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu t''es faufilé dans cette brèche comme ... expert.'::text,'un'::text,'l'''::text,'un'::text,'Franchement, tu t''es faufilé dans cette brèche comme un expert.'::text),
(357416,39713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen o boşluktan ... uzman gibi sıyrıldın.'::text,'bir'::text,NULL::text,'bir'::text,'Açıkçası, sen o boşluktan bir uzman gibi sıyrıldın.'::text),
(357417,39713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te úgy préselted át magad azon a résen, mint ... profi.'::text,'egy'::text,'a'::text,'egy'::text,'Őszintén, te úgy préselted át magad azon a résen, mint egy profi.'::text),
(376734,41860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte sagte, dass an diesem Tag 12 Männer aus dem Gefängnis entlassen ..., wie der Bericht zeigte.'::text,'würden'::text,'werden'::text,'werden'::text,'Der Beamte sagte, dass an diesem Tag 12 Männer aus dem Gefängnis entlassen würden, wie der Bericht zeigte.'::text),
(376738,41860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер сказав, що того дня з в''язниці ... 12 чоловіків, як показав звіт.'::text,'звільнять'::text,'звільнять'::text,'звільняють'::text,'Офіцер сказав, що того дня з в''язниці звільнять 12 чоловіків, як показав звіт.'::text),
(376737,41860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El funcionario dijo que ese día ... 12 hombres de la prisión, como mostraba el informe.'::text,'serían liberados'::text,'serán liberados'::text,'son liberados'::text,'El funcionario dijo que ese día serían liberados 12 hombres de la prisión, como mostraba el informe.'::text),
(376736,41860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gardien a dit que 12 hommes ... de prison ce jour-là, comme le montrait le rapport.'::text,'seraient libérés'::text,'seront libérés'::text,'sont libérés'::text,'Le gardien a dit que 12 hommes seraient libérés de prison ce jour-là, comme le montrait le rapport.'::text),
(376739,41860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli, raporda görüldüğü gibi o gün cezaevinden 12 adamın ... söyledi.'::text,'serbest bırakılacağını'::text,'serbest bırakılacağını'::text,'serbest bırakıldığını'::text,'Görevli, raporda görüldüğü gibi o gün cezaevinden 12 adamın serbest bırakılacağını söyledi.'::text),
(376740,41860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt azt mondta, hogy aznap 12 férfit ... a börtönből, ahogy a jelentés is mutatta.'::text,'engednek szabadon'::text,'fognak szabadon engedni'::text,'engednek szabadon'::text,'A tiszt azt mondta, hogy aznap 12 férfit engednek szabadon a börtönből, ahogy a jelentés is mutatta.'::text),
(376779,41865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass er zehn Jahre im Gefängnis ..., bevor sie ihn rausgelassen haben.'::text,'gewesen war'::text,'gewesen ist'::text,'war'::text,'Hör mal, ich hab gehört, dass er zehn Jahre im Gefängnis gewesen war, bevor sie ihn rausgelassen haben.'::text),
(376783,41865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що він ... у в''язниці десять років, перш ніж його відпустили.'::text,'був'::text,'є'::text,'був'::text,'Слухай, я чула, що він був у в''язниці десять років, перш ніж його відпустили.'::text),
(376782,41865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, yo he oído que él ... en la cárcel diez años antes de que lo soltaran.'::text,'había estado'::text,'ha estado'::text,'estaba siendo'::text,'Oye, yo he oído que él había estado en la cárcel diez años antes de que lo soltaran.'::text),
(376781,41865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''il ... en prison pendant dix ans avant qu''on le laisse sortir.'::text,'avait été'::text,'a été'::text,'était'::text,'Écoute, j''ai entendu dire qu''il avait été en prison pendant dix ans avant qu''on le laisse sortir.'::text),
(376784,41865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben duydum ki o, bırakılmadan önce on yıl hapiste ...'::text,'kalmıştı'::text,'kalıyor'::text,'kalıyordu'::text,'Dinle, ben duydum ki o, bırakılmadan önce on yıl hapiste kalmıştı.'::text),
(376785,41865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én úgy hallottam, hogy ő tíz évig ... börtönben, mielőtt kiengedték.'::text,'volt'::text,'van'::text,'volt'::text,'Figyelj, én úgy hallottam, hogy ő tíz évig volt börtönben, mielőtt kiengedték.'::text),
(333732,37082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fahnen ... über der Tribüne, seit der Gesang begonnen hat.'::text,'wehen'::text,'wehten'::text,'wehen'::text,'Die Fahnen wehen über der Tribüne, seit der Gesang begonnen hat.'::text),
(333736,37082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Банери ... над трибуною, відколи почався спів.'::text,'майорять'::text,'майоріли'::text,'майорять'::text,'Банери майорять над трибуною, відколи почався спів.'::text),
(333735,37082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las pancartas ... sobre la grada desde que empezó el canto.'::text,'han estado ondeando'::text,'ondearon'::text,'están ondeando'::text,'Las pancartas han estado ondeando sobre la grada desde que empezó el canto.'::text),
(333734,37082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les banderoles ... au-dessus de la tribune depuis que les chants ont commencé.'::text,'flottent'::text,'ont flotté'::text,'flottent'::text,'Les banderoles flottent au-dessus de la tribune depuis que les chants ont commencé.'::text),
(333737,37082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şarkı başladığından beri pankartlar tribünün üzerinde ...'::text,'dalgalanıyor'::text,'dalgalandı'::text,'dalgalanıyor'::text,'Şarkı başladığından beri pankartlar tribünün üzerinde dalgalanıyor.'::text),
(333738,37082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A molinók azóta ... a lelátó felett, hogy elkezdődött az éneklés.'::text,'lobognak'::text,'lobogtak'::text,'lobognak'::text,'A molinók azóta lobognak a lelátó felett, hogy elkezdődött az éneklés.'::text),
(394320,43814,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Fans ihr Vereinslied ..., gingen die Flutlichter an.'::text,'sangen'::text,'sangen'::text,'gesungen haben'::text,'Während die Fans ihr Vereinslied sangen, gingen die Flutlichter an.'::text),
(394324,43814,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вболівальники ... свій клубний гімн, увімкнулися прожектори.'::text,'співали'::text,'заспівали'::text,'заспівали'::text,'Поки вболівальники співали свій клубний гімн, увімкнулися прожектори.'::text),
(394323,43814,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras los aficionados ... su himno del club, se encendieron los focos.'::text,'cantaban'::text,'cantaron'::text,'han cantado'::text,'Mientras los aficionados cantaban su himno del club, se encendieron los focos.'::text),
(394322,43814,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que les supporters ... leur chant du club, les projecteurs se sont allumés.'::text,'chantaient'::text,'ont chanté'::text,'ont chanté'::text,'Pendant que les supporters chantaient leur chant du club, les projecteurs se sont allumés.'::text),
(394325,43814,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taraftarlar kulüp marşını ..., projektörler yandı.'::text,'söylerken'::text,'söyleyince'::text,'söylemişken'::text,'Taraftarlar kulüp marşını söylerken, projektörler yandı.'::text),
(394326,43814,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a szurkolók a klubdalukat ..., felgyulladtak a reflektorok.'::text,'énekelték'::text,'elénekelték'::text,'elénekelték'::text,'Miközben a szurkolók a klubdalukat énekelték, felgyulladtak a reflektorok.'::text),
(330447,36717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn vor einem Spiel die Hymne ..., legen die Spielerinnen die Hände auf die Brust.'::text,'läuft'::text,'lief'::text,'laufen wird'::text,'Wenn vor einem Spiel die Hymne läuft, legen die Spielerinnen die Hände auf die Brust.'::text),
(330451,36717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли перед матчем ... гімн, гравчині кладуть руки на груди.'::text,'лунає'::text,'лунав'::text,'лунатиме'::text,'Коли перед матчем лунає гімн, гравчині кладуть руки на груди.'::text),
(330450,36717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando ... el himno antes de un partido, las jugadoras se ponen la mano en el pecho.'::text,'suena'::text,'sonó'::text,'sonará'::text,'Cuando suena el himno antes de un partido, las jugadoras se ponen la mano en el pecho.'::text),
(330449,36717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''hymne ... avant un match, les joueuses posent la main sur leur poitrine.'::text,'retentit'::text,'a retenti'::text,'retentira'::text,'Quand l''hymne retentit avant un match, les joueuses posent la main sur leur poitrine.'::text),
(330452,36717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maçtan önce marş ..., oyuncular ellerini göğüslerine koyar.'::text,'çalınca'::text,'çaldığında'::text,'çalacağı zaman'::text,'Maçtan önce marş çalınca, oyuncular ellerini göğüslerine koyar.'::text),
(330453,36717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor meccs előtt ... a himnusz, a játékosok a mellkasukra teszik a kezüket.'::text,'szól'::text,'szólt'::text,'szólni fog'::text,'Amikor meccs előtt szól a himnusz, a játékosok a mellkasukra teszik a kezüket.'::text),
(350184,38910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... vor großen Spielen so emotional, aber heute Abend weint sie.'::text,'war früher nicht'::text,'wäre nicht'::text,'war es nicht gewohnt, zu sein'::text,'Sie war früher nicht vor großen Spielen so emotional, aber heute Abend weint sie.'::text),
(350188,38910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... такою емоційною перед великими матчами, але сьогодні ввечері плаче.'::text,'раніше не була'::text,'не була б'::text,'не звикла бути'::text,'Вона раніше не була такою емоційною перед великими матчами, але сьогодні ввечері плаче.'::text),
(350187,38910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... ser tan emotiva antes de los grandes partidos, pero esta noche llora.'::text,'no solía'::text,'no iba a'::text,'no estaba acostumbrada a'::text,'Ella no solía ser tan emotiva antes de los grandes partidos, pero esta noche llora.'::text),
(350186,38910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... aussi émotive avant les grands matchs, mais ce soir, elle pleure.'::text,'n''était pas autrefois'::text,'ne serait pas'::text,'n''était pas habituée à être'::text,'Elle n''était pas autrefois aussi émotive avant les grands matchs, mais ce soir, elle pleure.'::text),
(350189,38910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, büyük maçlardan önce bu kadar duygusal ..., ama bu gece ağlıyor.'::text,'olmazdı'::text,'olmazdı'::text,'olmaya alışkın değildi'::text,'O, büyük maçlardan önce bu kadar duygusal olmazdı, ama bu gece ağlıyor.'::text),
(350190,38910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... ilyen érzelmes a nagy meccsek előtt, de ma este sír.'::text,'régen nem volt'::text,'nem lenne'::text,'nem volt hozzászokva, hogy'::text,'Ő régen nem volt ilyen érzelmes a nagy meccsek előtt, de ma este sír.'::text),
(350229,38915,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, bis zum Schlusspfiff wirst du jeden emotionalen Fan in diesem Stadion ...'::text,'erobert haben'::text,'erobern'::text,'am Erobern sein'::text,'Ganz ehrlich, bis zum Schlusspfiff wirst du jeden emotionalen Fan in diesem Stadion erobert haben.'::text),
(350233,38915,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, до фінального свистка ти ... кожного емоційного фаната на цьому стадіоні.'::text,'завоюєш'::text,'завоюєш'::text,'завойовуватимеш'::text,'Не буду брехати, до фінального свистка ти завоюєш кожного емоційного фаната на цьому стадіоні.'::text),
(350232,38915,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, para el pitido final tú ... a todos los aficionados emotivos de este estadio.'::text,'habrás conquistado'::text,'conquistarás'::text,'estarás conquistando'::text,'No voy a mentir, para el pitido final tú habrás conquistado a todos los aficionados emotivos de este estadio.'::text),
(350231,38915,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, d''ici le coup de sifflet final, tu ... chaque supporter ému de ce stade.'::text,'auras conquis'::text,'conquerras'::text,'seras en train de conquérir'::text,'Je vais pas mentir, d''ici le coup de sifflet final, tu auras conquis chaque supporter ému de ce stade.'::text),
(350234,38915,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, maç sonu düdüğüne kadar sen bu stattaki her duygusal taraftarın gönlünü ...'::text,'kazanmış olacaksın'::text,'kazanacaksın'::text,'kazanıyor olacaksın'::text,'Yalan yok, maç sonu düdüğüne kadar sen bu stattaki her duygusal taraftarın gönlünü kazanmış olacaksın.'::text),
(350235,38915,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, a lefújásig te ... ennek a stadionnak minden érzelmes szurkolóját.'::text,'meghódítod'::text,'meg fogod hódítani'::text,'hódítani fogod'::text,'Nem hazudok, a lefújásig te meghódítod ennek a stadionnak minden érzelmes szurkolóját.'::text),
(366555,40729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... gerade mit lauter Stimme, als der Himmel violett wurde.'::text,'rief'::text,'rief'::text,'hat gerufen'::text,'Der Mann rief gerade mit lauter Stimme, als der Himmel violett wurde.'::text),
(366559,40729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... гучним голосом, коли небо стало фіолетовим.'::text,'кликав'::text,'покликав'::text,'покликав'::text,'Чоловік кликав гучним голосом, коли небо стало фіолетовим.'::text),
(366558,40729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... en voz alta cuando el cielo se volvió violeta.'::text,'estaba llamando'::text,'llamó'::text,'ha llamado'::text,'El hombre estaba llamando en voz alta cuando el cielo se volvió violeta.'::text),
(366557,40729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... d''une voix forte quand le ciel est devenu violet.'::text,'appelait'::text,'a appelé'::text,'a appelé'::text,'L''homme appelait d''une voix forte quand le ciel est devenu violet.'::text),
(366560,40729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökyüzü mora döndüğünde adam yüksek sesle ...'::text,'sesleniyordu'::text,'seslendi'::text,'seslendi'::text,'Gökyüzü mora döndüğünde adam yüksek sesle sesleniyordu.'::text),
(366561,40729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi éppen hangosan ..., amikor az ég lilára változott.'::text,'kiabált'::text,'kiáltott'::text,'kiáltott'::text,'A férfi éppen hangosan kiabált, amikor az ég lilára változott.'::text),
(377355,41929,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann in der gelben Jacke ... das Mikrofon und zerstörte die Stille im Pub!'::text,'nahm'::text,'wurde genommen'::text,'nehmend'::text,'Der Mann in der gelben Jacke nahm das Mikrofon und zerstörte die Stille im Pub!'::text),
(377359,41929,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у жовтій куртці ... мікрофон і зруйнував тишу в пабі!'::text,'взяв'::text,'був узятий'::text,'беручи'::text,'Чоловік у жовтій куртці взяв мікрофон і зруйнував тишу в пабі!'::text),
(377358,41929,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El hombre de la chaqueta amarilla ... el micrófono y destrozó el silencio del pub!'::text,'cogió'::text,'fue cogido'::text,'cogiendo'::text,'¡El hombre de la chaqueta amarilla cogió el micrófono y destrozó el silencio del pub!'::text),
(377357,41929,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme à la veste jaune ... le micro et a détruit le silence du pub !'::text,'a pris'::text,'a été pris'::text,'prenant'::text,'L''homme à la veste jaune a pris le micro et a détruit le silence du pub !'::text),
(377360,41929,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı ceketli adam mikrofonu ... ve pubın sessizliğini yerle bir etti!'::text,'aldı'::text,'alındı'::text,'alarak'::text,'Sarı ceketli adam mikrofonu aldı ve pubın sessizliğini yerle bir etti!'::text),
(377361,41929,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sárga kabátos férfi ... a mikrofont, és szétrombolta a kocsma csendjét!'::text,'elvette'::text,'elvették'::text,'elvéve'::text,'A sárga kabátos férfi elvette a mikrofont, és szétrombolta a kocsma csendjét!'::text),
(330834,36760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann wusste, dass der Applaus lang ..., wie es typischerweise nach einer starken Darbietung vorkommt.'::text,'sein würde'::text,'sein wird'::text,'ist'::text,'Der Mann wusste, dass der Applaus lang sein würde, wie es typischerweise nach einer starken Darbietung vorkommt.'::text),
(330838,36760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік знав, що оплески ... довгими, як це типово буває після сильного виступу.'::text,'будуть'::text,'будуть'::text,'є'::text,'Чоловік знав, що оплески будуть довгими, як це типово буває після сильного виступу.'::text),
(330837,36760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre sabía que el aplauso ... largo, como ocurre típicamente tras una actuación potente.'::text,'sería'::text,'será'::text,'es'::text,'El hombre sabía que el aplauso sería largo, como ocurre típicamente tras una actuación potente.'::text),
(330836,36760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme savait que les applaudissements ... longs, comme c''est typiquement le cas après une performance forte.'::text,'seraient'::text,'seront'::text,'sont'::text,'L''homme savait que les applaudissements seraient longs, comme c''est typiquement le cas après une performance forte.'::text),
(330839,36760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, güçlü bir performanstan sonra tipik olarak olduğu gibi alkışın uzun ... biliyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Adam, güçlü bir performanstan sonra tipik olarak olduğu gibi alkışın uzun olacağını biliyordu.'::text),
(330840,36760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi tudta, hogy a taps hosszú ..., ahogy az egy erős előadás után jellemzően lenni szokott.'::text,'lesz'::text,'lesz'::text,NULL::text,'A férfi tudta, hogy a taps hosszú lesz, ahogy az egy erős előadás után jellemzően lenni szokott.'::text),
(335163,37241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Cremestreifen ... von der Visagistin in die Haut eingearbeitet, und ein gleichmäßiger Teint wurde beobachtet.'::text,'wurden'::text,'arbeiteten'::text,'wurden gerade'::text,'Die Cremestreifen wurden von der Visagistin in die Haut eingearbeitet, und ein gleichmäßiger Teint wurde beobachtet.'::text),
(335167,37241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Смуги крему ... візажисткою в шкіру, і було зафіксовано рівний тон.'::text,'були розтушовані'::text,'розтушували'::text,'розтушовувалися'::text,'Смуги крему були розтушовані візажисткою в шкіру, і було зафіксовано рівний тон.'::text),
(335166,37241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las franjas de crema ... en la piel por la maquilladora, y se observó un tono uniforme.'::text,'fueron difuminadas'::text,'difuminaron'::text,'estaban difuminando'::text,'Las franjas de crema fueron difuminadas en la piel por la maquilladora, y se observó un tono uniforme.'::text),
(335165,37241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les bandes de crème ... dans la peau par la maquilleuse, et un teint uniforme a été observé.'::text,'ont été estompées'::text,'ont estompé'::text,'estompaient'::text,'Les bandes de crème ont été estompées dans la peau par la maquilleuse, et un teint uniforme a été observé.'::text),
(335168,37241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krem şeritleri makyöz tarafından cilde ... ve eşit bir ton gözlemlendi.'::text,'yedirildi'::text,'yedirdi'::text,'yediriyordu'::text,'Krem şeritleri makyöz tarafından cilde yedirildi ve eşit bir ton gözlemlendi.'::text),
(335169,37241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A krémcsíkokat a sminkes ... a bőrbe, és egyenletes tónust figyeltek meg.'::text,'bedolgozta'::text,'bedolgozták'::text,'éppen bedolgozta'::text,'A krémcsíkokat a sminkes bedolgozta a bőrbe, és egyenletes tónust figyeltek meg.'::text),
(335190,37244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende dieser Sitzung hat die Visagistin den letzten Streifen ..., sonst ist es eine Katastrophe!'::text,'eingearbeitet'::text,'einarbeiten'::text,'arbeitet ein'::text,'Bis zum Ende dieser Sitzung hat die Visagistin den letzten Streifen eingearbeitet, sonst ist es eine Katastrophe!'::text),
(335194,37244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця цього сеансу візажистка ... останню смугу, інакше це катастрофа!'::text,'розтушує'::text,'розтушує'::text,'розтушовує'::text,'До кінця цього сеансу візажистка розтушує останню смугу, інакше це катастрофа!'::text),
(335193,37244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el final de esta sesión la maquilladora ... la última franja, o es un desastre!'::text,'habrá difuminado'::text,'difuminará'::text,'difumina'::text,'¡Para el final de esta sesión la maquilladora habrá difuminado la última franja, o es un desastre!'::text),
(335192,37244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la séance, la maquilleuse ... la dernière bande, sinon c''est la catastrophe !'::text,'aura estompé'::text,'estompera'::text,'estompe'::text,'D''ici la fin de la séance, la maquilleuse aura estompé la dernière bande, sinon c''est la catastrophe !'::text),
(335195,37244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu seansın sonuna kadar makyöz son şeridi ..., yoksa felaket!'::text,'yedirmiş olacak'::text,'yedirecek'::text,'yedirir'::text,'Bu seansın sonuna kadar makyöz son şeridi yedirmiş olacak, yoksa felaket!'::text),
(335196,37244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek az ülésnek a végére a sminkes ... az utolsó csíkot is, különben katasztrófa!'::text,'bedolgozza'::text,'be fogja dolgozni'::text,'dolgozza be'::text,'Ennek az ülésnek a végére a sminkes bedolgozza az utolsó csíkot is, különben katasztrófa!'::text),
(369597,41067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... es gewohnt, mit winzigen Modellen zu arbeiten, also machen ihr kleine Türme keine Angst.'::text,'ist'::text,'war früher'::text,'würde'::text,'Sie ist es gewohnt, mit winzigen Modellen zu arbeiten, also machen ihr kleine Türme keine Angst.'::text),
(369601,41067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... працювати з крихітними макетами, тож маленькі вежі її не лякають.'::text,'звикла'::text,'колись'::text,'б'::text,'Вона звикла працювати з крихітними макетами, тож маленькі вежі її не лякають.'::text),
(369600,41067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... trabajar con maquetas diminutas, así que las torres pequeñas no la asustan.'::text,'está acostumbrada a'::text,'solía'::text,'querría'::text,'Ella está acostumbrada a trabajar con maquetas diminutas, así que las torres pequeñas no la asustan.'::text),
(369599,41067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... de travailler avec de minuscules maquettes, donc les petites tours ne lui font pas peur.'::text,'a l''habitude'::text,'avait l''habitude'::text,'voudrait'::text,'Elle a l''habitude de travailler avec de minuscules maquettes, donc les petites tours ne lui font pas peur.'::text),
(369602,41067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, minicik maketlerle çalışmaya ..., bu yüzden küçük kuleler onu korkutmuyor.'::text,'alışkın'::text,'alışkındı'::text,'alışırdı'::text,'O, minicik maketlerle çalışmaya alışkın, bu yüzden küçük kuleler onu korkutmuyor.'::text),
(369603,41067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... apró makettekkel dolgozni, így a kis tornyok nem ijesztik meg.'::text,'hozzászokott'::text,'régen szokott'::text,'szokna'::text,'Ő hozzászokott apró makettekkel dolgozni, így a kis tornyok nem ijesztik meg.'::text),
(369633,41071,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buchstäblich monatelang ... sie an dem Modell gearbeitet, bevor ein echter Turm gebaut wurde!'::text,'hatte'::text,'hat'::text,'war'::text,'Buchstäblich monatelang hatte sie an dem Modell gearbeitet, bevor ein echter Turm gebaut wurde!'::text),
(369637,41071,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Буквально місяцями вона ... над макетом, перш ніж збудували справжню вежу!'::text,'працювала'::text,'працює'::text,'працювала'::text,'Буквально місяцями вона працювала над макетом, перш ніж збудували справжню вежу!'::text),
(369636,41071,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Literalmente durante meses ella ... en la maqueta antes de que se construyera una torre de verdad!'::text,'había estado trabajando'::text,'ha estado trabajando'::text,'estaba trabajando'::text,'¡Literalmente durante meses ella había estado trabajando en la maqueta antes de que se construyera una torre de verdad!'::text),
(369635,41071,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Littéralement pendant des mois, elle ... sur la maquette avant qu''une vraie tour soit construite !'::text,'avait travaillé'::text,'a travaillé'::text,'travaillait'::text,'Littéralement pendant des mois, elle avait travaillé sur la maquette avant qu''une vraie tour soit construite !'::text),
(369638,41071,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen aylarca o, gerçek bir kule inşa edilmeden önce maket üzerinde ...!'::text,'çalışmıştı'::text,'çalışıyor'::text,'çalışıyordu'::text,'Resmen aylarca o, gerçek bir kule inşa edilmeden önce maket üzerinde çalışmıştı!'::text),
(369639,41071,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szó szerint hónapokig ő ... a maketten, mielőtt felépült egy igazi torony!'::text,'dolgozott'::text,'dolgozik'::text,'dolgozott'::text,'Szó szerint hónapokig ő dolgozott a maketten, mielőtt felépült egy igazi torony!'::text),
(400422,44492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, der Gletscher war riesig; er ... sich dort so winzig gefühlt haben.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Mädel, er hat mir erzählt, der Gletscher war riesig; er muss sich dort so winzig gefühlt haben.'::text),
(400426,44492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що льодовик був величезний; він ... почуватися там таким крихітним.'::text,'мусив'::text,'мав'::text,'не міг'::text,'Подруго, він сказав мені, що льодовик був величезний; він мусив почуватися там таким крихітним.'::text),
(400425,44492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él me dijo que el glaciar era inmenso; ... sentido tan pequeño allí de pie.'::text,'debió de haberse'::text,'debería haberse'::text,'no puede haberse'::text,'Tía, él me dijo que el glaciar era inmenso; debió de haberse sentido tan pequeño allí de pie.'::text),
(400424,44492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que le glacier était immense ; il ... se sentir tout petit là-bas.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Meuf, il m''a dit que le glacier était immense ; il a dû se sentir tout petit là-bas.'::text),
(400427,44492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana buzulun devasa olduğunu söyledi; orada dururken kendini çok küçük ...'::text,'hissetmiş olmalı'::text,'hissetmeliydi'::text,'hissetmiş olamaz'::text,'Kızım, o bana buzulun devasa olduğunu söyledi; orada dururken kendini çok küçük hissetmiş olmalı.'::text),
(400428,44492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta nekem, hogy a gleccser hatalmas volt; ott állva ... magát nagyon kicsinek.'::text,'biztosan érezte'::text,'kellett volna éreznie'::text,'nem érezhette'::text,'Csajszi, ő azt mondta nekem, hogy a gleccser hatalmas volt; ott állva biztosan érezte magát nagyon kicsinek.'::text),
(338889,37655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Pferd sich aufbäumte, ... das Vieh schon über die Ebene gezogen.'::text,'war'::text,'ist'::text,'zieht'::text,'Als das Pferd sich aufbäumte, war das Vieh schon über die Ebene gezogen.'::text),
(338893,37655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки кінь став дибки, худоба вже ... рівниною.'::text,'перейшла'::text,'перейшла'::text,'переходить'::text,'Поки кінь став дибки, худоба вже перейшла рівниною.'::text),
(338892,37655,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el caballo se encabritó, el ganado ya ... por la llanura.'::text,'se había desplazado'::text,'se ha desplazado'::text,'se desplaza'::text,'Para cuando el caballo se encabritó, el ganado ya se había desplazado por la llanura.'::text),
(338891,37655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où le cheval s''est cabré, le bétail ... à travers la plaine.'::text,'s''était déplacé'::text,'s''est déplacé'::text,'se déplace'::text,'Au moment où le cheval s''est cabré, le bétail s''était déplacé à travers la plaine.'::text),
(338894,37655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'At şahlandığında sığırlar ovanın öbür yanına çoktan ...'::text,'geçmişti'::text,'geçti'::text,'geçer'::text,'At şahlandığında sığırlar ovanın öbür yanına çoktan geçmişti.'::text),
(338895,37655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a ló felágaskodott, a marhák már ... a síkságon.'::text,'átvonultak'::text,'átvonultak'::text,'vonulnak át'::text,'Mire a ló felágaskodott, a marhák már átvonultak a síkságon.'::text),
(333804,37090,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat uns gesagt, das Barbecue ... draußen, weil es nicht drinnen war.'::text,'sei'::text,'seien'::text,'sein'::text,'Er hat uns gesagt, das Barbecue sei draußen, weil es nicht drinnen war.'::text),
(333808,37090,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав нам, що барбекю ... надворі, бо воно було не всередині.'::text,'було'::text,'були'::text,'бути'::text,'Він сказав нам, що барбекю було надворі, бо воно було не всередині.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
