from (values
(333807,37090,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él nos dijo que la barbacoa ... fuera porque no estaba dentro.'::text,'estaba'::text,'estaban'::text,'estar'::text,'Él nos dijo que la barbacoa estaba fuera porque no estaba dentro.'::text),
(333806,37090,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il nous a dit que le barbecue ... dehors parce qu''il n''était pas dedans.'::text,'était'::text,'étaient'::text,'être'::text,'Il nous a dit que le barbecue était dehors parce qu''il n''était pas dedans.'::text),
(333809,37090,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bize barbekünün içeride olmadığı için dışarıda ... söyledi.'::text,'olduğunu'::text,'olduklarını'::text,'olmak'::text,'O bize barbekünün içeride olmadığı için dışarıda olduğunu söyledi.'::text),
(333810,37090,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt mondta nekünk, hogy a barbecue kint ..., mert nem bent volt.'::text,'van'::text,'vannak'::text,'lenni'::text,'Ő azt mondta nekünk, hogy a barbecue kint van, mert nem bent volt.'::text),
(333849,37095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... stundenlang Rippchen gegrillt, bevor die Barbecue-Gäste zu jubeln anfingen.'::text,'hattest'::text,'hast'::text,'bist'::text,'Respekt, du hattest stundenlang Rippchen gegrillt, bevor die Barbecue-Gäste zu jubeln anfingen.'::text),
(333853,37095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... реберця годинами, поки гості барбекю не почали радіти.'::text,'смажив'::text,'смажиш'::text,'смажиш'::text,'Респект, ти смажив реберця годинами, поки гості барбекю не почали радіти.'::text),
(333852,37095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, tú ... costillas durante horas antes de que los invitados de la barbacoa empezaran a aclamar.'::text,'habías estado asando'::text,'has estado asando'::text,'estás asando'::text,'Respeto, tú habías estado asando costillas durante horas antes de que los invitados de la barbacoa empezaran a aclamar.'::text),
(333851,37095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu ... des côtes pendant des heures avant que les invités du barbecue se mettent à applaudir.'::text,'avais grillé'::text,'as grillé'::text,'grilles'::text,'Respect, tu avais grillé des côtes pendant des heures avant que les invités du barbecue se mettent à applaudir.'::text),
(333854,37095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı, sen barbekü misafirleri tezahürat yapmaya başlamadan önce saatlerce kaburga ...'::text,'ızgara yapmıştın'::text,'ızgara yapıyorsun'::text,'ızgara yapıyorsun'::text,'Saygı, sen barbekü misafirleri tezahürat yapmaya başlamadan önce saatlerce kaburga ızgara yapmıştın.'::text),
(333855,37095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, te órákig ... a bordákat, mielőtt a barbecue vendégei ujjongani kezdtek.'::text,'grillezted'::text,'grillezed'::text,'grillezed'::text,'Respekt, te órákig grillezted a bordákat, mielőtt a barbecue vendégei ujjongani kezdtek.'::text),
(382899,42545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ein Kissen neben den Teppich auf den Boden ..., und das andere ist noch in der Luft.'::text,'geworfen'::text,'geworfen'::text,'wirft'::text,'Sie hat ein Kissen neben den Teppich auf den Boden geworfen, und das andere ist noch in der Luft.'::text),
(382903,42545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... одну подушку на підлогу біля килима, а друга ще в повітрі.'::text,'кинула'::text,'кидала'::text,'кидає'::text,'Вона кинула одну подушку на підлогу біля килима, а друга ще в повітрі.'::text),
(382902,42545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... un cojín al suelo junto a la alfombra, y el otro sigue en el aire.'::text,'ha tirado'::text,'ha estado tirando'::text,'tira'::text,'Ella ha tirado un cojín al suelo junto a la alfombra, y el otro sigue en el aire.'::text),
(382901,42545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un coussin par terre à côté du tapis, et l''autre est encore en l''air.'::text,'a lancé'::text,'lance depuis'::text,'lance'::text,'Elle a lancé un coussin par terre à côté du tapis, et l''autre est encore en l''air.'::text),
(382904,42545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, bir yastığı halının yanına yere ... ve diğeri hâlâ havada.'::text,'attı'::text,'atıyor'::text,'atar'::text,'O, bir yastığı halının yanına yere attı ve diğeri hâlâ havada.'::text),
(382905,42545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... az egyik párnát a földre a szőnyeg mellé, a másik pedig még a levegőben van.'::text,'ledobta'::text,'dobálta'::text,'dobja'::text,'Ő ledobta az egyik párnát a földre a szőnyeg mellé, a másik pedig még a levegőben van.'::text),
(367806,40868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Soldaten ... seit dem frühen Morgen über den Exerzierplatz.'::text,'marschieren'::text,'marschieren'::text,'marschieren'::text,'Die Soldaten marschieren seit dem frühen Morgen über den Exerzierplatz.'::text),
(367810,40868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Солдати ... плацом з самого ранку.'::text,'марширують'::text,'марширують'::text,'марширують'::text,'Солдати марширують плацом з самого ранку.'::text),
(367809,40868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los soldados ... por el patio de armas desde primera hora de la mañana.'::text,'han estado marchando'::text,'están marchando'::text,'marchan'::text,'Los soldados han estado marchando por el patio de armas desde primera hora de la mañana.'::text),
(367808,40868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les soldats ... sur le terrain de parade depuis tôt ce matin.'::text,'défilent'::text,'défilent'::text,'défilent'::text,'Les soldats défilent sur le terrain de parade depuis tôt ce matin.'::text),
(367811,40868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Askerler sabahın erken saatlerinden beri tören alanında uygun adım ...'::text,'yürüyor'::text,'yürüyor'::text,'yürür'::text,'Askerler sabahın erken saatlerinden beri tören alanında uygun adım yürüyor.'::text),
(367812,40868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A katonák kora reggel óta ... a díszszemle terén.'::text,'masíroznak'::text,'masíroznak'::text,'masíroznak'::text,'A katonák kora reggel óta masíroznak a díszszemle terén.'::text),
(331572,36842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... er gerade eine Tasche mit falschen Edelsteinen, als der Polizist ihn festnahm.'::text,'trug'::text,'trug'::text,'hat getragen'::text,'Mädel, angeblich trug er gerade eine Tasche mit falschen Edelsteinen, als der Polizist ihn festnahm.'::text),
(331576,36842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... сумку фальшивих коштовностей, коли поліцейський його затримав.'::text,'ніс'::text,'поніс'::text,'поніс'::text,'Подруго, кажуть, він ніс сумку фальшивих коштовностей, коли поліцейський його затримав.'::text),
(331575,36842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer él ... una bolsa de joyas falsas cuando el policía lo detuvo.'::text,'llevaba'::text,'llevó'::text,'ha llevado'::text,'Tía, al parecer él llevaba una bolsa de joyas falsas cuando el policía lo detuvo.'::text),
(331574,36842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... un sac de faux bijoux quand le policier l''a arrêté.'::text,'portait'::text,'a porté'::text,'a porté'::text,'Meuf, apparemment il portait un sac de faux bijoux quand le policier l''a arrêté.'::text),
(331577,36842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre polis onu tutukladığında o sahte mücevherlerle dolu bir çanta ...'::text,'taşıyormuş'::text,'taşıdı'::text,'taşıdı'::text,'Kızım, duyduğuma göre polis onu tutukladığında o sahte mücevherlerle dolu bir çanta taşıyormuş.'::text),
(331578,36842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő épp egy zsák hamis drágakövet ..., amikor a rendőr letartóztatta.'::text,'cipelt'::text,'cipelt'::text,'cipelt'::text,'Csajszi, állítólag ő épp egy zsák hamis drágakövet cipelt, amikor a rendőr letartóztatta.'::text),
(331599,36845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Tasche zu gewesen wäre, ... bei der Festnahme keine Beute herausgefallen.'::text,'wäre'::text,'wird'::text,'fiel'::text,'Wenn die Tasche zu gewesen wäre, wäre bei der Festnahme keine Beute herausgefallen.'::text),
(331603,36845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сумка була закрита, під час арешту ... жодна здобич.'::text,'не випала б'::text,'не випаде'::text,'не випала'::text,'Якби сумка була закрита, під час арешту не випала б жодна здобич.'::text),
(331602,36845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la bolsa hubiera estado cerrada, no ... nada del botín durante la detención.'::text,'se habría caído'::text,'se caerá'::text,'se cayó'::text,'Si la bolsa hubiera estado cerrada, no se habría caído nada del botín durante la detención.'::text),
(331601,36845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le sac avait été fermé, aucun butin ne ... pendant l''arrestation.'::text,'serait tombé'::text,'tombera'::text,'est tombé'::text,'Si le sac avait été fermé, aucun butin ne serait tombé pendant l''arrestation.'::text),
(331604,36845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çanta kapalı olsaydı, tutuklama sırasında hiç ganimet dışarı ...'::text,'düşmezdi'::text,'düşmeyecek'::text,'düşmedi'::text,'Çanta kapalı olsaydı, tutuklama sırasında hiç ganimet dışarı düşmezdi.'::text),
(331605,36845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a táska zárva lett volna, a letartóztatás közben semmi zsákmány nem ... ki.'::text,'esett volna'::text,'fog esni'::text,'esett'::text,'Ha a táska zárva lett volna, a letartóztatás közben semmi zsákmány nem esett volna ki.'::text),
(374979,41665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ihres schweren Koffers raste sie den Bahnsteig entlang. Absolut unaufhaltsam!'::text,'Trotz'::text,'Obwohl'::text,'Im Falle'::text,'Trotz ihres schweren Koffers raste sie den Bahnsteig entlang. Absolut unaufhaltsam!'::text),
(374983,41665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... свою важку валізу, вона помчала пероном. Абсолютно нестримна!'::text,'Попри'::text,'Хоча'::text,'У разі'::text,'Попри свою важку валізу, вона помчала пероном. Абсолютно нестримна!'::text),
(374982,41665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su pesada maleta, ella corrió por el andén. ¡Absolutamente imparable!'::text,'A pesar de'::text,'Aunque'::text,'En caso de'::text,'A pesar de su pesada maleta, ella corrió por el andén. ¡Absolutamente imparable!'::text),
(374981,41665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sa lourde valise, elle a foncé sur le quai. Absolument inarrêtable !'::text,'Malgré'::text,'Bien que'::text,'En cas de'::text,'Malgré sa lourde valise, elle a foncé sur le quai. Absolument inarrêtable !'::text),
(374984,41665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağır bavuluna ..., o perondan aşağı koştu. Kesinlikle durdurulamaz!'::text,'rağmen'::text,'karşın'::text,'halinde'::text,'Ağır bavuluna rağmen, o perondan aşağı koştu. Kesinlikle durdurulamaz!'::text),
(374985,41665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nehéz bőröndje ..., ő végigszáguldott a peronon. Abszolút megállíthatatlan!'::text,'ellenére'::text,'bár'::text,'esetén'::text,'A nehéz bőröndje ellenére, ő végigszáguldott a peronon. Abszolút megállíthatatlan!'::text),
(393510,43724,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Licht schwand, ... sie in ihrem Atelier drei Leinwände bemalt.'::text,'hatte'::text,'hat'::text,'malt'::text,'Als das Licht schwand, hatte sie in ihrem Atelier drei Leinwände bemalt.'::text),
(393514,43724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки світло згасло, вона ... у своїй студії три полотна.'::text,'намалювала'::text,'намалювала'::text,'малює'::text,'Поки світло згасло, вона намалювала у своїй студії три полотна.'::text),
(393513,43724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se fue la luz, ella ... tres lienzos en su estudio.'::text,'había pintado'::text,'ha pintado'::text,'pinta'::text,'Para cuando se fue la luz, ella había pintado tres lienzos en su estudio.'::text),
(393512,43724,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où la lumière a baissé, elle ... trois toiles dans son atelier.'::text,'avait peint'::text,'a peint'::text,'peint'::text,'Au moment où la lumière a baissé, elle avait peint trois toiles dans son atelier.'::text),
(393515,43724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işık solduğunda o, atölyesinde üç tuval ...'::text,'boyamıştı'::text,'boyadı'::text,'boyar'::text,'Işık solduğunda o, atölyesinde üç tuval boyamıştı.'::text),
(393516,43724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elhalványult a fény, ő ... három vásznat a műtermében.'::text,'megfestett'::text,'megfestett'::text,'fest'::text,'Mire elhalványult a fény, ő megfestett három vásznat a műtermében.'::text),
(362451,40273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie beeindruckt: Du ... echt gut mit Anleitungen sein; der Schrank stand so schnell.'::text,'musst'::text,'kannst nicht'::text,'solltest nicht'::text,'Irgendwie beeindruckt: Du musst echt gut mit Anleitungen sein; der Schrank stand so schnell.'::text),
(362455,40273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи вражена: ти ... бути неймовірним з інструкціями; шафа постала так швидко.'::text,'мусиш'::text,'не можеш'::text,'не повинен'::text,'Трохи вражена: ти мусиш бути неймовірним з інструкціями; шафа постала так швидко.'::text),
(362454,40273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un poco impresionada: tú ... de ser genial con las instrucciones; el armario quedó montado rapidísimo.'::text,'debes'::text,'no puedes'::text,'no deberías'::text,'Un poco impresionada: tú debes de ser genial con las instrucciones; el armario quedó montado rapidísimo.'::text),
(362453,40273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt impressionnée : tu ... être génial avec les notices ; l''armoire a été montée tellement vite.'::text,'dois'::text,'ne peux pas'::text,'ne devrais pas'::text,'Plutôt impressionnée : tu dois être génial avec les notices ; l''armoire a été montée tellement vite.'::text),
(362456,40273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz etkilendim: sen talimatlar konusunda harika ...; dolap o kadar hızlı kuruldu ki.'::text,'olmalısın'::text,'olamazsın'::text,'olmamalısın'::text,'Biraz etkilendim: sen talimatlar konusunda harika olmalısın; dolap o kadar hızlı kuruldu ki.'::text),
(362457,40273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit le vagyok nyűgözve: te ... az útmutatókkal; a szekrény olyan gyorsan összeállt.'::text,'biztos zseniális vagy'::text,'nem lehetsz zseniális'::text,'nem kéne zseniálisnak lenned'::text,'Kicsit le vagyok nyűgözve: te biztos zseniális vagy az útmutatókkal; a szekrény olyan gyorsan összeállt.'::text),
(362478,40276,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... sie jeden Schritt der Anleitung befolgt.'::text,'haben'::text,'werden'::text,'befolgen'::text,'Bis heute Abend haben sie jeden Schritt der Anleitung befolgt.'::text),
(362482,40276,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До сьогоднішнього вечора вони ... кожного кроку в інструкції.'::text,'дотримаються'::text,'дотримаються'::text,'дотримуються'::text,'До сьогоднішнього вечора вони дотримаються кожного кроку в інструкції.'::text),
(362481,40276,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ellos ... cada paso de las instrucciones.'::text,'habrán seguido'::text,'seguirán'::text,'siguen'::text,'Para esta noche, ellos habrán seguido cada paso de las instrucciones.'::text),
(362480,40276,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, ils ... chaque étape de la notice.'::text,'auront suivi'::text,'suivront'::text,'suivent'::text,'D''ici ce soir, ils auront suivi chaque étape de la notice.'::text),
(362483,40276,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar onlar talimatlardaki her adımı ...'::text,'uygulamış olacaklar'::text,'uygulayacaklar'::text,'uyguluyorlar'::text,'Bu akşama kadar onlar talimatlardaki her adımı uygulamış olacaklar.'::text),
(362484,40276,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma estére ők az útmutató minden lépését ...'::text,'végigkövetik'::text,'követni fogják'::text,'követik'::text,'Ma estére ők az útmutató minden lépését végigkövetik.'::text),
(340149,37795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, dass die Möwe, ... seine Pommes geklaut hat, mit Freunden zurück ist.'::text,'die'::text,'deren'::text,'wo'::text,'Bestie, er hat mir erzählt, dass die Möwe, die seine Pommes geklaut hat, mit Freunden zurück ist.'::text),
(340153,37795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, він сказав мені, що чайка, ... вкрала його картоплю фрі, повернулася з друзями.'::text,'яка'::text,'чия'::text,'де'::text,'Бесті, він сказав мені, що чайка, яка вкрала його картоплю фрі, повернулася з друзями.'::text),
(340152,37795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, él me dijo que la gaviota ... le robó las patatas fritas ha vuelto con amigas.'::text,'que'::text,'cuya'::text,'donde'::text,'Bestie, él me dijo que la gaviota que le robó las patatas fritas ha vuelto con amigas.'::text),
(340151,37795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, il m''a dit que la mouette ... a volé ses frites est revenue avec ses potes.'::text,'qui'::text,'dont'::text,'où'::text,'Bestie, il m''a dit que la mouette qui a volé ses frites est revenue avec ses potes.'::text),
(340154,37795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o bana ... patateslerini çalan martının arkadaşlarıyla geri döndüğünü söyledi.'::text,''::text,NULL::text,NULL::text,'Kanka, o bana patateslerini çalan martının arkadaşlarıyla geri döndüğünü söyledi.'::text),
(340155,37795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ő azt mondta nekem, hogy a sirály, ... ellopta a sült krumpliját, visszajött a barátaival.'::text,'amelyik'::text,'akinek a'::text,'ahol'::text,'Bestie, ő azt mondta nekem, hogy a sirály, amelyik ellopta a sült krumpliját, visszajött a barátaival.'::text),
(340167,37797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du isst Pommes ... wie ein echter Einheimischer.'::text,'am Meer'::text,'an einem Meer'::text,'an Meer'::text,'Ehrlich, du isst Pommes am Meer wie ein echter Einheimischer.'::text),
(340171,37797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти їси картоплю фрі біля ..., як справжній місцевий.'::text,'моря'::text,'моря'::text,'моря'::text,'Чесно, ти їси картоплю фрі біля моря, як справжній місцевий.'::text),
(340170,37797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú comes patatas fritas junto ... como un auténtico local.'::text,'al mar'::text,'a un mar'::text,'a mar'::text,'Sinceramente, tú comes patatas fritas junto al mar como un auténtico local.'::text),
(340169,37797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu manges des frites au bord de ... comme un vrai local.'::text,'la mer'::text,'une mer'::text,'mer'::text,'Franchement, tu manges des frites au bord de la mer comme un vrai local.'::text),
(340172,37797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen gerçek bir yerli gibi ... kenarında patates kızartması yiyorsun.'::text,'deniz'::text,'bir deniz'::text,'deniz'::text,'Açıkçası, sen gerçek bir yerli gibi deniz kenarında patates kızartması yiyorsun.'::text),
(340173,37797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te úgy eszed a sült krumplit ... mellett, mint egy igazi helyi.'::text,'a tenger'::text,'egy tenger'::text,'tenger'::text,'Őszintén, te úgy eszed a sült krumplit a tenger mellett, mint egy igazi helyi.'::text),
(354504,39390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... vor den Möwen geflohen, weil er vor ihnen weggerannt sei.'::text,'sei'::text,'ist'::text,'flieht'::text,'Er sagte, er sei vor den Möwen geflohen, weil er vor ihnen weggerannt sei.'::text),
(354508,39390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що ... від чайок, бо тікав від них.'::text,'утік'::text,'утік'::text,'тікає'::text,'Він сказав, що утік від чайок, бо тікав від них.'::text),
(354507,39390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él dijo que ... de las gaviotas porque estaba huyendo de ellas.'::text,'había huido'::text,'ha huido'::text,'huye'::text,'Él dijo que había huido de las gaviotas porque estaba huyendo de ellas.'::text),
(354506,39390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... les mouettes parce qu''il était en train de leur échapper.'::text,'avait fui'::text,'a fui'::text,'fuit'::text,'Il a dit qu''il avait fui les mouettes parce qu''il était en train de leur échapper.'::text),
(354509,39390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, onlardan kaçtığı için martılardan ... söyledi.'::text,'kaçmış olduğunu'::text,'kaçtığını'::text,'kaçtığını'::text,'O, onlardan kaçtığı için martılardan kaçmış olduğunu söyledi.'::text),
(354510,39390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt mondta, hogy ... a sirályok elől, mert menekült előlük.'::text,'elmenekült'::text,'elmenekült'::text,'menekül'::text,'Ő azt mondta, hogy elmenekült a sirályok elől, mert menekült előlük.'::text),
(354567,39397,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seine Pommes eine Minute lang gegessen, bevor er fliehen musste. Makelloses Mittagessen, natürlich.'::text,'hatte'::text,'hat'::text,'isst'::text,'Er hatte seine Pommes eine Minute lang gegessen, bevor er fliehen musste. Makelloses Mittagessen, natürlich.'::text),
(354571,39397,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... свою картоплю фрі хвилину, перш ніж мусив тікати. Бездоганний обід, звісно.'::text,'їв'::text,'їсть'::text,'їсть'::text,'Він їв свою картоплю фрі хвилину, перш ніж мусив тікати. Бездоганний обід, звісно.'::text),
(354570,39397,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... sus patatas fritas durante un minuto antes de tener que huir. Un almuerzo impecable, obviamente.'::text,'había estado comiendo'::text,'ha estado comiendo'::text,'come'::text,'Él había estado comiendo sus patatas fritas durante un minuto antes de tener que huir. Un almuerzo impecable, obviamente.'::text),
(354569,39397,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... ses frites pendant une minute avant de devoir fuir. Déjeuner impeccable, évidemment.'::text,'avait mangé'::text,'a mangé'::text,'mange'::text,'Il avait mangé ses frites pendant une minute avant de devoir fuir. Déjeuner impeccable, évidemment.'::text),
(354572,39397,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kaçmak zorunda kalmadan önce bir dakika boyunca patateslerini ...; kusursuz bir öğle yemeği, tabii ki.'::text,'yemişti'::text,'yiyor'::text,'yer'::text,'O, kaçmak zorunda kalmadan önce bir dakika boyunca patateslerini yemişti; kusursuz bir öğle yemeği, tabii ki.'::text),
(354573,39397,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy percig ... a sült krumpliját, mielőtt menekülnie kellett. Hibátlan ebéd, nyilvánvalóan.'::text,'ette'::text,'eszi'::text,'eszi'::text,'Ő egy percig ette a sült krumpliját, mielőtt menekülnie kellett. Hibátlan ebéd, nyilvánvalóan.'::text),
(364287,40477,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Lachen ... das Spielzimmer jetzt schon seit zehn Minuten, und es hört nicht auf.'::text,'erfüllt'::text,'hat erfüllt'::text,'erfüllt'::text,'Ihr Lachen erfüllt das Spielzimmer jetzt schon seit zehn Minuten, und es hört nicht auf.'::text),
(364291,40477,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхній сміх ... ігрову кімнату вже десять хвилин, і досі не стихає.'::text,'наповнює'::text,'наповнив'::text,'наповнює'::text,'Їхній сміх наповнює ігрову кімнату вже десять хвилин, і досі не стихає.'::text),
(364290,40477,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su risa ... la sala de juegos desde hace diez minutos, y sigue sin parar.'::text,'llena'::text,'ha llenado'::text,'está llenando'::text,'Su risa llena la sala de juegos desde hace diez minutos, y sigue sin parar.'::text),
(364289,40477,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leur rire ... la salle de jeux depuis dix minutes maintenant, et ça continue.'::text,'remplit'::text,'a rempli'::text,'remplit'::text,'Leur rire remplit la salle de jeux depuis dix minutes maintenant, et ça continue.'::text),
(364292,40477,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahkahaları on dakikadır oyun odasını ... ve hâlâ devam ediyor.'::text,'dolduruyor'::text,'doldurdu'::text,'dolduruyor'::text,'Kahkahaları on dakikadır oyun odasını dolduruyor ve hâlâ devam ediyor.'::text),
(364293,40477,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nevetésük már tíz perce ... a játszószobát, és még mindig tart.'::text,'betölti'::text,'betöltötte'::text,'betölti'::text,'A nevetésük már tíz perce betölti a játszószobát, és még mindig tart.'::text),
(329322,36592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die beiden Frauen ihre Zuneigung mit einer weiteren großen Umarmung.'::text,'zeigen'::text,'zeigen'::text,'zeigen'::text,'Morgen um diese Zeit zeigen die beiden Frauen ihre Zuneigung mit einer weiteren großen Umarmung.'::text),
(329326,36592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час ці дві жінки ... свою прихильність ще одними великими обіймами.'::text,'проявлятимуть'::text,'проявлять'::text,'проявляють'::text,'Завтра в цей час ці дві жінки проявлятимуть свою прихильність ще одними великими обіймами.'::text),
(329325,36592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, las dos mujeres ... su cariño con otro gran abrazo.'::text,'estarán mostrando'::text,'mostrarán'::text,'muestran'::text,'Mañana a esta hora, las dos mujeres estarán mostrando su cariño con otro gran abrazo.'::text),
(329324,36592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, les deux femmes ... leur affection par un autre gros câlin.'::text,'seront en train de montrer'::text,'montreront'::text,'montrent'::text,'Demain à la même heure, les deux femmes seront en train de montrer leur affection par un autre gros câlin.'::text),
(329327,36592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte iki kadın büyük bir sarılmayla daha sevgilerini ...'::text,'gösteriyor olacak'::text,'gösterecek'::text,'gösteriyor'::text,'Yarın bu saatte iki kadın büyük bir sarılmayla daha sevgilerini gösteriyor olacak.'::text),
(329328,36592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a két nő egy újabb nagy öleléssel ... a szeretetét.'::text,'fogja kimutatni'::text,'mutatja ki'::text,'mutatja ki'::text,'Holnap ilyenkor a két nő egy újabb nagy öleléssel fogja kimutatni a szeretetét.'::text),
(360768,40086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Mann sich umsah, ... die Kängurus schon an ihm vorbeigehüpft.'::text,'waren'::text,'sind'::text,'hüpfen'::text,'Als der Mann sich umsah, waren die Kängurus schon an ihm vorbeigehüpft.'::text),
(360772,40086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки чоловік озирнувся, кенгуру вже ... повз нього.'::text,'пострибали'::text,'пострибали'::text,'стрибають'::text,'Поки чоловік озирнувся, кенгуру вже пострибали повз нього.'::text),
(360771,40086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el hombre miró atrás, los canguros ya ... junto a él.'::text,'habían pasado saltando'::text,'han pasado saltando'::text,'pasan saltando'::text,'Para cuando el hombre miró atrás, los canguros ya habían pasado saltando junto a él.'::text),
(360770,40086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où l''homme s''est retourné, les kangourous ... devant lui en sautant.'::text,'étaient passés'::text,'sont passés'::text,'passent'::text,'Au moment où l''homme s''est retourné, les kangourous étaient passés devant lui en sautant.'::text),
(360773,40086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam arkasına baktığında kangurular çoktan yanından zıplayarak ...'::text,'geçmişti'::text,'geçti'::text,'geçer'::text,'Adam arkasına baktığında kangurular çoktan yanından zıplayarak geçmişti.'::text),
(360774,40086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a férfi hátranézett, a kenguruk már ... mellette.'::text,'elugráltak'::text,'elugráltak'::text,'ugrálnak el'::text,'Mire a férfi hátranézett, a kenguruk már elugráltak mellette.'::text),
(352533,39171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Boot ... seit Jahren 300 Touristen am Tag über den Hafen, bei voller Auslastung.'::text,'befördert'::text,'befördert gerade'::text,'befördert'::text,'Dieses Boot befördert seit Jahren 300 Touristen am Tag über den Hafen, bei voller Auslastung.'::text),
(352537,39171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей човен ... 300 туристів на день через гавань уже роками, на повну потужність.'::text,'перевозить'::text,'перевозить'::text,'перевозить'::text,'Цей човен перевозить 300 туристів на день через гавань уже роками, на повну потужність.'::text),
(352536,39171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este barco ... 300 turistas al día por el puerto desde hace años, a plena capacidad.'::text,'ha estado transportando'::text,'está transportando'::text,'transporta'::text,'Este barco ha estado transportando 300 turistas al día por el puerto desde hace años, a plena capacidad.'::text),
(352535,39171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce bateau ... 300 touristes par jour à travers le port depuis des années, à pleine capacité.'::text,'transporte'::text,'est en train de transporter'::text,'transporte'::text,'Ce bateau transporte 300 touristes par jour à travers le port depuis des années, à pleine capacité.'::text),
(352538,39171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu tekne yıllardır limanın bir yakasından diğerine günde 300 turist ..., tam kapasiteyle.'::text,'taşıyor'::text,'taşıyor'::text,'taşır'::text,'Bu tekne yıllardır limanın bir yakasından diğerine günde 300 turist taşıyor, tam kapasiteyle.'::text),
(352539,39171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a hajó évek óta napi 300 turistát ... át a kikötőn, teljes kapacitással.'::text,'visz'::text,'visz'::text,'visz'::text,'Ez a hajó évek óta napi 300 turistát visz át a kikötőn, teljes kapacitással.'::text),
(352605,39179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Sommer ... die kleinen Boote Touristen über den Hafen.'::text,'befördern'::text,'befördern gerade'::text,'haben befördert'::text,'Jeden Sommer befördern die kleinen Boote Touristen über den Hafen.'::text),
(352609,39179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоліта маленькі човни ... туристів через гавань.'::text,'перевозять'::text,'перевозять'::text,'перевезли'::text,'Щоліта маленькі човни перевозять туристів через гавань.'::text),
(352608,39179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada verano, las barquitas ... turistas por el puerto.'::text,'transportan'::text,'están transportando'::text,'han transportado'::text,'Cada verano, las barquitas transportan turistas por el puerto.'::text),
(352607,39179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque été, les petits bateaux ... des touristes à travers le port.'::text,'transportent'::text,'sont en train de transporter'::text,'ont transporté'::text,'Chaque été, les petits bateaux transportent des touristes à travers le port.'::text),
(352610,39179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yaz küçük tekneler turistleri limanın karşısına ...'::text,'taşır'::text,'taşıyor'::text,'taşıdı'::text,'Her yaz küçük tekneler turistleri limanın karşısına taşır.'::text),
(352611,39179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nyáron a kis hajók ... át a turistákat a kikötőn.'::text,'viszik'::text,'viszik'::text,'vitték'::text,'Minden nyáron a kis hajók viszik át a turistákat a kikötőn.'::text),
(331923,36881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Trainer glaubt, dass sie nächsten Monat den sportlichen Surfwettbewerb ...'::text,'gewinnt'::text,'gewinnen wird'::text,'gerade gewinnt'::text,'Ihr Trainer glaubt, dass sie nächsten Monat den sportlichen Surfwettbewerb gewinnt.'::text),
(331927,36881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її тренер думає, що вона ... спортивні змагання з серфінгу наступного місяця.'::text,'виграє'::text,'виграватиме'::text,'виграє'::text,'Її тренер думає, що вона виграє спортивні змагання з серфінгу наступного місяця.'::text),
(331926,36881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su entrenador cree que ella ... el concurso atlético de surf el mes que viene.'::text,'ganará'::text,'estará ganando'::text,'está ganando'::text,'Su entrenador cree que ella ganará el concurso atlético de surf el mes que viene.'::text),
(331925,36881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son coach pense qu''elle ... la compétition sportive de surf le mois prochain.'::text,'gagnera'::text,'sera en train de gagner'::text,'est en train de gagner'::text,'Son coach pense qu''elle gagnera la compétition sportive de surf le mois prochain.'::text),
(331928,36881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koçu, onun gelecek ay atletik sörf yarışmasını ... düşünüyor.'::text,'kazanacağını'::text,'kazanıyor olacağını'::text,'kazandığını'::text,'Koçu, onun gelecek ay atletik sörf yarışmasını kazanacağını düşünüyor.'::text),
(331929,36881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edzője szerint ő ... a sportos szörfversenyt jövő hónapban.'::text,'megnyeri'::text,'nyerni fogja'::text,'épp nyeri'::text,'Az edzője szerint ő megnyeri a sportos szörfversenyt jövő hónapban.'::text),
(367689,40855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sie sich gerade aufs Marmorgeländer, als das Quartett zu spielen anfing.'::text,'lehnte'::text,'lehnte'::text,'hat gelehnt'::text,'Mädel, angeblich lehnte sie sich gerade aufs Marmorgeländer, als das Quartett zu spielen anfing.'::text),
(367693,40855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... на мармурові поруччя, коли квартет почав грати.'::text,'спиралася'::text,'сперлася'::text,'сперлася'::text,'Подруго, кажуть, вона спиралася на мармурові поруччя, коли квартет почав грати.'::text),
(367692,40855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ella ... en la barandilla de mármol cuando el cuarteto empezó a tocar.'::text,'estaba apoyada'::text,'se apoyó'::text,'se ha apoyado'::text,'Tía, al parecer ella estaba apoyada en la barandilla de mármol cuando el cuarteto empezó a tocar.'::text),
(367691,40855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... sur la rambarde en marbre quand le quatuor a commencé à jouer.'::text,'s''appuyait'::text,'s''est appuyée'::text,'s''est appuyée'::text,'Meuf, apparemment elle s''appuyait sur la rambarde en marbre quand le quatuor a commencé à jouer.'::text),
(367694,40855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre dörtlü çalmaya başladığında o mermer korkuluğa ...'::text,'yaslanıyormuş'::text,'yaslandı'::text,'yaslandı'::text,'Kızım, duyduğuma göre dörtlü çalmaya başladığında o mermer korkuluğa yaslanıyormuş.'::text),
(367695,40855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő épp ... a márványkorlátnak, amikor a vonósnégyes játszani kezdett.'::text,'támaszkodott'::text,'nekitámaszkodott'::text,'nekitámaszkodott'::text,'Csajszi, állítólag ő épp támaszkodott a márványkorlátnak, amikor a vonósnégyes játszani kezdett.'::text),
(367725,40859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Marmor nicht anfassen sollen; auf dem Schild stand: Berühren verboten. Makellose Manieren, eindeutig.'::text,'hätte'::text,'durfte'::text,'konnte'::text,'Sie hätte den Marmor nicht anfassen sollen; auf dem Schild stand: Berühren verboten. Makellose Manieren, eindeutig.'::text),
(367729,40859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... торкатися мармуру; на табличці було написано «не торкатися». Бездоганні манери, явно.'::text,'не мала б'::text,'не мусила'::text,'не могла'::text,'Вона не мала б торкатися мармуру; на табличці було написано «не торкатися». Бездоганні манери, явно.'::text),
(367728,40859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... tocado el mármol; el cartel decía que no se tocara. Modales impecables, claramente.'::text,'no debería haber'::text,'no tenía que haber'::text,'no podía haber'::text,'Ella no debería haber tocado el mármol; el cartel decía que no se tocara. Modales impecables, claramente.'::text),
(367727,40859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... toucher le marbre ; le panneau disait de ne pas toucher. Des manières impeccables, clairement.'::text,'n''aurait pas dû'::text,'ne devait pas'::text,'ne pouvait pas'::text,'Elle n''aurait pas dû toucher le marbre ; le panneau disait de ne pas toucher. Des manières impeccables, clairement.'::text),
(367730,40859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O mermere ...; tabelada dokunmak yasak yazıyordu. Kusursuz görgü, belli ki.'::text,'dokunmamalıydı'::text,'dokunmamış olmalı'::text,'dokunamadı'::text,'O mermere dokunmamalıydı; tabelada dokunmak yasak yazıyordu. Kusursuz görgü, belli ki.'::text),
(367731,40859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... hozzáérnie a márványhoz; a táblán az állt, hogy tilos megérinteni. Hibátlan modor, egyértelműen.'::text,'nem kellett volna'::text,'nem kellett'::text,'nem tudott'::text,'Ő nem kellett volna hozzáérnie a márványhoz; a táblán az állt, hogy tilos megérinteni. Hibátlan modor, egyértelműen.'::text),
(329295,36589,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Baby so ..., findet jeder es entzückend.'::text,'lächelt'::text,'lächelte'::text,'lächeln wird'::text,'Wenn ein Baby so lächelt, findet jeder es entzückend.'::text),
(329299,36589,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли немовля ... ось так, усі вважають, що воно чарівне.'::text,'усміхається'::text,'усміхнулося'::text,'усміхнеться'::text,'Коли немовля усміхається ось так, усі вважають, що воно чарівне.'::text),
(329298,36589,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando un bebé ... así, todo el mundo piensa que es adorable.'::text,'sonríe'::text,'sonrió'::text,'sonreirá'::text,'Cuando un bebé sonríe así, todo el mundo piensa que es adorable.'::text),
(329297,36589,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand un bébé ... comme ça, tout le monde le trouve adorable.'::text,'sourit'::text,'a souri'::text,'sourira'::text,'Quand un bébé sourit comme ça, tout le monde le trouve adorable.'::text),
(329300,36589,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir bebek böyle ..., herkes onun çok tatlı olduğunu düşünür.'::text,'gülümsediğinde'::text,'gülümsediğinde'::text,'gülümseyeceği zaman'::text,'Bir bebek böyle gülümsediğinde, herkes onun çok tatlı olduğunu düşünür.'::text),
(329301,36589,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor egy baba így ..., mindenki imádnivalónak tartja.'::text,'mosolyog'::text,'mosolygott'::text,'mosolyogni fog'::text,'Amikor egy baba így mosolyog, mindenki imádnivalónak tartja.'::text),
(389271,43253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein schmerzender Rücken ... durch das Tragen eines schweren Rucksacks den Berg hinauf verursacht.'::text,'wurde'::text,'verursachte'::text,'verursacht gerade'::text,'Sein schmerzender Rücken wurde durch das Tragen eines schweren Rucksacks den Berg hinauf verursacht.'::text),
(389275,43253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його хвора спина ... носінням важкого рюкзака на пагорб.'::text,'була спричинена'::text,'спричинила'::text,'спричиняє'::text,'Його хвора спина була спричинена носінням важкого рюкзака на пагорб.'::text),
(389274,43253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su espalda dolorida ... por cargar una mochila pesada colina arriba.'::text,'fue causada'::text,'causó'::text,'está causando'::text,'Su espalda dolorida fue causada por cargar una mochila pesada colina arriba.'::text),
(389273,43253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son mal de dos ... par le port d''un sac à dos lourd en haut de la colline.'::text,'a été causé'::text,'a causé'::text,'est en train de causer'::text,'Son mal de dos a été causé par le port d''un sac à dos lourd en haut de la colline.'::text),
(389276,43253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun ağrıyan sırtı, ağır bir sırt çantasını tepeye taşımaktan ...'::text,'kaynaklandı'::text,'neden oldu'::text,'neden oluyor'::text,'Onun ağrıyan sırtı, ağır bir sırt çantasını tepeye taşımaktan kaynaklandı.'::text),
(389277,43253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fájó hátát ... a nehéz hátizsák felcipelése a dombra.'::text,'okozta'::text,'okozta'::text,'okozza'::text,'A fájó hátát okozta a nehéz hátizsák felcipelése a dombra.'::text),
(389325,43259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, sein Rücken ... weh, seit die Wanderung angefangen hat, der Typ ist echt durch.'::text,'tut'::text,'tut'::text,'tut gerade'::text,'Nee, sein Rücken tut weh, seit die Wanderung angefangen hat, der Typ ist echt durch.'::text),
(389329,43259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, його спина ... з початку походу, чувак геть виснажений.'::text,'болить'::text,'болить'::text,'болить'::text,'Не, його спина болить з початку походу, чувак геть виснажений.'::text),
(389328,43259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, la espalda le ... desde que empezó la ruta, el tío está hecho polvo.'::text,'duele'::text,'duele'::text,'está doliendo'::text,'Qué va, la espalda le duele desde que empezó la ruta, el tío está hecho polvo.'::text),
(389327,43259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, son dos lui ... mal depuis le début de la rando, le mec est complètement cuit.'::text,'fait'::text,'fait'::text,'est en train de faire'::text,'Nan, son dos lui fait mal depuis le début de la rando, le mec est complètement cuit.'::text),
(389330,43259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok ya, yürüyüş başladığından beri sırtı ..., adam resmen bitmiş.'::text,'ağrıyor'::text,'ağrıyor'::text,'ağrıyor'::text,'Yok ya, yürüyüş başladığından beri sırtı ağrıyor, adam resmen bitmiş.'::text),
(389331,43259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, a háta a túra kezdete óta ..., a srác eléggé ki van készülve.'::text,'fáj'::text,'fáj'::text,'fáj'::text,'Nem, a háta a túra kezdete óta fáj, a srác eléggé ki van készülve.'::text),
(338160,37574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es anfängt zu regnen, ... ihr Rucksack aus Segeltuch ihre Sachen trocken.'::text,'hält'::text,'würde halten'::text,'hielt'::text,'Wenn es anfängt zu regnen, hält ihr Rucksack aus Segeltuch ihre Sachen trocken.'::text),
(338164,37574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо почнеться дощ, її брезентовий рюкзак ... її речі сухими.'::text,'збереже'::text,'зберіг би'::text,'зберіг'::text,'Якщо почнеться дощ, її брезентовий рюкзак збереже її речі сухими.'::text),
(338163,37574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si empieza a llover, su mochila de lona ... sus cosas secas.'::text,'mantendrá'::text,'mantendría'::text,'mantuvo'::text,'Si empieza a llover, su mochila de lona mantendrá sus cosas secas.'::text),
(338162,37574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il commence à pleuvoir, son sac à dos en toile ... ses affaires au sec.'::text,'gardera'::text,'garderait'::text,'a gardé'::text,'S''il commence à pleuvoir, son sac à dos en toile gardera ses affaires au sec.'::text),
(338165,37574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur başlarsa, onun kanvas sırt çantası eşyalarını kuru ...'::text,'tutacak'::text,'tutardı'::text,'tuttu'::text,'Yağmur başlarsa, onun kanvas sırt çantası eşyalarını kuru tutacak.'::text),
(338166,37574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elered az eső, a vászon hátizsákja szárazon ... a holmiját.'::text,'tartja'::text,'tartaná'::text,'tartotta'::text,'Ha elered az eső, a vászon hátizsákja szárazon tartja a holmiját.'::text),
(377715,41969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine schlichte Stofftasche, aber jetzt hat sie eine Lederhandtasche.'::text,'trug früher'::text,'würde tragen'::text,'ist es gewohnt, zu tragen'::text,'Sie trug früher eine schlichte Stofftasche, aber jetzt hat sie eine Lederhandtasche.'::text),
(377719,41969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... носити просту тканинну сумку, але тепер у неї шкіряна сумочка.'::text,'мала звичку'::text,'б'::text,'звикла'::text,'Вона мала звичку носити просту тканинну сумку, але тепер у неї шкіряна сумочка.'::text),
(377718,41969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... llevar un tote sencillo, pero ahora tiene un bolso de cuero.'::text,'solía'::text,'querría'::text,'está acostumbrada a'::text,'Ella solía llevar un tote sencillo, pero ahora tiene un bolso de cuero.'::text),
(377717,41969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... porter un simple tote bag, mais maintenant elle a un sac à main en cuir.'::text,'avait l''habitude de'::text,'voudrait'::text,'est habituée à'::text,'Elle avait l''habitude de porter un simple tote bag, mais maintenant elle a un sac à main en cuir.'::text),
(377720,41969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O eskiden sade bir bez çanta ..., ama şimdi deri bir çantası var.'::text,'taşırdı'::text,'taşırdı'::text,'taşımaya alışkın'::text,'O eskiden sade bir bez çanta taşırdı, ama şimdi deri bir çantası var.'::text),
(377721,41969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő régen egy egyszerű vászontáskát ..., de most bőr kézitáskája van.'::text,'hordott'::text,'hordana'::text,'szokott hordani'::text,'Ő régen egy egyszerű vászontáskát hordott, de most bőr kézitáskája van.'::text),
(377733,41971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Moment ... sie auf der Rolltreppe eine braune Lederhandtasche hoch.'::text,'hält'::text,'hält'::text,'hat gehalten'::text,'Im Moment hält sie auf der Rolltreppe eine braune Lederhandtasche hoch.'::text),
(377737,41971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз вона ... на ескалаторі коричневу шкіряну сумочку вгору.'::text,'тримає'::text,'тримає'::text,'тримала'::text,'Зараз вона тримає на ескалаторі коричневу шкіряну сумочку вгору.'::text),
(377736,41971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, ella ... un bolso de cuero marrón en alto en la escalera mecánica.'::text,'está sosteniendo'::text,'sostiene'::text,'ha sostenido'::text,'En este momento, ella está sosteniendo un bolso de cuero marrón en alto en la escalera mecánica.'::text),
(377735,41971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... un sac à main en cuir marron en l''air sur l''escalator.'::text,'tient'::text,'tient'::text,'a tenu'::text,'En ce moment, elle tient un sac à main en cuir marron en l''air sur l''escalator.'::text),
(377738,41971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o yürüyen merdivende kahverengi deri bir çantayı yukarıda ...'::text,'tutuyor'::text,'tutar'::text,'tuttu'::text,'Şu anda o yürüyen merdivende kahverengi deri bir çantayı yukarıda tutuyor.'::text),
(377739,41971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ő a mozgólépcsőn egy barna bőr kézitáskát ... a magasba.'::text,'tart'::text,'tart'::text,'tartott'::text,'Épp most ő a mozgólépcsőn egy barna bőr kézitáskát tart a magasba.'::text),
(386418,42936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat den ganzen Tag eingekauft, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Sie hat den ganzen Tag eingekauft, oder?'::text),
(386422,42936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона цілий день ходила по магазинах, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Вона цілий день ходила по магазинах, правда?'::text),
(386421,42936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella estuvo de compras todo el día, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Ella estuvo de compras todo el día, ¿verdad?'::text),
(386420,42936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait du shopping toute la journée, ... ?'::text,'non'::text,'non'::text,'non'::text,'Elle a fait du shopping toute la journée, non ?'::text),
(386423,42936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bütün gün alışveriş yaptı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'O bütün gün alışveriş yaptı, değil mi?'::text),
(386424,42936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egész nap vásárolt, ...?'::text,'nem'::text,'nem'::text,'nem'::text,'Ő egész nap vásárolt, nem?'::text),
(386445,42939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... seit zehn Uhr morgens und ist immer noch nicht fertig.'::text,'shoppt'::text,'shoppt gerade'::text,'shoppt'::text,'Bro, sie shoppt seit zehn Uhr morgens und ist immer noch nicht fertig.'::text),
(386449,42939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... з десятої ранку і досі не закінчила.'::text,'ходить по магазинах'::text,'ходить по магазинах'::text,'ходить по магазинах'::text,'Бро, вона ходить по магазинах з десятої ранку і досі не закінчила.'::text),
(386448,42939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... desde las diez de la mañana y todavía no ha acabado.'::text,'lleva comprando'::text,'está comprando'::text,'compra'::text,'Bro, ella lleva comprando desde las diez de la mañana y todavía no ha acabado.'::text),
(386447,42939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... depuis dix heures ce matin et elle a toujours pas fini.'::text,'fait du shopping'::text,'est en train de faire du shopping'::text,'fait du shopping'::text,'Frérot, elle fait du shopping depuis dix heures ce matin et elle a toujours pas fini.'::text),
(386450,42939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o sabah ondan beri ... ve hâlâ bitirmedi.'::text,'alışveriş yapıyor'::text,'alışveriş yapıyor'::text,'alışveriş yapar'::text,'Kanka, o sabah ondan beri alışveriş yapıyor ve hâlâ bitirmedi.'::text),
(386451,42939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő reggel tíz óta ..., és még mindig nem végzett.'::text,'vásárol'::text,'vásárol'::text,'vásárol'::text,'Tesó, ő reggel tíz óta vásárol, és még mindig nem végzett.'::text),
(330591,36733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein roter Rucksack ist endlich aufgetaucht, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Sein roter Rucksack ist endlich aufgetaucht, oder?'::text),
(330595,36733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його червоний рюкзак нарешті з''явився, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Його червоний рюкзак нарешті з''явився, правда?'::text),
(330594,36733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su mochila roja por fin ha aparecido, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Su mochila roja por fin ha aparecido, ¿verdad?'::text),
(330593,36733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son sac à dos rouge est enfin apparu, ... ?'::text,'non'::text,'non'::text,'non'::text,'Son sac à dos rouge est enfin apparu, non ?'::text),
(330596,36733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun kırmızı sırt çantası sonunda göründü, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Onun kırmızı sırt çantası sonunda göründü, değil mi?'::text),
(330597,36733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Végre megjelent a piros hátizsákja, ...?'::text,'nem'::text,'nem'::text,'nem'::text,'Végre megjelent a piros hátizsákja, nem?'::text),
(348843,38761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du den Teig nicht so ordentlich geformt hättest, ... diese Croissants nicht so gut geworden.'::text,'wären'::text,'werden'::text,'wurden'::text,'Ehrlich, wenn du den Teig nicht so ordentlich geformt hättest, wären diese Croissants nicht so gut geworden.'::text),
(348847,38761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти не сформувала тісто так акуратно, ці круасани ... такими смачними.'::text,'не вийшли б'::text,'не вийдуть'::text,'не вийшли'::text,'Чесно, якби ти не сформувала тісто так акуратно, ці круасани не вийшли б такими смачними.'::text),
(348846,38761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si tú no hubieras formado la masa con tanto cuidado, estos cruasanes no ... tan buenos.'::text,'habrían salido'::text,'saldrán'::text,'salieron'::text,'Sinceramente, si tú no hubieras formado la masa con tanto cuidado, estos cruasanes no habrían salido tan buenos.'::text),
(348845,38761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu n''avais pas façonné la pâte aussi soigneusement, ces croissants ... aussi bons.'::text,'n''auraient pas été'::text,'ne seront pas'::text,'n''étaient pas'::text,'Franchement, si tu n''avais pas façonné la pâte aussi soigneusement, ces croissants n''auraient pas été aussi bons.'::text),
(348848,38761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen hamuru bu kadar düzgün şekillendirmeseydin, bu kruvasanlar bu kadar güzel ...'::text,'olmazdı'::text,'olmayacak'::text,'olmadı'::text,'Açıkçası, sen hamuru bu kadar düzgün şekillendirmeseydin, bu kruvasanlar bu kadar güzel olmazdı.'::text),
(348849,38761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha te nem formáztad volna ilyen szépen a tésztát, ezek a croissant-ok nem ... ilyen jók.'::text,'lettek volna'::text,'lesznek'::text,'lettek'::text,'Őszintén, ha te nem formáztad volna ilyen szépen a tésztát, ezek a croissant-ok nem lettek volna ilyen jók.'::text),
(365691,40633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Lichterkette ..., leuchtet die Terrasse warm.'::text,'anmacht'::text,'anmachte'::text,'anmachen wird'::text,'Wenn sie die Lichterkette anmacht, leuchtet die Terrasse warm.'::text),
(365695,40633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона ... гірлянду, тераса тепло світиться.'::text,'вмикає'::text,'увімкнула'::text,'увімкне'::text,'Якщо вона вмикає гірлянду, тераса тепло світиться.'::text),
(365694,40633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella ... las guirnaldas de luces, la terraza brilla con calidez.'::text,'enciende'::text,'encendió'::text,'encenderá'::text,'Si ella enciende las guirnaldas de luces, la terraza brilla con calidez.'::text),
(365693,40633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ... la guirlande lumineuse, la terrasse brille d''une lumière chaude.'::text,'allume'::text,'a allumé'::text,'allumera'::text,'Si elle allume la guirlande lumineuse, la terrasse brille d''une lumière chaude.'::text),
(365696,40633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ışık zincirini ..., teras sıcacık parlar.'::text,'yakarsa'::text,'yaktı'::text,'yakacak'::text,'O ışık zincirini yakarsa, teras sıcacık parlar.'::text),
(365697,40633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő ... a fényfüzért, a terasz melegen ragyog.'::text,'felkapcsolja'::text,'felkapcsolta'::text,'fel fogja kapcsolni'::text,'Ha ő felkapcsolja a fényfüzért, a terasz melegen ragyog.'::text),
(383160,42574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen Mittag ... der Bankangestellte gerade die Scheine in den Tresor, also ist der Schalter geschlossen.'::text,'legt'::text,'legt'::text,'legt'::text,'Morgen Mittag legt der Bankangestellte gerade die Scheine in den Tresor, also ist der Schalter geschlossen.'::text),
(383164,42574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні касир ... банкноти в сейф, тож віконце буде зачинене.'::text,'складатиме'::text,'складе'::text,'складає'::text,'Завтра опівдні касир складатиме банкноти в сейф, тож віконце буде зачинене.'::text),
(383163,42574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana al mediodía, el empleado ... los billetes en la caja fuerte, así que la ventanilla estará cerrada.'::text,'estará metiendo'::text,'meterá'::text,'mete'::text,'Mañana al mediodía, el empleado estará metiendo los billetes en la caja fuerte, así que la ventanilla estará cerrada.'::text),
(383162,42574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, le guichetier ... les billets dans le coffre, donc le guichet sera fermé.'::text,'sera en train de ranger'::text,'rangera'::text,'range'::text,'Demain à midi, le guichetier sera en train de ranger les billets dans le coffre, donc le guichet sera fermé.'::text),
(383165,42574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen memur banknotları kasaya ..., bu yüzden gişe kapalı olacak.'::text,'koyuyor olacak'::text,'koyacak'::text,'koyar'::text,'Yarın öğlen memur banknotları kasaya koyuyor olacak, bu yüzden gişe kapalı olacak.'::text),
(383166,42574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben a pénztáros ... a bankjegyeket a széfbe, így a pult zárva lesz.'::text,'épp berakja'::text,'be fogja rakni'::text,'berakja'::text,'Holnap délben a pénztáros épp berakja a bankjegyeket a széfbe, így a pult zárva lesz.'::text),
(366069,40675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... als Kind von so einer Bankhalle, ohne Witz.'::text,'träumte früher'::text,'war es gewohnt, zu träumen'::text,'träumt'::text,'Bro, sie träumte früher als Kind von so einer Bankhalle, ohne Witz.'::text),
(366073,40675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у дитинстві вона ... про такий банківський хол, без жартів.'::text,'часто мріяла'::text,'звикла мріяти'::text,'часто мріє'::text,'Бро, у дитинстві вона часто мріяла про такий банківський хол, без жартів.'::text),
(366072,40675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, de niña ella ... soñar con un vestíbulo de banco así, en serio.'::text,'solía'::text,'estaba acostumbrada a'::text,'suele'::text,'Bro, de niña ella solía soñar con un vestíbulo de banco así, en serio.'::text),
(366071,40675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, petite, elle ... rêver d''un hall de banque comme ça, sans mentir.'::text,'avait l''habitude de'::text,'était habituée à'::text,'a l''habitude de'::text,'Frérot, petite, elle avait l''habitude de rêver d''un hall de banque comme ça, sans mentir.'::text),
(366074,40675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o çocukken böyle bir banka lobisinin hayalini ..., yalan yok.'::text,'kurardı'::text,'kurmaya alışkındı'::text,'kurar'::text,'Kanka, o çocukken böyle bir banka lobisinin hayalini kurardı, yalan yok.'::text),
(366075,40675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő gyerekként egy ilyen bankcsarnokról ..., komolyan.'::text,'álmodozott'::text,'hozzá volt szokva, hogy álmodozzon'::text,'szokott álmodozni'::text,'Tesó, ő gyerekként egy ilyen bankcsarnokról álmodozott, komolyan.'::text),
(366105,40679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bankangestellte ... eine Stunde lang Scheine gezählt, bevor sie in die Halle kam.'::text,'hatte'::text,'hat'::text,'war'::text,'Der Bankangestellte hatte eine Stunde lang Scheine gezählt, bevor sie in die Halle kam.'::text),
(366109,40679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Касир ... банкноти годину, перш ніж вона зайшла в хол.'::text,'рахував'::text,'рахує'::text,'рахував'::text,'Касир рахував банкноти годину, перш ніж вона зайшла в хол.'::text),
(366108,40679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El empleado ... billetes durante una hora antes de que ella entrara en el vestíbulo.'::text,'había estado contando'::text,'ha estado contando'::text,'estaba contando'::text,'El empleado había estado contando billetes durante una hora antes de que ella entrara en el vestíbulo.'::text),
(366107,40679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le guichetier ... des billets pendant une heure avant qu''elle entre dans le hall.'::text,'avait compté'::text,'a compté'::text,'comptait'::text,'Le guichetier avait compté des billets pendant une heure avant qu''elle entre dans le hall.'::text),
(366110,40679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur, o lobiye girmeden önce bir saat boyunca banknot ...'::text,'saymıştı'::text,'sayıyor'::text,'sayıyordu'::text,'Memur, o lobiye girmeden önce bir saat boyunca banknot saymıştı.'::text),
(366111,40679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pénztáros egy órán át ... a bankjegyeket, mielőtt ő belépett a csarnokba.'::text,'számolta'::text,'számolja'::text,'számolta'::text,'A pénztáros egy órán át számolta a bankjegyeket, mielőtt ő belépett a csarnokba.'::text),
(382233,42471,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich bin sicher, dass die Rinde rau ..., auch wenn dieser Streifen abgeht.'::text,'bleibt'::text,'bleiben wird'::text,'gerade bleibt'::text,'Ich bin sicher, dass die Rinde rau bleibt, auch wenn dieser Streifen abgeht.'::text),
(382237,42471,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я впевнений, що кора ... шорсткою, навіть коли ця смуга відпаде.'::text,'залишиться'::text,'залишатиметься'::text,'залишається'::text,'Я впевнений, що кора залишиться шорсткою, навіть коли ця смуга відпаде.'::text),
(382236,42471,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo estoy seguro de que la corteza ... áspera incluso después de que se caiga esta tira.'::text,'seguirá'::text,'estará siguiendo'::text,'está siguiendo'::text,'Yo estoy seguro de que la corteza seguirá áspera incluso después de que se caiga esta tira.'::text),
(382235,42471,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je suis sûr que l''écorce ... rugueuse même après que cette bande se sera détachée.'::text,'restera'::text,'sera en train de rester'::text,'reste'::text,'Je suis sûr que l''écorce restera rugueuse même après que cette bande se sera détachée.'::text),
(382238,42471,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ben, bu şerit düştükten sonra bile ağaç kabuğunun pürüzlü ... eminim.'::text,'kalacağından'::text,'kalıyor olacağından'::text,'kaldığından'::text,'Ben, bu şerit düştükten sonra bile ağaç kabuğunun pürüzlü kalacağından eminim.'::text),
(382239,42471,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Én biztos vagyok benne, hogy a kéreg ... érdes, még azután is, hogy ez a csík leválik.'::text,'marad'::text,'maradni fog'::text,'marad éppen'::text,'Én biztos vagyok benne, hogy a kéreg marad érdes, még azután is, hogy ez a csík leválik.'::text),
(334164,37130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat seinen Keller in ein Heimkino ..., und jetzt ist es fertig.'::text,'verwandelt'::text,'verwandelt'::text,'verwandelt gerade'::text,'Er hat seinen Keller in ein Heimkino verwandelt, und jetzt ist es fertig.'::text),
(334168,37130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... свій підвал на домашній кінотеатр, і тепер він готовий.'::text,'перетворив'::text,'перетворював'::text,'перетворює'::text,'Він перетворив свій підвал на домашній кінотеатр, і тепер він готовий.'::text),
(334167,37130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... su sótano en un cine en casa, y ahora está terminado.'::text,'ha convertido'::text,'ha estado convirtiendo'::text,'está convirtiendo'::text,'Él ha convertido su sótano en un cine en casa, y ahora está terminado.'::text),
(334166,37130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... son sous-sol en home cinéma, et maintenant c''est fini.'::text,'a transformé'::text,'transforme depuis'::text,'est en train de transformer'::text,'Il a transformé son sous-sol en home cinéma, et maintenant c''est fini.'::text),
(334169,37130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bodrumunu ev sinemasına ... ve artık bitti.'::text,'dönüştürdü'::text,'dönüştürüyor'::text,'dönüştürüyor'::text,'O bodrumunu ev sinemasına dönüştürdü ve artık bitti.'::text),
(334170,37130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a pincéjét házimozivá, és most már kész.'::text,'átalakította'::text,'alakítgatta'::text,'alakítja át'::text,'Ő átalakította a pincéjét házimozivá, és most már kész.'::text),
(334218,37136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ewig durch den gruseligen Keller gelaufen, bevor die Kinotür aufging!'::text,'waren'::text,'sind'::text,'laufen'::text,'Sie waren ewig durch den gruseligen Keller gelaufen, bevor die Kinotür aufging!'::text),
(334222,37136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... жахливим підвалом цілу вічність, перш ніж відчинилися двері кінотеатру!'::text,'ішли'::text,'ідуть'::text,'ідуть'::text,'Вони ішли жахливим підвалом цілу вічність, перш ніж відчинилися двері кінотеатру!'::text),
(334221,37136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... por el sótano aterrador durante siglos antes de que se abriera la puerta del cine!'::text,'habían estado caminando'::text,'han estado caminando'::text,'caminan'::text,'¡Ellos habían estado caminando por el sótano aterrador durante siglos antes de que se abriera la puerta del cine!'::text),
(334220,37136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... dans le sous-sol terrifiant pendant une éternité avant que la porte du cinéma s''ouvre !'::text,'avaient marché'::text,'ont marché'::text,'marchent'::text,'Ils avaient marché dans le sous-sol terrifiant pendant une éternité avant que la porte du cinéma s''ouvre !'::text),
(334223,37136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar sinemanın kapısı açılmadan önce korkunç bodrumda bir ömür boyu ...!'::text,'yürümüşlerdi'::text,'yürüyorlar'::text,'yürürler'::text,'Onlar sinemanın kapısı açılmadan önce korkunç bodrumda bir ömür boyu yürümüşlerdi!'::text),
(334224,37136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők egy örökkévalóságig ... a félelmetes pincében, mielőtt kinyílt a mozi ajtaja!'::text,'mentek'::text,'mennek'::text,'mennek'::text,'Ők egy örökkévalóságig mentek a félelmetes pincében, mielőtt kinyílt a mozi ajtaja!'::text),
(399000,44334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jemand zu viel Seife in eine Wanne ..., läuft der Schaum über den Rand.'::text,'gießt'::text,'goss'::text,'gießen wird'::text,'Wenn jemand zu viel Seife in eine Wanne gießt, läuft der Schaum über den Rand.'::text),
(399004,44334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хтось ... у ванну забагато мила, піна переливається через край.'::text,'наливає'::text,'налив'::text,'наллє'::text,'Якщо хтось наливає у ванну забагато мила, піна переливається через край.'::text),
(399003,44334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si alguien ... demasiado jabón en una bañera, la espuma se desborda.'::text,'echa'::text,'echó'::text,'echará'::text,'Si alguien echa demasiado jabón en una bañera, la espuma se desborda.'::text),
(399002,44334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si quelqu''un ... trop de savon dans une baignoire, la mousse déborde.'::text,'verse'::text,'a versé'::text,'versera'::text,'Si quelqu''un verse trop de savon dans une baignoire, la mousse déborde.'::text),
(399005,44334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri küvete fazla sabun ..., köpükler kenardan taşar.'::text,'dökerse'::text,'döktü'::text,'dökecek'::text,'Biri küvete fazla sabun dökerse, köpükler kenardan taşar.'::text),
(399006,44334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha valaki túl sok szappant ... egy kádba, a hab kifolyik a peremén.'::text,'önt'::text,'öntött'::text,'önteni fog'::text,'Ha valaki túl sok szappant önt egy kádba, a hab kifolyik a peremén.'::text),
(335829,37315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Matratze härter wäre, ... sie nicht so hoch.'::text,'hüpfte'::text,'wird hüpfen'::text,'hüpft'::text,'Wenn die Matratze härter wäre, hüpfte sie nicht so hoch.'::text),
(335833,37315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби матрац був твердіший, вона ... так високо.'::text,'не підстрибувала б'::text,'не підстрибне'::text,'не підстрибує'::text,'Якби матрац був твердіший, вона не підстрибувала б так високо.'::text),
(335832,37315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el colchón fuera más duro, ella ... tan alto.'::text,'no rebotaría'::text,'no rebotará'::text,'no rebota'::text,'Si el colchón fuera más duro, ella no rebotaría tan alto.'::text),
(335831,37315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le matelas était plus dur, elle ... aussi haut.'::text,'ne rebondirait pas'::text,'ne rebondira pas'::text,'ne rebondit pas'::text,'Si le matelas était plus dur, elle ne rebondirait pas aussi haut.'::text),
(335834,37315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yatak daha sert olsaydı, o bu kadar yükseğe ...'::text,'zıplamazdı'::text,'zıplamayacak'::text,'zıplamıyor'::text,'Yatak daha sert olsaydı, o bu kadar yükseğe zıplamazdı.'::text),
(335835,37315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha keményebb lenne a matrac, ő nem ... ilyen magasra.'::text,'pattanna'::text,'fog pattanni'::text,'pattan'::text,'Ha keményebb lenne a matrac, ő nem pattanna ilyen magasra.'::text),
(345576,38398,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gänseblümchen ... von der Biene eins nach dem anderen besucht.'::text,'werden'::text,'besuchen'::text,'werden gerade'::text,'Die Gänseblümchen werden von der Biene eins nach dem anderen besucht.'::text),
(345580,38398,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ромашки ... бджолою одна за одною.'::text,'відвідуються'::text,'відвідують'::text,'відвідують'::text,'Ромашки відвідуються бджолою одна за одною.'::text),
(345579,38398,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las margaritas ... por la abeja una a una.'::text,'son visitadas'::text,'visitan'::text,'están visitando'::text,'Las margaritas son visitadas por la abeja una a una.'::text),
(345578,38398,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pâquerettes ... par l''abeille une par une.'::text,'sont visitées'::text,'visitent'::text,'visitent'::text,'Les pâquerettes sont visitées par l''abeille une par une.'::text),
(345581,38398,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Papatyalar arı tarafından tek tek ...'::text,'ziyaret ediliyor'::text,'ziyaret ediyor'::text,'ziyaret ediyor'::text,'Papatyalar arı tarafından tek tek ziyaret ediliyor.'::text),
(345582,38398,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A százszorszépeket egyenként ... a méh.'::text,'látogatja meg'::text,'meglátogatják'::text,'látogatják'::text,'A százszorszépeket egyenként látogatja meg a méh.'::text),
(351084,39010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... aufgeregt wegen der ganzen Aufregung.'::text,'sei'::text,'seien'::text,'sein'::text,'Sie sagte, sie sei aufgeregt wegen der ganzen Aufregung.'::text),
(351088,39010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... схвильована через усе це хвилювання.'::text,'була'::text,'були'::text,'бути'::text,'Вона сказала, що була схвильована через усе це хвилювання.'::text),
(351087,39010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella dijo que ... emocionada por toda la emoción.'::text,'estaba'::text,'estaban'::text,'estar'::text,'Ella dijo que estaba emocionada por toda la emoción.'::text),
(351086,39010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... excitée à cause de toute cette excitation.'::text,'était'::text,'étaient'::text,'être'::text,'Elle a dit qu''elle était excitée à cause de toute cette excitation.'::text),
(351089,39010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, bütün o heyecan yüzünden heyecanlı ... söyledi.'::text,'olduğunu'::text,'olduklarını'::text,'olmak'::text,'O, bütün o heyecan yüzünden heyecanlı olduğunu söyledi.'::text),
(351090,39010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt mondta, hogy izgatott ... a sok izgalom miatt.'::text,''::text,NULL::text,'lenni'::text,'Ő azt mondta, hogy izgatott a sok izgalom miatt.'::text),
(351129,39015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie die Arena erreichten, ... ihre Aufregung schon den ganzen Nachmittag gewachsen.'::text,'war'::text,'ist'::text,'wächst'::text,'Bevor sie die Arena erreichten, war ihre Aufregung schon den ganzen Nachmittag gewachsen.'::text),
(351133,39015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони дісталися арени, її хвилювання ... все пообіддя.'::text,'зростало'::text,'зростає'::text,'зростає'::text,'Поки вони дісталися арени, її хвилювання зростало все пообіддя.'::text),
(351132,39015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que llegaran al estadio, su emoción ... toda la tarde.'::text,'había estado creciendo'::text,'ha estado creciendo'::text,'crece'::text,'Antes de que llegaran al estadio, su emoción había estado creciendo toda la tarde.'::text),
(351131,39015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''elles arrivent à l''arène, son excitation ... tout l''après-midi.'::text,'avait grandi'::text,'a grandi'::text,'grandit'::text,'Avant qu''elles arrivent à l''arène, son excitation avait grandi tout l''après-midi.'::text),
(351134,39015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar arenaya varmadan önce, onun heyecanı bütün öğleden sonra ...'::text,'artmıştı'::text,'artıyor'::text,'artar'::text,'Onlar arenaya varmadan önce, onun heyecanı bütün öğleden sonra artmıştı.'::text),
(351135,39015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt odaértek az arénához, az izgalma egész délután ...'::text,'nőtt'::text,'nő'::text,'nő'::text,'Mielőtt odaértek az arénához, az izgalma egész délután nőtt.'::text),
(352002,39112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Sturz des Mannes ... seine Brotzeittüte in die Luft.'::text,'schleuderte'::text,'wurde geschleudert'::text,'schleudernd'::text,'Der Sturz des Mannes schleuderte seine Brotzeittüte in die Luft.'::text),
(352006,39112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Падіння чоловіка ... його пакет з обідом у повітря.'::text,'підкинуло'::text,'було підкинуте'::text,'підкидаючи'::text,'Падіння чоловіка підкинуло його пакет з обідом у повітря.'::text),
(352005,39112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La caída del hombre ... su bolsa del almuerzo por los aires.'::text,'mandó'::text,'fue mandada'::text,'mandando'::text,'La caída del hombre mandó su bolsa del almuerzo por los aires.'::text),
(352004,39112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chute de l''homme ... son sac-repas en l''air.'::text,'a envoyé'::text,'a été envoyée'::text,'envoyant'::text,'La chute de l''homme a envoyé son sac-repas en l''air.'::text),
(352007,39112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamın düşüşü öğle yemeği poşetini havaya ...'::text,'fırlattı'::text,'fırlatıldı'::text,'fırlatarak'::text,'Adamın düşüşü öğle yemeği poşetini havaya fırlattı.'::text),
(352008,39112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi esése a levegőbe ... az ebédes zacskóját.'::text,'repítette'::text,'repítették'::text,'repítve'::text,'A férfi esése a levegőbe repítette az ebédes zacskóját.'::text),
(371604,41290,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass seine Gegnerin diesen Zug das ganze Spiel über ...'::text,'geplant hat'::text,'plant'::text,'planend'::text,'Man glaubt, dass seine Gegnerin diesen Zug das ganze Spiel über geplant hat.'::text),
(371608,41290,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважають, що його суперниця ... цей хід усю гру.'::text,'планувала'::text,'планує'::text,'планування'::text,'Вважають, що його суперниця планувала цей хід усю гру.'::text),
(371607,41290,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que su rival ... esta jugada durante toda la partida.'::text,'ha estado planeando'::text,'planea'::text,'planeando'::text,'Se cree que su rival ha estado planeando esta jugada durante toda la partida.'::text),
(371606,41290,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que son adversaire ... ce coup pendant toute la partie.'::text,'a préparé'::text,'prépare'::text,'préparant'::text,'On pense que son adversaire a préparé ce coup pendant toute la partie.'::text),
(371609,41290,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakibinin bu hamleyi bütün oyun boyunca ... düşünülüyor.'::text,'planlamış olduğu'::text,'planladığı'::text,'planlayarak'::text,'Rakibinin bu hamleyi bütün oyun boyunca planlamış olduğu düşünülüyor.'::text),
(371610,41290,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy az ellenfele az egész játék alatt ... ezt a lépést.'::text,'tervezte'::text,'tervezi'::text,'tervezve'::text,'Úgy tartják, hogy az ellenfele az egész játék alatt tervezte ezt a lépést.'::text),
(386148,42906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er ..., hast du ihn mit einem eleganten Zug geschockt, ehrlich.'::text,'redete'::text,'redete'::text,'geredet hat'::text,'Während er redete, hast du ihn mit einem eleganten Zug geschockt, ehrlich.'::text),
(386152,42906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ..., ти шокувала його одним елегантним ходом, чесно.'::text,'говорив'::text,'поговорив'::text,'поговорив'::text,'Поки він говорив, ти шокувала його одним елегантним ходом, чесно.'::text),
(386151,42906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras él ..., tú lo dejaste en shock con un movimiento elegante, sinceramente.'::text,'hablaba'::text,'habló'::text,'ha hablado'::text,'Mientras él hablaba, tú lo dejaste en shock con un movimiento elegante, sinceramente.'::text),
(386150,42906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ..., tu l''as choqué avec un coup élégant, franchement.'::text,'parlait'::text,'a parlé'::text,'a parlé'::text,'Pendant qu''il parlait, tu l''as choqué avec un coup élégant, franchement.'::text),
(386153,42906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ..., sen onu tek bir şık hamleyle şoke ettin, açıkçası.'::text,'konuşurken'::text,'konuştuğunda'::text,'konuşmuşken'::text,'O konuşurken, sen onu tek bir şık hamleyle şoke ettin, açıkçası.'::text),
(386154,42906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ..., te egyetlen elegáns lépéssel sokkoltad, őszintén.'::text,'beszélt'::text,'beszélt'::text,'beszélt'::text,'Miközben ő beszélt, te egyetlen elegáns lépéssel sokkoltad, őszintén.'::text),
(386220,42914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, angeblich ... sie ihn bis zur nächsten Runde wieder mit einem hinterhältigen Zug geschockt.'::text,'hat'::text,'wird'::text,'schockt'::text,'Warte, angeblich hat sie ihn bis zur nächsten Runde wieder mit einem hinterhältigen Zug geschockt.'::text),
(386224,42914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, кажуть, до наступного раунду вона знову ... його ще одним підступним ходом.'::text,'шокує'::text,'шокує'::text,'шокує'::text,'Стривай, кажуть, до наступного раунду вона знову шокує його ще одним підступним ходом.'::text),
(386223,42914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, dicen que para la siguiente ronda ella lo ... otra vez con otro movimiento astuto.'::text,'habrá sorprendido'::text,'sorprenderá'::text,'sorprende'::text,'Espera, dicen que para la siguiente ronda ella lo habrá sorprendido otra vez con otro movimiento astuto.'::text),
(386222,42914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, il paraît que d''ici la prochaine manche, elle ... encore avec un autre coup sournois.'::text,'l''aura choqué'::text,'le choquera'::text,'le choque'::text,'Attends, il paraît que d''ici la prochaine manche, elle l''aura choqué encore avec un autre coup sournois.'::text),
(386225,42914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duyduğuma göre bir sonraki tura kadar o, başka sinsi bir hamleyle onu yine ...'::text,'şoke etmiş olacak'::text,'şoke edecek'::text,'şoke ediyor'::text,'Dur, duyduğuma göre bir sonraki tura kadar o, başka sinsi bir hamleyle onu yine şoke etmiş olacak.'::text),
(386226,42914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt beszélik, a következő körre ő megint ... egy újabb alattomos lépéssel.'::text,'lesokkolja'::text,'sokkolni fogja'::text,'sokkolja'::text,'Várj, azt beszélik, a következő körre ő megint lesokkolja egy újabb alattomos lépéssel.'::text),
(390945,43439,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie einen seltenen Vogel ..., würde sie ihn fotografieren.'::text,'entdeckte'::text,'entdeckt'::text,'entdecken würde'::text,'Wenn sie einen seltenen Vogel entdeckte, würde sie ihn fotografieren.'::text),
(390949,43439,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ... рідкісного птаха, вона б його сфотографувала.'::text,'помітила'::text,'помічає'::text,'помітила б'::text,'Якби помітила рідкісного птаха, вона б його сфотографувала.'::text),
(390948,43439,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... un pájaro raro, ella le haría una foto.'::text,'divisara'::text,'divisa'::text,'divisaría'::text,'Si divisara un pájaro raro, ella le haría una foto.'::text),
(390947,43439,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ... un oiseau rare, elle le prendrait en photo.'::text,'repérait'::text,'repère'::text,'repérerait'::text,'Si elle repérait un oiseau rare, elle le prendrait en photo.'::text),
(390950,43439,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadir bir kuş ..., o onun fotoğrafını çekerdi.'::text,'görse'::text,'görüyor'::text,'görürdü'::text,'Nadir bir kuş görse, o onun fotoğrafını çekerdi.'::text),
(390951,43439,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ... egy ritka madarat, ő lefotózná.'::text,'kiszúrna'::text,'kiszúr'::text,'kiszúrna'::text,'Ha kiszúrna egy ritka madarat, ő lefotózná.'::text),
(352173,39131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade das ferne Ufer mit dem Fernglas ab, als sich etwas bewegte.'::text,'suchte'::text,'suchte'::text,'hat abgesucht'::text,'Sie suchte gerade das ferne Ufer mit dem Fernglas ab, als sich etwas bewegte.'::text),
(352177,39131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... далекий берег у бінокль, коли щось ворухнулося.'::text,'оглядала'::text,'оглянула'::text,'оглянула'::text,'Вона оглядала далекий берег у бінокль, коли щось ворухнулося.'::text),
(352176,39131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la orilla lejana con los prismáticos cuando algo se movió.'::text,'estaba escudriñando'::text,'escudriñó'::text,'ha escudriñado'::text,'Ella estaba escudriñando la orilla lejana con los prismáticos cuando algo se movió.'::text),
(352175,39131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la rive lointaine aux jumelles quand quelque chose a bougé.'::text,'scrutait'::text,'a scruté'::text,'a scruté'::text,'Elle scrutait la rive lointaine aux jumelles quand quelque chose a bougé.'::text),
(352178,39131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir şey kıpırdadığında o dürbünle uzak kıyıyı ...'::text,'tarıyordu'::text,'taradı'::text,'taradı'::text,'Bir şey kıpırdadığında o dürbünle uzak kıyıyı tarıyordu.'::text),
(352179,39131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő épp ... a távoli partot a távcsővel, amikor valami megmozdult.'::text,'pásztázta'::text,'végigpásztázta'::text,'végigpásztázta'::text,'Ő épp pásztázta a távoli partot a távcsővel, amikor valami megmozdult.'::text),
(352227,39137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie lässt ihr Fernglas ..., weil das ferne Ufer irgendwie verschwommen aussieht.'::text,'reparieren'::text,'reparieren'::text,'zu reparieren'::text,'Alter, sie lässt ihr Fernglas reparieren, weil das ferne Ufer irgendwie verschwommen aussieht.'::text),
(352231,39137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона віддасть свій бінокль ..., бо далекий берег виглядає якось розмито.'::text,'полагодити'::text,'лагодити'::text,'щоб полагодити'::text,'Чувак, вона віддасть свій бінокль полагодити, бо далекий берег виглядає якось розмито.'::text),
(352230,39137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella va a mandar ... los prismáticos porque la orilla lejana se ve medio borrosa.'::text,'a arreglar'::text,'arreglar'::text,'para arreglar'::text,'Tío, ella va a mandar a arreglar los prismáticos porque la orilla lejana se ve medio borrosa.'::text),
(352229,39137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle va faire ... ses jumelles parce que la rive au loin a l''air un peu floue.'::text,'réparer'::text,'réparer'::text,'de réparer'::text,'Mec, elle va faire réparer ses jumelles parce que la rive au loin a l''air un peu floue.'::text),
(352232,39137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o dürbününü ..., çünkü uzak kıyı biraz bulanık görünüyor.'::text,'tamir ettirecek'::text,'tamir edecek'::text,'tamir etmeye götürecek'::text,'Kanka, o dürbününü tamir ettirecek, çünkü uzak kıyı biraz bulanık görünüyor.'::text),
(352233,39137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... a távcsövét, mert a távoli part kicsit homályos.'::text,'megjavíttatja'::text,'megjavítja'::text,'megjavítani'::text,'Tesó, ő megjavíttatja a távcsövét, mert a távoli part kicsit homályos.'::text),
(330645,36739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade deinen Apfel auf, als dieser Riesenburger kam, und ehrlich, dein Appetit ist ikonisch.'::text,'aßt'::text,'aßt'::text,'isst'::text,'Du aßt gerade deinen Apfel auf, als dieser Riesenburger kam, und ehrlich, dein Appetit ist ikonisch.'::text),
(330649,36739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... яблуко, коли принесли той гігантський бургер, і чесно, твій апетит культовий.'::text,'доїдав'::text,'доїв'::text,'доїдаєш'::text,'Ти доїдав яблуко, коли принесли той гігантський бургер, і чесно, твій апетит культовий.'::text),
(330648,36739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... la manzana cuando llegó esa hamburguesa gigante, y sinceramente, tu apetito es icónico.'::text,'estabas terminando'::text,'has terminado'::text,'terminas'::text,'Tú estabas terminando la manzana cuando llegó esa hamburguesa gigante, y sinceramente, tu apetito es icónico.'::text),
(330647,36739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... la pomme quand ce burger géant est arrivé, et franchement, ton appétit est iconique.'::text,'finissais'::text,'as fini'::text,'finis'::text,'Tu finissais la pomme quand ce burger géant est arrivé, et franchement, ton appétit est iconique.'::text),
(330650,36739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dev burger geldiğinde sen elmayı ... ve açıkçası, iştahın efsane.'::text,'bitiriyordun'::text,'bitirdin'::text,'bitirirsin'::text,'O dev burger geldiğinde sen elmayı bitiriyordun ve açıkçası, iştahın efsane.'::text),
(330651,36739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te épp ... az almát, amikor megjött az az óriási burger, és őszintén, az étvágyad ikonikus.'::text,'fejezted be'::text,'befejezted'::text,'befejezed'::text,'Te épp fejezted be az almát, amikor megjött az az óriási burger, és őszintén, az étvágyad ikonikus.'::text),
(330726,36748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach einem Bissen vom Riesenburger hat er heute ...'::text,'einen riesigen Appetit'::text,'den riesigen Appetit'::text,'riesigen Appetit'::text,'Nach einem Bissen vom Riesenburger hat er heute einen riesigen Appetit.'::text),
(330730,36748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після одного укусу гігантського бургера він сьогодні має ...'::text,'величезний апетит'::text,'величезний апетит'::text,'величезний апетит'::text,'Після одного укусу гігантського бургера він сьогодні має величезний апетит.'::text),
(330729,36748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de un bocado de la hamburguesa gigante, él tiene hoy ...'::text,'un apetito enorme'::text,'el apetito enorme'::text,'apetito enorme'::text,'Después de un bocado de la hamburguesa gigante, él tiene hoy un apetito enorme.'::text),
(330728,36748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après une bouchée du burger géant, il a ... aujourd''hui.'::text,'un appétit énorme'::text,'l''appétit énorme'::text,'appétit énorme'::text,'Après une bouchée du burger géant, il a un appétit énorme aujourd''hui.'::text),
(330731,36748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev burgerden bir ısırıktan sonra onun bugün ... var.'::text,'müthiş bir iştahı'::text,'müthiş iştahı'::text,'müthiş iştahı'::text,'Dev burgerden bir ısırıktan sonra onun bugün müthiş bir iştahı var.'::text),
(330732,36748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy harapás után az óriási burgerből ma ... van.'::text,'hatalmas étvágya'::text,'a hatalmas étvágya'::text,'hatalmas étvágya'::text,'Egy harapás után az óriási burgerből ma hatalmas étvágya van.'::text),
(364845,40539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Meeting um 9 Uhr ... er noch eine Schicht Decken hinzugefügt.'::text,'hatte'::text,'hat'::text,'fügt'::text,'Bis zum Meeting um 9 Uhr hatte er noch eine Schicht Decken hinzugefügt.'::text),
(364849,40539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наради о 9:00 він ... ще один шар ковдр.'::text,'додав'::text,'додав'::text,'додає'::text,'До наради о 9:00 він додав ще один шар ковдр.'::text),
(364848,40539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la reunión de las 9, él ya ... otra capa de mantas.'::text,'había añadido'::text,'ha añadido'::text,'añade'::text,'Para la reunión de las 9, él ya había añadido otra capa de mantas.'::text),
(364847,40539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant la réunion de 9 h, il ... une autre couche de couvertures.'::text,'avait ajouté'::text,'a ajouté'::text,'ajoute'::text,'Avant la réunion de 9 h, il avait ajouté une autre couche de couvertures.'::text),
(364850,40539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 9 toplantısına kadar o, bir kat battaniye daha ...'::text,'eklemişti'::text,'ekledi'::text,'ekler'::text,'Saat 9 toplantısına kadar o, bir kat battaniye daha eklemişti.'::text),
(364851,40539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A reggel 9-es meetingre ő már ... még egy réteg takarót.'::text,'rátett'::text,'rátett'::text,'rátesz'::text,'A reggel 9-es meetingre ő már rátett még egy réteg takarót.'::text),
(364881,40543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich jetzt unter vielen Schichten, und nur sein Gesicht ist zu sehen.'::text,'versteckt'::text,'versteckt'::text,'hat versteckt'::text,'Er versteckt sich jetzt unter vielen Schichten, und nur sein Gesicht ist zu sehen.'::text),
(364885,40543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зараз ... під багатьма шарами, і видно лише його обличчя.'::text,'ховається'::text,'ховається'::text,'сховався'::text,'Він зараз ховається під багатьма шарами, і видно лише його обличчя.'::text),
(364884,40543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... bajo muchas capas ahora, y solo se le ve la cara.'::text,'se está escondiendo'::text,'se esconde'::text,'se ha escondido'::text,'Él se está escondiendo bajo muchas capas ahora, y solo se le ve la cara.'::text),
(364883,40543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sous plein de couches maintenant, et on ne voit que son visage.'::text,'se cache'::text,'se cache'::text,'s''est caché'::text,'Il se cache sous plein de couches maintenant, et on ne voit que son visage.'::text),
(364886,40543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şimdi birçok katmanın altında ... ve sadece yüzü görünüyor.'::text,'saklanıyor'::text,'saklanır'::text,'saklandı'::text,'O şimdi birçok katmanın altında saklanıyor ve sadece yüzü görünüyor.'::text),
(364887,40543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő most sok réteg alatt ..., és csak az arca látszik.'::text,'bujkál'::text,'bujkál'::text,'elbújt'::text,'Ő most sok réteg alatt bujkál, és csak az arca látszik.'::text),
(362199,40245,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schaffte es, die Verletzung mit einem kleinen Pflaster ...'::text,'abzudecken'::text,'abdeckend'::text,'abdecken'::text,'Er schaffte es, die Verletzung mit einem kleinen Pflaster abzudecken.'::text),
(362203,40245,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зумів ... рану маленьким пластирем.'::text,'закрити'::text,'закриття'::text,'закрити'::text,'Він зумів закрити рану маленьким пластирем.'::text),
(362202,40245,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él logró ... la herida con una tirita pequeña.'::text,'cubrir'::text,'cubriendo'::text,'cubrir'::text,'Él logró cubrir la herida con una tirita pequeña.'::text),
(362201,40245,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a réussi à ... la blessure avec un petit pansement.'::text,'couvrir'::text,'couvrant'::text,'couvrir'::text,'Il a réussi à couvrir la blessure avec un petit pansement.'::text),
(362204,40245,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, yarayı küçük bir yara bandıyla ... başardı.'::text,'kapatmayı'::text,'kapatarak'::text,'kapatmak'::text,'O, yarayı küçük bir yara bandıyla kapatmayı başardı.'::text),
(362205,40245,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő képes volt ... a sérülést egy kis sebtapasszal.'::text,'lefedni'::text,'lefedve'::text,'lefed'::text,'Ő képes volt lefedni a sérülést egy kis sebtapasszal.'::text),
(362217,40247,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... ewig ohne Verletzung Gemüse geschnitten, bevor das Messer abrutschte. Ein echter Profi.'::text,'hatte'::text,'hat'::text,'schneidet'::text,'Er hatte ewig ohne Verletzung Gemüse geschnitten, bevor das Messer abrutschte. Ein echter Profi.'::text),
(362221,40247,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... овочі цілу вічність без травм, поки не зісковзнув ніж. Справжній професіонал.'::text,'різав'::text,'ріже'::text,'ріже'::text,'Він різав овочі цілу вічність без травм, поки не зісковзнув ніж. Справжній професіонал.'::text),
(362220,40247,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... verduras durante siglos sin herirse antes de que se le resbalara el cuchillo. Todo un profesional.'::text,'había estado cortando'::text,'ha estado cortando'::text,'corta'::text,'Él había estado cortando verduras durante siglos sin herirse antes de que se le resbalara el cuchillo. Todo un profesional.'::text),
(362219,40247,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des légumes pendant une éternité sans se blesser avant que le couteau glisse. Un vrai pro.'::text,'avait coupé'::text,'a coupé'::text,'coupe'::text,'Il avait coupé des légumes pendant une éternité sans se blesser avant que le couteau glisse. Un vrai pro.'::text),
(362222,40247,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, bıçak kaymadan önce çok uzun süre yaralanmadan sebze ...; gerçek bir profesyonel.'::text,'doğramıştı'::text,'doğruyor'::text,'doğrar'::text,'O, bıçak kaymadan önce çok uzun süre yaralanmadan sebze doğramıştı; gerçek bir profesyonel.'::text),
(362223,40247,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy örökkévalóságig ... sérülés nélkül a zöldséget, mielőtt megcsúszott a kés. Igazi profi.'::text,'aprította'::text,'aprítja'::text,'aprítja'::text,'Ő egy örökkévalóságig aprította sérülés nélkül a zöldséget, mielőtt megcsúszott a kés. Igazi profi.'::text),
(388785,43199,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Visagistin ... die Streifen auf ihrer Haut, und die Katastrophe war weg!'::text,'glättete'::text,'wurde geglättet'::text,'glättend'::text,'Die Visagistin glättete die Streifen auf ihrer Haut, und die Katastrophe war weg!'::text),
(388789,43199,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візажистка ... смуги на її шкірі, і катастрофа зникла!'::text,'розгладила'::text,'була розгладжена'::text,'розгладжуючи'::text,'Візажистка розгладила смуги на її шкірі, і катастрофа зникла!'::text),
(388788,43199,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La maquilladora ... las franjas sobre su piel, y el desastre desapareció!'::text,'alisó'::text,'fue alisada'::text,'alisando'::text,'¡La maquilladora alisó las franjas sobre su piel, y el desastre desapareció!'::text),
(388787,43199,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilleuse ... les bandes sur sa peau, et la catastrophe a disparu !'::text,'a lissé'::text,'a été lissée'::text,'lissant'::text,'La maquilleuse a lissé les bandes sur sa peau, et la catastrophe a disparu !'::text),
(388790,43199,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz şeritleri cildinde ... ve felaket yok oldu!'::text,'düzeltti'::text,'düzeltildi'::text,'düzelterek'::text,'Makyöz şeritleri cildinde düzeltti ve felaket yok oldu!'::text),
(388791,43199,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sminkes ... a csíkokat a bőrén, és a katasztrófa eltűnt!'::text,'elsimította'::text,'elsimították'::text,'elsimítva'::text,'A sminkes elsimította a csíkokat a bőrén, és a katasztrófa eltűnt!'::text),
(388848,43206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Visagistin ... die Streifen mit einem Schwamm geglättet, bevor sie den Pinsel benutzte.'::text,'hatte'::text,'hat'::text,'glättet'::text,'Die Visagistin hatte die Streifen mit einem Schwamm geglättet, bevor sie den Pinsel benutzte.'::text),
(388852,43206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візажистка ... смуги губкою, перш ніж узяла пензлик.'::text,'розгладила'::text,'розгладила'::text,'розгладжує'::text,'Візажистка розгладила смуги губкою, перш ніж узяла пензлик.'::text),
(388851,43206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilladora ... las franjas con una esponja antes de usar la brocha.'::text,'había alisado'::text,'ha alisado'::text,'está alisando'::text,'La maquilladora había alisado las franjas con una esponja antes de usar la brocha.'::text),
(388850,43206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilleuse ... les bandes avec une éponge avant d''utiliser le pinceau.'::text,'avait lissé'::text,'a lissé'::text,'est en train de lisser'::text,'La maquilleuse avait lissé les bandes avec une éponge avant d''utiliser le pinceau.'::text),
(388853,43206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz, fırçayı kullanmadan önce şeritleri süngerle ...'::text,'düzeltmişti'::text,'düzeltti'::text,'düzeltiyor'::text,'Makyöz, fırçayı kullanmadan önce şeritleri süngerle düzeltmişti.'::text),
(388854,43206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sminkes ... a csíkokat egy szivaccsal, mielőtt az ecsetet használta.'::text,'elsimította'::text,'elsimította'::text,'simítja'::text,'A sminkes elsimította a csíkokat egy szivaccsal, mielőtt az ecsetet használta.'::text),
(395391,43933,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sichtlich am Leiden: Er ... gerade den Geschmack seines Smoothies, als das Grinsen auftauchte.'::text,'genoss'::text,'genoss'::text,'hat genossen'::text,'Sichtlich am Leiden: Er genoss gerade den Geschmack seines Smoothies, als das Grinsen auftauchte.'::text),
(395395,43933,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно страждає: він ... смаком свого смузі, коли з''явилася усмішка.'::text,'насолоджувався'::text,'насолодився'::text,'насолодився'::text,'Явно страждає: він насолоджувався смаком свого смузі, коли з''явилася усмішка.'::text),
(395394,43933,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente sufriendo: él ... el sabor de su smoothie cuando apareció la sonrisa.'::text,'estaba disfrutando'::text,'disfrutó'::text,'ha disfrutado'::text,'Claramente sufriendo: él estaba disfrutando el sabor de su smoothie cuando apareció la sonrisa.'::text),
(395393,43933,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement en souffrance : il ... le goût de son smoothie quand le sourire est apparu.'::text,'savourait'::text,'a savouré'::text,'a savouré'::text,'Clairement en souffrance : il savourait le goût de son smoothie quand le sourire est apparu.'::text),
(395396,43933,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki acı çekiyor: sırıtma belirdiğinde o smoothiesinin tadını ...'::text,'çıkarıyordu'::text,'çıkardı'::text,'çıkardı'::text,'Belli ki acı çekiyor: sırıtma belirdiğinde o smoothiesinin tadını çıkarıyordu.'::text),
(395397,43933,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen szenved: ő épp ... a smoothie-ja ízét, amikor megjelent a vigyor.'::text,'élvezte'::text,'élvezte'::text,'élvezte'::text,'Egyértelműen szenved: ő épp élvezte a smoothie-ja ízét, amikor megjelent a vigyor.'::text),
(395481,43943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast mit dieser Mango ... dieses Smoothies perfekt gemacht.'::text,'den Geschmack'::text,'einen Geschmack'::text,'Geschmack'::text,'Ehrlich, du hast mit dieser Mango den Geschmack dieses Smoothies perfekt gemacht.'::text),
(395485,43943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти зробив ... цього смузі ідеальним завдяки тому манго.'::text,'смак'::text,'смак'::text,'смак'::text,'Чесно, ти зробив смак цього смузі ідеальним завдяки тому манго.'::text),
(395484,43943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú hiciste perfecto ... de este smoothie con ese mango.'::text,'el sabor'::text,'un sabor'::text,'sabor'::text,'Sinceramente, tú hiciste perfecto el sabor de este smoothie con ese mango.'::text),
(395483,43943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as rendu ... de ce smoothie parfait avec cette mangue.'::text,'le goût'::text,'un goût'::text,'goût'::text,'Franchement, tu as rendu le goût de ce smoothie parfait avec cette mangue.'::text),
(395486,43943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen o mangoyla bu smoothienin ... mükemmel yaptın.'::text,'tadını'::text,'bir tadını'::text,'tadını'::text,'Açıkçası, sen o mangoyla bu smoothienin tadını mükemmel yaptın.'::text),
(395487,43943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te azzal a mangóval tökéletessé tetted ... ennek a smoothie-nak.'::text,'az ízét'::text,'egy ízét'::text,'ízét'::text,'Őszintén, te azzal a mangóval tökéletessé tetted az ízét ennek a smoothie-nak.'::text),
(335253,37251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie die Augenbinden abnahmen, ... die blinden Spieler schon die Hälfte der Luftschlangen heruntergerissen.'::text,'hatten'::text,'haben'::text,'rissen'::text,'Als sie die Augenbinden abnahmen, hatten die blinden Spieler schon die Hälfte der Luftschlangen heruntergerissen.'::text),
(335257,37251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони зняли пов''язки з очей, сліпі гравці ... половину серпантину.'::text,'зірвали'::text,'зірвали'::text,'зривали'::text,'Поки вони зняли пов''язки з очей, сліпі гравці зірвали половину серпантину.'::text),
(335256,37251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se quitaron las vendas, los jugadores ciegos ya ... la mitad de las serpentinas.'::text,'habían arrancado'::text,'han arrancado'::text,'arrancaron'::text,'Para cuando se quitaron las vendas, los jugadores ciegos ya habían arrancado la mitad de las serpentinas.'::text),
(335255,37251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où ils ont enlevé les bandeaux, les joueurs aveugles ... la moitié des serpentins.'::text,'avaient arraché'::text,'ont arraché'::text,'ont arraché'::text,'Au moment où ils ont enlevé les bandeaux, les joueurs aveugles avaient arraché la moitié des serpentins.'::text),
(335258,37251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar göz bantlarını çıkardığında, kör oyuncular süslerin yarısını çoktan ...'::text,'indirmişti'::text,'indirdi'::text,'indirdi'::text,'Onlar göz bantlarını çıkardığında, kör oyuncular süslerin yarısını çoktan indirmişti.'::text),
(335259,37251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire levették a szemkötőket, a vak játékosok a szalagok felét már ...'::text,'letépték'::text,'letépték'::text,'letépték'::text,'Mire levették a szemkötőket, a vak játékosok a szalagok felét már letépték.'::text),
(335307,37257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass sie schon eine Stunde blind ..., als die Augenbinden abkamen.'::text,'herumgestolpert waren'::text,'herumstolperten'::text,'herumgestolpert sind'::text,'Hör mal, ich hab gehört, dass sie schon eine Stunde blind herumgestolpert waren, als die Augenbinden abkamen.'::text),
(335311,37257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вони ... наосліп уже годину, коли зняли пов''язки.'::text,'спотикалися'::text,'спотикалися'::text,'спотикаються'::text,'Слухай, я чула, що вони спотикалися наосліп уже годину, коли зняли пов''язки.'::text),
(335310,37257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, yo he oído que ellos ... a ciegas durante una hora cuando se quitaron las vendas.'::text,'habían estado tropezando'::text,'estaban tropezando'::text,'han estado tropezando'::text,'Oye, yo he oído que ellos habían estado tropezando a ciegas durante una hora cuando se quitaron las vendas.'::text),
(335309,37257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''ils ... à l''aveugle depuis une heure quand les bandeaux sont tombés.'::text,'trébuchaient'::text,'trébuchaient'::text,'ont trébuché'::text,'Écoute, j''ai entendu dire qu''ils trébuchaient à l''aveugle depuis une heure quand les bandeaux sont tombés.'::text),
(335312,37257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben duydum ki göz bantları çıktığında onlar bir saattir körlemesine ...'::text,'sendeliyorlarmış'::text,'sendeliyorlardı'::text,'sendeliyorlar'::text,'Dinle, ben duydum ki göz bantları çıktığında onlar bir saattir körlemesine sendeliyorlarmış.'::text),
(335313,37257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én úgy hallottam, hogy ők már egy órája ... vakon, amikor lekerültek a szemkötők.'::text,'botladoztak'::text,'botladoztak'::text,'botladoznak'::text,'Figyelj, én úgy hallottam, hogy ők már egy órája botladoztak vakon, amikor lekerültek a szemkötők.'::text),
(398532,44282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie konnte es nicht vermeiden, mitten auf dieser Albtraumwanderung eine Behandlung ...!'::text,'zu bekommen'::text,'zu bekommen'::text,'bekommen'::text,'Sie konnte es nicht vermeiden, mitten auf dieser Albtraumwanderung eine Behandlung zu bekommen!'::text),
(398536,44282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не змогла уникнути ... допомоги посеред цього кошмарного походу!'::text,'отримання'::text,'отримати'::text,'отримати'::text,'Вона не змогла уникнути отримання допомоги посеред цього кошмарного походу!'::text),
(398535,44282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella no pudo evitar ... tratamiento en medio de esta caminata de pesadilla!'::text,'recibir'::text,'recibir'::text,'recibir'::text,'¡Ella no pudo evitar recibir tratamiento en medio de esta caminata de pesadilla!'::text),
(398534,44282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''a pas pu éviter de ... des soins au milieu de cette rando cauchemardesque !'::text,'recevoir'::text,'recevoir'::text,'recevoir'::text,'Elle n''a pas pu éviter de recevoir des soins au milieu de cette rando cauchemardesque !'::text),
(398537,44282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, bu kâbus gibi yürüyüşün ortasında tedavi ... kaçamadı!'::text,'olmaktan'::text,'olmaya'::text,'ol'::text,'O, bu kâbus gibi yürüyüşün ortasında tedavi olmaktan kaçamadı!'::text),
(398538,44282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő nem tudta elkerülni, hogy ... kezelést ennek a rémálomszerű túrának a közepén!'::text,'kapjon'::text,'kapjon'::text,'kap'::text,'Ő nem tudta elkerülni, hogy kapjon kezelést ennek a rémálomszerű túrának a közepén!'::text),
(398595,44289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine entspannte Wanderung, klar. Das Pflaster war ... im ganzen Rucksack.'::text,'die einzige Behandlung'::text,'eine einzige Behandlung'::text,'einzige Behandlung'::text,'Eine entspannte Wanderung, klar. Das Pflaster war die einzige Behandlung im ganzen Rucksack.'::text),
(398599,44289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розслаблювальний похід, звісно. Пластир був ... в усьому рюкзаку.'::text,'єдиними ліками'::text,'єдиними ліками'::text,'єдиними ліками'::text,'Розслаблювальний похід, звісно. Пластир був єдиними ліками в усьому рюкзаку.'::text),
(398598,44289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una caminata relajante, obviamente. La tirita era ... en toda la mochila.'::text,'el único tratamiento'::text,'un único tratamiento'::text,'único tratamiento'::text,'Una caminata relajante, obviamente. La tirita era el único tratamiento en toda la mochila.'::text),
(398597,44289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une rando reposante, évidemment. Le pansement était ... dans tout le sac.'::text,'le seul soin'::text,'un seul soin'::text,'seul soin'::text,'Une rando reposante, évidemment. Le pansement était le seul soin dans tout le sac.'::text),
(398600,44289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahatlatıcı bir yürüyüş, tabii ki. Bütün çantadaki ... yara bandıydı.'::text,'tek tedavi'::text,'bir tek tedavi'::text,'tek tedavi'::text,'Rahatlatıcı bir yürüyüş, tabii ki. Bütün çantadaki tek tedavi yara bandıydı.'::text),
(398601,44289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pihentető túra, nyilván. A sebtapasz volt ... az egész hátizsákban.'::text,'az egyetlen kezelés'::text,'egy egyetlen kezelés'::text,'egyetlen kezelés'::text,'Pihentető túra, nyilván. A sebtapasz volt az egyetlen kezelés az egész hátizsákban.'::text),
(335397,37267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast dem Hirten gesagt, seine Schafe ... deinen Transporter. Ehrlich, ikonische Warnweste.'::text,'blockierten'::text,'blockieren'::text,'blockiert'::text,'Du hast dem Hirten gesagt, seine Schafe blockierten deinen Transporter. Ehrlich, ikonische Warnweste.'::text),
(335401,37267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказав пастуху, що його вівці ... твій фургон. Чесно, культовий світловідбивний жилет.'::text,'блокують'::text,'блокують'::text,'блокує'::text,'Ти сказав пастуху, що його вівці блокують твій фургон. Чесно, культовий світловідбивний жилет.'::text),
(335400,37267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú le dijiste al pastor que sus ovejas ... tu furgoneta. Sinceramente, un chaleco reflectante icónico.'::text,'estaban bloqueando'::text,'están bloqueando'::text,'bloquea'::text,'Tú le dijiste al pastor que sus ovejas estaban bloqueando tu furgoneta. Sinceramente, un chaleco reflectante icónico.'::text),
(335399,37267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit au berger que ses moutons ... ta camionnette. Franchement, gilet fluo iconique.'::text,'bloquaient'::text,'bloquent'::text,'bloque'::text,'Tu as dit au berger que ses moutons bloquaient ta camionnette. Franchement, gilet fluo iconique.'::text),
(335402,37267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen çobana koyunlarının kamyonetini ... söyledin. Açıkçası, efsane reflektörlü yelek.'::text,'kapattığını'::text,'kapattığını'::text,'kapatıyor'::text,'Sen çobana koyunlarının kamyonetini kapattığını söyledin. Açıkçası, efsane reflektörlü yelek.'::text),
(335403,37267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te azt mondtad a pásztornak, hogy a juhai ... a furgonodat. Őszintén, ikonikus láthatósági mellény.'::text,'elállják'::text,'elállják'::text,'elállja'::text,'Te azt mondtad a pásztornak, hogy a juhai elállják a furgonodat. Őszintén, ikonikus láthatósági mellény.'::text),
(393402,43712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst nach einem langen Kampf ... den Gipfel des Hügels.'::text,'erreichte er'::text,'er erreichte'::text,'konnte er erreichen'::text,'Erst nach einem langen Kampf erreichte er den Gipfel des Hügels.'::text),
(393406,43712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише після довгої боротьби він ... вершини пагорба.'::text,'дістався'::text,'дістався'::text,'зміг дістатися'::text,'Лише після довгої боротьби він дістався вершини пагорба.'::text),
(393405,43712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo después de una larga lucha él ... a la cima de la colina.'::text,'llegó'::text,'llegó'::text,'pudo llegar'::text,'Solo después de una larga lucha él llegó a la cima de la colina.'::text),
(393404,43712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est qu''après une longue lutte qu''il ... le sommet de la colline.'::text,'a atteint'::text,'a atteint'::text,'a pu atteindre'::text,'Ce n''est qu''après une longue lutte qu''il a atteint le sommet de la colline.'::text),
(393407,43712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak uzun bir mücadeleden sonra o tepenin zirvesine ...'::text,'ulaştı'::text,'ulaştı'::text,'ulaşabildi'::text,'Ancak uzun bir mücadeleden sonra o tepenin zirvesine ulaştı.'::text),
(393408,43712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak hosszú küzdelem után ... ő a domb tetejére.'::text,'ért fel'::text,'ért fel'::text,'tudott felérni'::text,'Csak hosszú küzdelem után ért fel ő a domb tetejére.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
